/* 자동 생성 — tools/build_data.py. 직접 고치지 마세요. */
(window.TS_DATA = window.TS_DATA || {}).p3 = [{"id":"p3-001","level":1,"topic":"복사기 고장","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, Mark. The copy machine on our floor isn't working again."},{"s":"M","t":"Oh no. I need to make copies for the two o'clock meeting."},{"s":"W","t":"You can use the one on the third floor. It works fine."},{"s":"M","t":"Good idea. Did you call someone to fix ours?"},{"s":"W","t":"Yes, I called the repair company this morning. A technician is coming at four."},{"s":"M","t":"Great. I'll go upstairs now, then."}],"graphic":null,"questions":[{"q":"What problem are the speakers discussing?","choices":["A meeting was canceled by the manager.","A floor is closed.","A machine is out of order.","A phone call was missed."],"answer":2,"type":"주제·목적","explanation":"여자가 첫 대사에서 \"The copy machine on our floor isn't working again.\"이라고 했으므로 기계가 고장 난 것이 문제다. 회의(meeting)와 층(floor)은 대화에 나온 단어를 이용한 오답이다."},{"q":"When will a technician arrive?","choices":["At two o'clock","At four o'clock","At three o'clock","This morning"],"answer":1,"type":"세부 사항","explanation":"여자가 \"A technician is coming at four.\"라고 했으므로 4시가 정답이다. 2시는 회의 시각, 오늘 아침(this morning)은 수리 업체에 전화한 때, 3은 층 번호이다."},{"q":"What will the man do next?","choices":["Go to another floor","Call a repair company","Cancel a meeting","Fix a machine himself"],"answer":0,"type":"다음 할 일","explanation":"남자가 마지막에 \"I'll go upstairs now.\"라고 했으므로 다른 층으로 갈 것이다. 수리 업체에 전화한 사람은 여자이므로 오답이다."}],"translation":"W: 안녕하세요, 마크. 우리 층 복사기가 또 작동하지 않아요.\nM: 이런. 2시 회의 자료를 복사해야 하는데요.\nW: 3층에 있는 복사기를 쓰시면 돼요. 그건 잘 작동해요.\nM: 좋은 생각이네요. 우리 복사기 고쳐 줄 사람한테 연락했나요?\nW: 네, 오늘 아침에 수리 업체에 전화했어요. 기술자가 4시에 올 거예요.\nM: 잘됐네요. 그럼 지금 위층으로 올라갈게요.","part":3},{"id":"p3-002","level":1,"topic":"식당 예약","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hello, I'd like to book a table for dinner tomorrow."},{"s":"W","t":"Sure. How many people will be in your group?"},{"s":"M","t":"There will be six of us. Around seven o'clock, please."},{"s":"W","t":"Let me check. Yes, we have a table for six at seven."},{"s":"M","t":"Great. Can we sit near the window?"},{"s":"W","t":"Of course. May I have your name and phone number, please?"}],"graphic":null,"questions":[{"q":"Where does the woman most likely work?","choices":["At a hotel","At a travel agency","At a phone store","At a restaurant"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"남자가 \"I'd like to book a table for dinner tomorrow.\"라며 저녁 식사 자리를 예약하고 여자가 좌석을 확인해 주므로 여자는 식당 직원이다. 전화번호(phone number)라는 말만 듣고 휴대폰 매장을 고르면 안 된다."},{"q":"How many people will be in the man's group?","choices":["Six","Two","Seven","Ten"],"answer":0,"type":"세부 사항","explanation":"남자가 \"There will be six of us.\"라고 했으므로 6명이다. 7(seven)은 예약 시각이므로 함정이다."},{"q":"What does the woman ask for?","choices":["Contact information","A deposit","A menu choice","A window seat"],"answer":0,"type":"요청·제안","explanation":"여자가 마지막에 \"May I have your name and phone number?\"라고 했으므로 연락처를 요청한 것이다. 창가 자리(window seat)는 남자가 요청한 것이다."}],"translation":"M: 안녕하세요, 내일 저녁 식사 자리를 예약하고 싶어요.\nW: 네. 일행이 몇 분이신가요?\nM: 여섯 명이에요. 7시쯤으로 부탁해요.\nW: 확인해 볼게요. 네, 7시에 6인석이 있습니다.\nM: 좋아요. 창가 쪽에 앉을 수 있을까요?\nW: 물론이죠. 성함과 전화번호를 알려 주시겠어요?","part":3},{"id":"p3-003","level":1,"topic":"신입 직원 첫 출근","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Excuse me, I'm Daniel. Today is my first day in the sales department."},{"s":"W","t":"Welcome, Daniel! I'm Susan, the office manager. Let me show you your desk."},{"s":"M","t":"Thank you. Where should I put my coat?"},{"s":"W","t":"There's a closet next to the kitchen. And here's your ID card."},{"s":"M","t":"Thanks. When do I get my computer?"},{"s":"W","t":"Someone from the IT team will bring it after lunch."}],"graphic":null,"questions":[{"q":"Who most likely is the man?","choices":["An office manager","A new employee","An IT worker","A sales customer"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"남자가 \"Today is my first day in the sales department.\"라고 했으므로 신입 직원이다. 사무실 관리자는 여자(Susan)이고, IT팀과 영업(sales)은 대화 속 단어를 이용한 오답이다."},{"q":"What does the woman give the man?","choices":["A coat","A computer","An identification card","A lunch menu"],"answer":2,"type":"세부 사항","explanation":"여자가 \"here's your ID card\"라며 사원증을 건넨다. ID card를 identification card로 바꿔 표현했다. 컴퓨터는 점심 후에 IT팀이 가져온다."},{"q":"According to the woman, what will happen after lunch?","choices":["A meeting will begin.","A device will be delivered.","The kitchen will be cleaned.","The man will meet a client."],"answer":1,"type":"세부 사항","explanation":"여자가 \"Someone from the IT team will bring it after lunch.\"라고 했고 it은 컴퓨터이므로 기기가 전달될 것이다. 탕비실(kitchen)은 옷장 위치를 말할 때 나온 단어다."}],"translation":"M: 실례합니다, 저는 다니엘입니다. 오늘이 영업부 첫 출근 날이에요.\nW: 환영해요, 다니엘! 저는 사무실 관리자 수잔이에요. 자리를 안내해 드릴게요.\nM: 감사합니다. 코트는 어디에 두면 될까요?\nW: 탕비실 옆에 옷장이 있어요. 그리고 여기 사원증이요.\nM: 감사합니다. 컴퓨터는 언제 받을 수 있나요?\nW: IT팀 직원이 점심 후에 가져다줄 거예요.","part":3},{"id":"p3-004","level":1,"topic":"택배 미도착 문의","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, I ordered a desk lamp from your online store last week, but it hasn't arrived yet."},{"s":"M","t":"I'm sorry about that. Can you tell me your order number?"},{"s":"W","t":"Yes, it's five, two, seven, one."},{"s":"M","t":"Thank you. It looks like the package was sent to your old address."},{"s":"W","t":"Oh, I moved last month. I forgot to change it."},{"s":"M","t":"No problem. I'll send a new lamp to your new address today, free of charge."}],"graphic":null,"questions":[{"q":"Why is the woman calling?","choices":["To order a lamp","To ask about a delivery","To change her phone number","To return a desk"],"answer":1,"type":"주제·목적","explanation":"여자가 \"it hasn't arrived yet\"이라며 주문한 물건이 오지 않았다고 문의하므로 배송 문의 전화다. 스탠드는 지난주에 이미 주문했으므로 주문하려는 것이 아니다."},{"q":"What was the problem?","choices":["An old address was used.","The item was damaged.","The order number was wrong.","The store was closed."],"answer":0,"type":"세부 사항","explanation":"남자가 \"the package was sent to your old address\"라고 했으므로 예전 주소로 발송된 것이 문제다. 주문 번호는 정상적으로 확인되었다."},{"q":"What will the man do?","choices":["Give a refund","Visit the woman's home","Call a delivery driver","Send another item"],"answer":3,"type":"다음 할 일","explanation":"남자가 \"I'll send a new lamp to your new address today\"라고 했으므로 물건을 다시 보낼 것이다. free of charge(무료)라는 말을 환불로 착각하면 안 된다."}],"translation":"W: 안녕하세요, 지난주에 온라인 매장에서 책상 스탠드를 주문했는데 아직 도착하지 않았어요.\nM: 죄송합니다. 주문 번호를 알려 주시겠어요?\nW: 네, 5271이에요.\nM: 감사합니다. 택배가 예전 주소로 발송된 것 같네요.\nW: 아, 제가 지난달에 이사했어요. 주소 바꾸는 걸 잊었네요.\nM: 괜찮습니다. 오늘 새 주소로 새 스탠드를 무료로 보내 드릴게요.","part":3},{"id":"p3-005","level":1,"topic":"회의실 예약","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Linda, is the large meeting room free on Thursday morning?"},{"s":"W","t":"Let me look. No, the marketing team is using it until noon."},{"s":"M","t":"Hmm. I have a meeting with a client at ten."},{"s":"W","t":"How about the small room on the second floor? It's free all day."},{"s":"M","t":"That's fine. There are only three of us."},{"s":"W","t":"OK. I'll reserve it for you now."}],"graphic":null,"questions":[{"q":"What does the man want to do?","choices":["Meet the marketing team","Move to the second floor","Use a meeting room","Find a new client"],"answer":2,"type":"주제·목적","explanation":"남자가 \"is the large meeting room free on Thursday morning?\"이라며 고객 회의에 쓸 회의실을 찾고 있다. 마케팅팀과 2층은 대화에 나온 단어를 이용한 오답이다."},{"q":"Why is the large room unavailable?","choices":["It is being cleaned.","Another group is using it.","It is too small.","It is closed on Thursdays."],"answer":1,"type":"세부 사항","explanation":"여자가 \"the marketing team is using it until noon\"이라고 했으므로 다른 팀이 사용 중이기 때문이다. 작은 것은 2층 소회의실이다."},{"q":"What will the woman do next?","choices":["Call a client","Clean a room","Cancel a meeting","Make a reservation"],"answer":3,"type":"다음 할 일","explanation":"여자가 마지막에 \"I'll reserve it for you now.\"라고 했으므로 예약을 할 것이다. reserve를 make a reservation으로 바꿔 표현했다."}],"translation":"M: 린다, 목요일 오전에 대회의실 비어 있나요?\nW: 확인해 볼게요. 아니요, 마케팅팀이 정오까지 사용해요.\nM: 음. 저는 10시에 고객과 회의가 있는데요.\nW: 2층 소회의실은 어때요? 그곳은 하루 종일 비어 있어요.\nM: 좋아요. 우리는 세 명뿐이에요.\nW: 알겠어요. 지금 예약해 드릴게요.","part":3},{"id":"p3-006","level":2,"topic":"출장 항공편 취소","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, Kevin. I just got an e-mail from the airline. Our flight to Chicago on Monday has been canceled."},{"s":"M","t":"Really? We have to be there for the trade show on Tuesday morning."},{"s":"W","t":"I know. The airline offered us seats on a flight Monday evening, but it doesn't land until midnight."},{"s":"M","t":"That's too late. What about taking the train instead?"},{"s":"W","t":"The train takes about six hours, but it leaves at nine in the morning."},{"s":"M","t":"That works. We could even prepare our presentation on the way."},{"s":"W","t":"Good point. I'll book two train tickets right now."}],"graphic":null,"questions":[{"q":"What are the speakers mainly discussing?","choices":["Setting up a trade show booth","Canceling a presentation","Changing their travel arrangements","Choosing a hotel"],"answer":2,"type":"주제·목적","explanation":"항공편이 취소되어(\"Our flight to Chicago on Monday has been canceled\") 다른 이동 방법을 찾는 대화이므로 출장 이동 계획 변경이 주제다. 발표(presentation)는 기차에서 준비하겠다고 했을 뿐 취소하는 것이 아니다."},{"q":"Why does the man reject the airline's offer?","choices":["The ticket is too expensive for their budget.","The flight would arrive too late.","The flight leaves too early.","The seats are not together."],"answer":1,"type":"세부 사항","explanation":"여자가 대체 항공편은 \"doesn't land until midnight\"이라고 하자 남자가 \"That's too late.\"라고 답했다. 도착이 너무 늦다는 것이 거절 이유이다."},{"q":"What will the woman do next?","choices":["Purchase train tickets","E-mail the airline","Practice a presentation","Call a trade show organizer"],"answer":0,"type":"다음 할 일","explanation":"여자가 \"I'll book two train tickets right now.\"라고 했으므로 기차표를 구매할 것이다. 이메일은 항공사에서 받은 것이다."}],"translation":"W: 안녕하세요, 케빈. 방금 항공사에서 이메일을 받았어요. 월요일 시카고행 항공편이 취소됐대요.\nM: 정말요? 우리는 화요일 아침 무역 박람회에 가야 하잖아요.\nW: 그러니까요. 항공사가 월요일 저녁 비행기 좌석을 제안했는데, 자정이 되어야 도착해요.\nM: 그건 너무 늦어요. 대신 기차를 타는 건 어때요?\nW: 기차는 여섯 시간 정도 걸리지만 아침 9시에 출발해요.\nM: 그거 괜찮네요. 가는 동안 발표 준비도 할 수 있겠어요.\nW: 좋은 지적이에요. 지금 바로 기차표 두 장을 예매할게요.","part":3},{"id":"p3-007","level":2,"topic":"사무용 의자 주문 재고 부족","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Good morning, this is Brian from Lakeside Dental Clinic. I'm calling about the office chairs we ordered."},{"s":"W","t":"Hello, Brian. Let me find your order. You ordered eight black chairs, right?"},{"s":"M","t":"That's right. They were supposed to arrive yesterday."},{"s":"W","t":"I'm sorry. We only have five black chairs in stock right now. The rest will come from the factory next week."},{"s":"M","t":"Hmm, we're opening our new waiting room this Friday."},{"s":"W","t":"In that case, we have gray chairs of the same model available now. Would those work?"},{"s":"M","t":"Actually, gray might match our new walls better. Please send eight gray ones."}],"graphic":null,"questions":[{"q":"Where does the man work?","choices":["At a furniture factory","At a paint store","At a delivery company","At a medical office"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"남자가 \"this is Brian from Lakeside Dental Clinic\"이라고 소개했으므로 치과, 즉 의료 기관에서 일한다. 공장(factory)과 벽(walls)은 대화 속 단어를 이용한 오답이다."},{"q":"What problem does the woman mention?","choices":["A price has increased.","Not enough items are available.","A chair was damaged.","A delivery address is wrong."],"answer":1,"type":"세부 사항","explanation":"여자가 \"We only have five black chairs in stock right now.\"라고 했으므로 재고가 부족한 것이 문제다. in stock이 부족하다는 내용을 not enough items are available로 바꿔 표현했다."},{"q":"What does the man ask the woman to do?","choices":["Wait until next week","Cancel his order","Send products in a different color","Paint the walls"],"answer":2,"type":"요청·제안","explanation":"남자가 \"Please send eight gray ones.\"라며 검은색 대신 회색 의자를 보내 달라고 했다. 다음 주에 공장에서 오는 것은 검은색 의자이고, 남자는 기다리지 않기로 했다."}],"translation":"M: 안녕하세요, 레이크사이드 치과의 브라이언입니다. 주문한 사무용 의자 때문에 전화드렸어요.\nW: 안녕하세요, 브라이언. 주문을 찾아볼게요. 검은색 의자 여덟 개 주문하셨죠?\nM: 맞아요. 어제 도착하기로 되어 있었어요.\nW: 죄송합니다. 지금 검은색 의자가 다섯 개밖에 재고가 없어요. 나머지는 다음 주에 공장에서 와요.\nM: 음, 저희가 이번 금요일에 새 대기실을 여는데요.\nW: 그렇다면 같은 모델의 회색 의자는 지금 바로 있어요. 그걸로 괜찮으시겠어요?\nM: 사실 회색이 새 벽과 더 잘 어울릴 것 같네요. 회색으로 여덟 개 보내 주세요.","part":3},{"id":"p3-008","level":2,"topic":"사무실 이전 준비","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"Jason, Tom, thanks for coming. As you know, we're moving to the new office next month."},{"s":"M","t":"Yes. Do we know exactly when?"},{"s":"W","t":"The movers are coming on the fifteenth. So I need everyone to pack their desks by the fourteenth."},{"s":"M2","t":"Will the company provide boxes?"},{"s":"W","t":"Yes, Tom. They'll be delivered to the storage room on Monday."},{"s":"M","t":"What about our computers? Should we pack them too?"},{"s":"W","t":"No, the IT team will handle all the computers. Just pack your papers and personal items."},{"s":"M2","t":"OK. I'll let the rest of my team know this afternoon."}],"graphic":null,"questions":[{"q":"What is the conversation mainly about?","choices":["A computer upgrade","An office relocation","A storage room renovation","A team reorganization"],"answer":1,"type":"주제·목적","explanation":"여자가 \"we're moving to the new office next month\"라며 이사 준비를 안내하므로 사무실 이전이 주제다. 컴퓨터와 창고는 세부 내용에 나온 단어일 뿐이다."},{"q":"Where will boxes be available?","choices":["In a storage room","At the new office","In the IT department","At the front desk"],"answer":0,"type":"세부 사항","explanation":"상자를 주느냐는 질문에 여자가 \"they'll be delivered to the storage room on Monday\"라고 답했다. IT팀은 컴퓨터를 처리하는 부서이다."},{"q":"What does Tom say he will do this afternoon?","choices":["Pack his computer","Order some boxes","Inform his coworkers","Call a moving company"],"answer":2,"type":"다음 할 일","explanation":"상자에 대해 물은 두 번째 남자에게 여자가 \"Yes, Tom\"이라고 답했으므로 그가 톰이다. 톰이 마지막에 \"I'll let the rest of my team know this afternoon.\"이라고 했다. 팀원들에게 알리겠다는 것을 inform his coworkers로 바꿔 표현했다. 컴퓨터는 싸지 말라고 했다."}],"translation":"W: 제이슨, 톰, 와 줘서 고마워요. 알다시피 우리는 다음 달에 새 사무실로 이사해요.\nM: 네. 정확히 언제인지 정해졌나요?\nW: 이삿짐 업체가 15일에 와요. 그래서 모두 14일까지 책상 짐을 싸야 해요.\nM2: 회사에서 상자를 주나요?\nW: 네, 톰. 월요일에 창고로 배달될 거예요.\nM: 컴퓨터는요? 그것도 싸야 하나요?\nW: 아니요, 컴퓨터는 모두 IT팀이 처리할 거예요. 서류와 개인 물품만 싸면 돼요.\nM2: 알겠어요. 오늘 오후에 제 팀원들에게 알릴게요.","part":3},{"id":"p3-009","level":2,"topic":"직원 교육 일정","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, Rachel. Are you going to the training sessions on Friday?"},{"s":"W","t":"Yes, I signed up for the morning ones. How about you?"},{"s":"M","t":"I wanted to take the software session, but I have a call with a client at ten thirty."},{"s":"W","t":"That's too bad. That one is really important for our team."},{"s":"M","t":"I know. I'm going to ask my manager if the trainer can repeat it next week."},{"s":"W","t":"Good idea. In the meantime, I'll take notes for you."},{"s":"M","t":"Thanks. I'll go to the e-mail writing session in the afternoon instead."}],"graphic":{"title":"Employee Training — Friday, May 10","rows":[["Time","Session","Room"],["9:00","Customer Service Basics","Room A"],["10:30","Using the New Sales Software","Room B"],["1:00","Time Management","Room A"],["2:30","Writing Business E-mails","Room C"]]},"questions":[{"q":"Why can't the man attend a session?","choices":["He has to speak with a customer.","He has to train new staff.","He will be on vacation for the whole week.","He has to write a report."],"answer":0,"type":"세부 사항","explanation":"남자가 \"I have a call with a client at ten thirty\"라고 했으므로 고객과 통화해야 하기 때문이다. call with a client를 speak with a customer로 바꿔 표현했다."},{"q":"What does the woman offer to do?","choices":["Call the trainer","Change the man's schedule","Reserve a room","Share what she learns"],"answer":3,"type":"요청·제안","explanation":"여자가 \"I'll take notes for you.\"라며 필기해 주겠다고 했으므로 배운 내용을 공유하겠다는 제안이다. 강사에게 다시 해 달라고 부탁하는 것은 남자가 매니저에게 물어볼 일이다."},{"q":"Look at the graphic. What time will the man's session begin?","choices":["At 2:30","At 9:00","At 10:30","At 1:00"],"answer":0,"type":"시각 자료 연계","explanation":"남자는 \"I'll go to the e-mail writing session in the afternoon instead.\"라고 했다. 표에서 Writing Business E-mails 세션은 2:30에 시작한다. 10:30은 남자가 통화 때문에 못 가는 소프트웨어 세션 시각이다."}],"translation":"M: 안녕하세요, 레이첼. 금요일 교육 세션에 가세요?\nW: 네, 오전 세션들을 신청했어요. 당신은요?\nM: 소프트웨어 세션을 듣고 싶었는데, 10시 30분에 고객과 통화가 있어요.\nW: 아쉽네요. 그 세션은 우리 팀에 정말 중요한데요.\nM: 그러니까요. 강사가 다음 주에 한 번 더 할 수 있는지 매니저에게 물어보려고요.\nW: 좋은 생각이에요. 그동안 제가 필기를 해 둘게요.\nM: 고마워요. 대신 오후에 이메일 작성 세션에 갈게요.","part":3},{"id":"p3-010","level":2,"topic":"컨퍼런스 단체 등록","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hello, I'm calling about the Regional Marketing Conference in October. Is registration still open?"},{"s":"M","t":"Yes, it is. The fee is two hundred dollars per person."},{"s":"W","t":"I see. I'd like to register five people from my company. Is there a group discount?"},{"s":"M","t":"Yes. Groups of four or more get twenty percent off."},{"s":"W","t":"That's great. Can I pay by credit card over the phone?"},{"s":"M","t":"I'm afraid not. You'll need to fill out the form on our Web site. You can pay there."},{"s":"W","t":"OK, I'll do that this afternoon."}],"graphic":null,"questions":[{"q":"What is the purpose of the call?","choices":["To cancel a registration","To speak at a conference","To sign up for an event","To book a hotel room"],"answer":2,"type":"주제·목적","explanation":"여자가 \"Is registration still open?\"이라고 묻고 다섯 명을 등록하고 싶다고 했으므로 행사 등록이 목적이다. register를 sign up으로 바꿔 표현했다."},{"q":"What is available for groups?","choices":["A reduced price","Free parking","Reserved seats","A private room"],"answer":0,"type":"세부 사항","explanation":"남자가 \"Groups of four or more get twenty percent off.\"라고 했으므로 단체에는 할인된 가격이 적용된다."},{"q":"What does the man tell the woman to do?","choices":["Pay in cash","Call back later","Complete an online form","Send a list of names by e-mail"],"answer":2,"type":"요청·제안","explanation":"남자가 \"You'll need to fill out the form on our Web site.\"라고 했으므로 온라인 양식을 작성해야 한다. 전화 결제는 안 된다고 했을 뿐 현금 결제를 말하지는 않았다."}],"translation":"W: 안녕하세요, 10월 지역 마케팅 컨퍼런스 때문에 전화드렸어요. 아직 등록할 수 있나요?\nM: 네, 가능합니다. 참가비는 1인당 200달러예요.\nW: 그렇군요. 저희 회사에서 다섯 명을 등록하고 싶은데요. 단체 할인이 있나요?\nM: 네. 4명 이상 단체는 20퍼센트 할인됩니다.\nW: 잘됐네요. 전화로 신용카드 결제가 되나요?\nM: 죄송하지만 안 됩니다. 저희 웹사이트에서 양식을 작성하셔야 해요. 거기서 결제하실 수 있어요.\nW: 알겠어요. 오늘 오후에 할게요.","part":3},{"id":"p3-011","level":3,"topic":"봄 판촉 캠페인 결과","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, Ellen. Have you seen the sales numbers from the spring campaign?"},{"s":"W","t":"I just looked at them. Online sales went up almost thirty percent."},{"s":"M","t":"That's more than we expected. I think the social media videos made a big difference."},{"s":"W","t":"I agree. But sales in our stores didn't change much."},{"s":"M","t":"Maybe we should do something special for store customers next time, like in-store demonstrations."},{"s":"W","t":"That's a good thought. But the budget for the summer campaign was approved last week."},{"s":"M","t":"Oh, so we can't add anything new?"},{"s":"W","t":"Not this time. Let's put together a proposal for the fall instead."}],"graphic":null,"questions":[{"q":"What are the speakers mainly discussing?","choices":["The design of a Web site","The results of a promotional effort","A new store opening","Training employees to use social media"],"answer":1,"type":"주제·목적","explanation":"남자가 \"Have you seen the sales numbers from the spring campaign?\"이라고 묻고 이어서 매출 결과를 이야기하므로 판촉 활동의 결과가 주제다. 소셜 미디어는 영상 효과를 말할 때 나온 단어다."},{"q":"Why does the woman say, \"But the budget for the summer campaign was approved last week\"?","choices":["To announce that more money is available for the summer campaign","To complain about a late decision","To indicate that a plan cannot be changed now","To ask the man to review a budget"],"answer":2,"type":"의도 파악","explanation":"남자가 매장 시연을 제안하자 여자가 이 말을 했고, 곧이어 남자가 \"so we can't add anything new?\"라고 묻자 \"Not this time.\"이라고 답한다. 예산이 이미 확정되어 지금은 계획을 바꿀 수 없다는 뜻이다."},{"q":"What does the woman suggest?","choices":["Holding demonstrations this summer","Making more videos","Lowering store prices","Preparing an idea for a later campaign"],"answer":3,"type":"요청·제안","explanation":"여자가 \"Let's put together a proposal for the fall instead.\"라고 했으므로 이후(가을) 캠페인용 제안을 준비하자는 것이다. 여름에는 새로운 것을 추가할 수 없다고 했으므로 여름 시연은 오답이다."}],"translation":"M: 안녕하세요, 엘런. 봄 캠페인 매출 수치 봤어요?\nW: 방금 봤어요. 온라인 매출이 거의 30퍼센트 올랐어요.\nM: 예상보다 많네요. 소셜 미디어 영상이 큰 효과를 낸 것 같아요.\nW: 동의해요. 그런데 매장 매출은 별로 변하지 않았어요.\nM: 다음에는 매장 고객을 위해 매장 내 시연 같은 특별한 걸 해 봐야 할 것 같아요.\nW: 좋은 생각이에요. 그런데 여름 캠페인 예산은 지난주에 승인됐어요.\nM: 아, 그럼 새로운 걸 추가할 수 없는 건가요?\nW: 이번에는 안 돼요. 대신 가을 캠페인용 제안서를 만들어 봐요.","part":3},{"id":"p3-012","level":3,"topic":"호텔 객실 에어컨 고장","speakers":{"M":"male","W":"female","W2":"female"},"script":[{"s":"M","t":"Excuse me, I checked in yesterday, and the air conditioner in my room is making a loud noise. I couldn't sleep at all."},{"s":"W","t":"I'm very sorry to hear that, sir. What's your room number?"},{"s":"M","t":"It's eight fourteen."},{"s":"W","t":"Let me call our maintenance manager. Oh, here she is now. Grace, this guest is having trouble with the air conditioner in eight fourteen."},{"s":"W2","t":"I'm sorry, sir. That unit is quite old. We can repair it, but it'll take a few hours."},{"s":"M","t":"I have meetings all day, but I'd like to rest in my room this evening."},{"s":"W","t":"Then we'll move you to a room on the twelfth floor. It's quieter, and there's no extra charge."},{"s":"M","t":"That would be perfect. Thank you."},{"s":"W2","t":"I'll have your luggage brought up while you're out."}],"graphic":null,"questions":[{"q":"Where does the conversation most likely take place?","choices":["At a hotel","At an electronics store","At a conference center","At a repair shop"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"남자가 \"I checked in yesterday\"라며 객실(room number) 문제를 말하고, 직원이 다른 층 객실로 옮겨 주므로 호텔이다. 회의(meetings)와 수리(repair)는 대화 속 단어를 이용한 오답이다."},{"q":"Who most likely is Grace?","choices":["A hotel guest staying on the eighth floor","A person in charge of building upkeep","A front desk clerk","A meeting organizer"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"프런트 직원이 \"Let me call our maintenance manager. Oh, here she is now. Grace, ...\"라고 했으므로 그레이스는 시설 관리 책임자다. maintenance manager를 building upkeep 담당자로 바꿔 표현했다."},{"q":"What does Grace say she will do?","choices":["Repair the air conditioner tonight","Give the man a discount","Schedule a meeting","Arrange for some bags to be moved"],"answer":3,"type":"다음 할 일","explanation":"그레이스가 마지막에 \"I'll have your luggage brought up while you're out.\"이라고 했으므로 짐을 옮기도록 조치할 것이다. 추가 요금이 없다는 것은 할인과 다르다."}],"translation":"M: 실례합니다, 어제 체크인했는데 방 에어컨에서 큰 소음이 나요. 한숨도 못 잤어요.\nW: 정말 죄송합니다, 손님. 객실 번호가 어떻게 되시나요?\nM: 814호예요.\nW: 시설 관리 매니저를 불러 드릴게요. 아, 마침 여기 오시네요. 그레이스, 이 손님 814호 에어컨에 문제가 있으시대요.\nW2: 죄송합니다, 손님. 그 에어컨은 꽤 오래됐어요. 수리할 수는 있지만 몇 시간 걸릴 거예요.\nM: 저는 하루 종일 회의가 있지만, 오늘 저녁에는 방에서 쉬고 싶어요.\nW: 그러면 12층 객실로 옮겨 드리겠습니다. 더 조용하고 추가 요금은 없습니다.\nM: 그거 딱 좋네요. 감사합니다.\nW2: 외출하신 동안 짐을 올려 드리도록 하겠습니다.","part":3},{"id":"p3-013","level":3,"topic":"명함 인쇄 주문","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, I'd like to order business cards for some new staff members."},{"s":"M","t":"Sure. Do you have the design ready?"},{"s":"W","t":"Yes. We have five new employees, and each of them needs about a hundred cards."},{"s":"M","t":"OK. Actually, if you order everything together, it's cheaper. We can print all the cards at once with different names."},{"s":"W","t":"Oh, that's good to know. Let's do that, then."},{"s":"M","t":"Great. When do you need them?"},{"s":"W","t":"The new employees start next Monday. Is that possible?"},{"s":"M","t":"If you send me the design file today, they'll be ready on Friday."}],"graphic":{"title":"Speedy Print — Business Card Prices","rows":[["Quantity","Price"],["100 cards","$25"],["250 cards","$45"],["500 cards","$70"],["1,000 cards","$110"]]},"questions":[{"q":"What does the woman want to order?","choices":["Name tags for a company event next week","A new company logo","Printed items for new workers","Office furniture"],"answer":2,"type":"주제·목적","explanation":"여자가 \"I'd like to order business cards for some new staff members.\"라고 했으므로 신입 직원용 인쇄물(명함)을 주문하려는 것이다. 디자인은 이미 준비되어 있으므로 로고를 주문하는 것이 아니다."},{"q":"Look at the graphic. How much will the woman most likely pay?","choices":["$25","$45","$70","$110"],"answer":2,"type":"시각 자료 연계","explanation":"다섯 명이 각각 100장씩 필요한데(\"five new employees ... about a hundred cards\"), 남자가 한꺼번에 주문하면 더 싸다고 하자 여자가 그렇게 하겠다고 했다. 모두 500장이므로 표에서 $70이다. $25는 100장 가격이다."},{"q":"What will the woman most likely do next?","choices":["Visit the print shop","Pay a deposit","Hire more staff","Send a file"],"answer":3,"type":"다음 할 일","explanation":"남자가 \"If you send me the design file today, they'll be ready on Friday.\"라고 했고 여자는 월요일 전에 명함이 필요하므로 디자인 파일을 보낼 것이다."}],"translation":"W: 안녕하세요, 신입 직원들 명함을 주문하고 싶어요.\nM: 네. 디자인은 준비되어 있나요?\nW: 네. 신입 직원이 다섯 명인데, 각자 명함이 100장 정도 필요해요.\nM: 알겠습니다. 사실 한꺼번에 주문하시면 더 저렴해요. 이름만 다르게 해서 모든 명함을 한 번에 인쇄할 수 있거든요.\nW: 아, 좋은 정보네요. 그럼 그렇게 해 주세요.\nM: 좋습니다. 언제 필요하세요?\nW: 신입 직원들이 다음 주 월요일에 출근해요. 가능할까요?\nM: 오늘 디자인 파일을 보내 주시면 금요일에 준비될 거예요.","part":3},{"id":"p3-014","level":3,"topic":"휴가 중 업무 대행 부탁","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, Sam. I'm going on vacation next week, and I was wondering if you could cover my client calls."},{"s":"M","t":"Sure. How many calls do you usually get?"},{"s":"W","t":"About ten a day. Most of them are simple questions about invoices."},{"s":"M","t":"I can handle that. What about the Harrison account?"},{"s":"W","t":"Oh, they might call about renewing their contract."},{"s":"M","t":"Well, I've never worked on a contract renewal before."},{"s":"W","t":"Don't worry. I'll write down all the details before I leave, and our manager, Paul, can help you too."},{"s":"M","t":"That makes me feel better. Could you send me the notes by Thursday?"}],"graphic":null,"questions":[{"q":"What does the woman ask the man to do?","choices":["Renew a client's contract","Plan a vacation","Take over some of her duties while she is away","Send invoices to clients"],"answer":2,"type":"요청·제안","explanation":"여자가 \"I'm going on vacation next week ... if you could cover my client calls\"라고 했으므로 휴가 동안 업무를 대신해 달라는 부탁이다. 청구서(invoices)와 계약 갱신은 대화 속 단어를 이용한 오답이다."},{"q":"Why does the man say, \"I've never worked on a contract renewal before\"?","choices":["To express concern about a task","To ask for a promotion","To refuse to help the woman","To suggest hiring a new employee"],"answer":0,"type":"의도 파악","explanation":"해리슨 거래처가 계약 갱신 건으로 전화할 수 있다는 말에 이렇게 답하자 여자가 \"Don't worry.\"라며 안심시키고, 남자도 \"That makes me feel better.\"라고 한다. 업무에 대한 걱정을 나타낸 말이다. 이미 도와주겠다고 했으므로 거절은 아니다."},{"q":"What does the man ask the woman for?","choices":["Paul's phone number","Written information by a certain day","A list of invoices","An extra day off"],"answer":1,"type":"요청·제안","explanation":"남자가 \"Could you send me the notes by Thursday?\"라고 했으므로 목요일까지 적어 둔 자료를 달라는 요청이다."}],"translation":"W: 안녕하세요, 샘. 제가 다음 주에 휴가를 가는데, 제 고객 전화를 대신 받아 줄 수 있을까 해서요.\nM: 그럼요. 보통 전화가 몇 통이나 와요?\nW: 하루에 열 통 정도요. 대부분 청구서에 관한 간단한 질문이에요.\nM: 그건 할 수 있어요. 해리슨 거래처는요?\nW: 아, 거기서 계약 갱신 건으로 전화할 수도 있어요.\nM: 음, 저는 계약 갱신 업무를 한 번도 해 본 적이 없는데요.\nW: 걱정 마세요. 떠나기 전에 세부 사항을 모두 적어 둘게요. 그리고 폴 매니저님도 도와주실 수 있어요.\nM: 그러면 마음이 좀 놓이네요. 목요일까지 메모를 보내 줄 수 있어요?","part":3},{"id":"p3-015","level":3,"topic":"주차장 공사 기간 임시 주차","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Did you hear the parking garage will be closed starting Monday?"},{"s":"W","t":"Yes, I read the e-mail. They're repainting the lines and fixing the lights. It'll take two weeks."},{"s":"M","t":"So where are we supposed to park?"},{"s":"W","t":"The company rented spaces at the shopping mall across the street. We just need to show our employee ID."},{"s":"M","t":"That's a long walk, especially when it's raining."},{"s":"W","t":"Actually, there'll be a shuttle bus every fifteen minutes in the morning and evening."},{"s":"M","t":"Oh, that's convenient. Do we need to sign up for it?"},{"s":"W","t":"No, but the e-mail says we have to pick up a parking pass from the reception desk by Friday."}],"graphic":null,"questions":[{"q":"What is the conversation mainly about?","choices":["A shopping mall opening","A change to a bus route near the mall","A new ID card system","A temporary parking arrangement"],"answer":3,"type":"주제·목적","explanation":"주차장이 2주간 폐쇄되는 동안(\"the parking garage will be closed\") 쇼핑몰에 임시로 주차하는 방법을 이야기하므로 임시 주차 방안이 주제다."},{"q":"What will be provided for employees?","choices":["Free umbrellas","Shopping discounts","A transportation service","New lights for their offices"],"answer":2,"type":"세부 사항","explanation":"여자가 \"there'll be a shuttle bus every fifteen minutes\"라고 했으므로 셔틀버스, 즉 이동 서비스가 제공된다. 조명(lights)은 주차장 공사 내용이다."},{"q":"According to the woman, what must employees do by Friday?","choices":["Sign up for the shuttle bus service online","Collect a document at the front desk","Repaint their parking spaces","Send an e-mail to reception"],"answer":1,"type":"세부 사항","explanation":"여자가 \"we have to pick up a parking pass from the reception desk by Friday\"라고 했다. 셔틀은 신청할 필요가 없다고(\"No\") 했으므로 오답이다."}],"translation":"M: 월요일부터 주차장이 폐쇄된다는 얘기 들었어요?\nW: 네, 이메일 읽었어요. 주차선을 다시 칠하고 조명을 고친대요. 2주 걸린대요.\nM: 그럼 우리는 어디에 주차해야 하죠?\nW: 회사가 길 건너 쇼핑몰에 주차 공간을 빌렸어요. 사원증만 보여 주면 된대요.\nM: 거기서 걸어오기엔 멀어요. 특히 비 오는 날엔요.\nW: 사실 아침저녁으로 15분마다 셔틀버스가 다닐 거예요.\nM: 아, 편리하네요. 신청해야 하나요?\nW: 아니요, 그런데 이메일에 따르면 금요일까지 안내 데스크에서 주차권을 받아 가야 한대요.","part":3},{"id":"p3-016","level":4,"topic":"건물 방문객 안내","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, I have a ten o'clock appointment with Ms. Park at Brightline Design Studio, but I'm a bit early."},{"s":"W","t":"No problem. You're welcome to wait in the café here on the ground floor."},{"s":"M","t":"Actually, I was hoping to drop off some product samples first. They're pretty heavy."},{"s":"W","t":"I see. Just so you know, Brightline's office is being renovated this month, so they're temporarily working out of the conference center on the top floor."},{"s":"M","t":"Thanks for letting me know. Is there a freight elevator I could use? This cart is quite bulky."},{"s":"W","t":"Yes, it's at the end of the hallway behind the café. You'll need a visitor badge to operate it, though."},{"s":"M","t":"Where can I get one of those?"},{"s":"W","t":"I can print one for you right now. I'll just need to see a photo ID."},{"s":"M","t":"Sure, here's my driver's license."}],"graphic":{"title":"Westgate Tower Directory","rows":[["Floor","Tenant"],["1","Lobby / Café Verona"],["2","Harlow Accounting"],["3","Brightline Design Studio"],["4","Nexus Legal Services"],["5","Conference Center"]]},"questions":[{"q":"Why is the man visiting the building?","choices":["To meet a colleague for coffee","To apply for a job","To keep a scheduled appointment","To repair an elevator"],"answer":2,"type":"주제·목적","explanation":"남자가 \"I have a ten o'clock appointment with Ms. Park\"이라고 했으므로 예정된 약속 때문에 방문했다. 카페(café)와 엘리베이터는 대화 속 단어를 이용한 오답이다."},{"q":"Look at the graphic. Which floor will the man most likely go to?","choices":["The third floor","The second floor","The first floor","The fifth floor"],"answer":3,"type":"시각 자료 연계","explanation":"안내판에는 브라이트라인이 3층이지만, 여자가 \"they're temporarily working out of the conference center on the top floor\"라고 했다. 표에서 Conference Center는 5층이므로 남자는 5층으로 간다. 3층을 고르면 함정에 걸린다."},{"q":"What does the woman ask the man for?","choices":["A signature","A product sample","His appointment time","Some identification"],"answer":3,"type":"요청·제안","explanation":"여자가 \"I'll just need to see a photo ID.\"라고 했고 남자가 운전면허증을 건넨다. 따라서 신분증을 요청한 것이다. 샘플은 남자가 내려놓으려는 물건이다."}],"translation":"M: 안녕하세요, 브라이트라인 디자인 스튜디오의 박 선생님과 10시에 약속이 있는데 조금 일찍 왔어요.\nW: 괜찮습니다. 여기 1층 카페에서 기다리셔도 돼요.\nM: 사실 제품 샘플을 먼저 내려놓고 싶어서요. 꽤 무겁거든요.\nW: 그렇군요. 참고로 브라이트라인 사무실이 이번 달에 개보수 중이라 임시로 꼭대기 층 컨퍼런스 센터에서 일하고 있어요.\nM: 알려 주셔서 감사합니다. 쓸 수 있는 화물용 엘리베이터가 있나요? 이 카트가 꽤 커서요.\nW: 네, 카페 뒤쪽 복도 끝에 있어요. 그런데 작동하려면 방문객 출입증이 필요해요.\nM: 그건 어디서 받을 수 있나요?\nW: 지금 바로 출력해 드릴 수 있어요. 사진이 있는 신분증만 보여 주시면 돼요.\nM: 네, 여기 제 운전면허증이요.","part":3},{"id":"p3-017","level":4,"topic":"신제품 출시 지연 대책","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"Thanks for joining, everyone. I wanted to talk about the launch of our wireless headphones. Luis, where are we with production?"},{"s":"M","t":"Well, the factory told us yesterday that one of the parts suppliers has fallen behind. We're looking at a three-week delay, at least."},{"s":"W","t":"Three weeks? That pushes us right past the holiday shopping season."},{"s":"M2","t":"If I could jump in, we could launch with a limited quantity. The factory has enough parts for about two thousand units."},{"s":"W","t":"That's an interesting idea. Would that be enough for our retail partners?"},{"s":"M2","t":"Not for all of them, but we could make it an online exclusive at first. That might even create some buzz."},{"s":"M","t":"I'd have to confirm the numbers with the factory, but I think it's doable."},{"s":"W","t":"OK. Luis, get back to me with firm figures by Wednesday. And Mark, please draft a plan for the online launch."}],"graphic":null,"questions":[{"q":"What is the main topic of the conversation?","choices":["A holiday sales event for retail partners","Choosing a new supplier","Hiring factory workers","A delay in releasing a product"],"answer":3,"type":"주제·목적","explanation":"여자가 헤드폰 출시 이야기를 꺼내고 남자가 \"We're looking at a three-week delay\"라고 하면서 출시 지연 대책을 논의한다. 연말(holiday) 시즌과 공급업체(supplier)는 대화 속 단어를 이용한 오답이다."},{"q":"What does Mark suggest?","choices":["Finding another factory","Selling a small number of units first","Lowering the price","Postponing the launch until the spring season"],"answer":1,"type":"요청·제안","explanation":"여자가 마지막에 마크에게 온라인 출시 계획을 맡기는 것으로 보아 두 번째 남자가 마크다. 그가 \"we could launch with a limited quantity\"라고 했으므로 적은 수량을 먼저 판매하자는 제안이다."},{"q":"What is Luis asked to do?","choices":["Create an online store","Confirm production numbers","Contact retail partners","Draft a marketing plan"],"answer":1,"type":"다음 할 일","explanation":"여자가 \"Luis, get back to me with firm figures by Wednesday.\"라고 했으므로 확정된 생산 수치를 알려 달라는 것이다. 계획 초안 작성은 마크에게 맡긴 일이다."}],"translation":"W: 모두 참석해 줘서 고마워요. 무선 헤드폰 출시에 관해 이야기하고 싶었어요. 루이스, 생산은 어디까지 진행됐나요?\nM: 음, 어제 공장에서 부품 공급업체 한 곳의 일정이 뒤처졌다고 알려 왔어요. 최소 3주는 지연될 것 같아요.\nW: 3주요? 그러면 연말 쇼핑 시즌을 완전히 넘기게 돼요.\nM2: 제가 한마디 하자면, 한정 수량으로 출시할 수 있을 것 같아요. 공장에 약 2천 개 분량의 부품은 있거든요.\nW: 흥미로운 아이디어네요. 그걸로 소매 협력업체들에 충분할까요?\nM2: 전부에게는 아니지만, 처음엔 온라인 단독 판매로 할 수 있어요. 오히려 화제가 될 수도 있고요.\nM: 공장과 수량을 확인해 봐야 하지만 가능할 것 같아요.\nW: 좋아요. 루이스, 수요일까지 확정된 수치를 알려 주세요. 그리고 마크, 온라인 출시 계획 초안을 작성해 주세요.","part":3},{"id":"p3-018","level":4,"topic":"이사회 보고서 마감 변경","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Mike, do you have a minute? It's about the quarterly report for the board."},{"s":"M","t":"Sure. Is there a problem with the figures I sent?"},{"s":"W","t":"No, those look fine. But the board meeting got moved up to this Thursday, so we need the final version by tomorrow afternoon."},{"s":"M","t":"Tomorrow? I still haven't gotten the regional numbers from the Asia office."},{"s":"W","t":"Can you call them directly? It's already morning there."},{"s":"M","t":"I tried an hour ago. Their finance manager is out sick this week."},{"s":"W","t":"Hmm. Well, Jennifer used to work in that office."},{"s":"M","t":"Oh, right. She'd probably know who else has access to that data. I'll go ask her."}],"graphic":null,"questions":[{"q":"What are the speakers mainly discussing?","choices":["A deadline that has been moved earlier","A new board member","A trip to the Asia office next Thursday","Errors in some figures"],"answer":0,"type":"주제·목적","explanation":"여자가 \"the board meeting got moved up to this Thursday, so we need the final version by tomorrow afternoon\"이라고 해서 앞당겨진 마감을 두고 대화한다. 수치는 괜찮다고(\"those look fine\") 했으므로 오류는 오답이다."},{"q":"Why does the woman say, \"Well, Jennifer used to work in that office\"?","choices":["To suggest someone who may be able to help","To explain why a colleague left the company","To recommend Jennifer for a promotion","To point out that an office has moved"],"answer":0,"type":"의도 파악","explanation":"아시아 지사 담당자가 병가라 자료를 받을 수 없다는 말에 이렇게 답했고, 남자가 \"She'd probably know who else has access to that data.\"라고 받는다. 도움이 될 만한 사람을 알려 주려는 의도다."},{"q":"What will the man most likely do next?","choices":["Speak with a coworker","Call the finance manager","Travel to Asia","Cancel a board meeting"],"answer":0,"type":"다음 할 일","explanation":"남자가 마지막에 \"I'll go ask her.\"라고 했으므로 동료 제니퍼와 이야기할 것이다. 재무 매니저는 병가 중이라 이미 연락이 안 되었다."}],"translation":"W: 마이크, 잠깐 시간 있어요? 이사회에 낼 분기 보고서 건이에요.\nM: 그럼요. 제가 보낸 수치에 문제가 있나요?\nW: 아니요, 그건 괜찮아요. 그런데 이사회가 이번 주 목요일로 앞당겨져서 내일 오후까지 최종본이 필요해요.\nM: 내일요? 아시아 지사에서 지역 수치를 아직 못 받았는데요.\nW: 직접 전화해 볼 수 있어요? 거기는 벌써 아침이잖아요.\nM: 한 시간 전에 해 봤어요. 그쪽 재무 담당 매니저가 이번 주에 병가예요.\nW: 음. 그런데 제니퍼가 예전에 그 지사에서 일했잖아요.\nM: 아, 맞아요. 그 데이터에 접근할 수 있는 다른 사람을 알고 있을 거예요. 가서 물어볼게요.","part":3},{"id":"p3-019","level":4,"topic":"창립 기념 만찬 케이터링 상담","speakers":{"W":"female","M":"male","W2":"female"},"script":[{"s":"W","t":"Chef Moreno, thanks for meeting with us. My colleague Anna and I are organizing our company's anniversary dinner."},{"s":"M","t":"My pleasure. How many guests are you expecting?"},{"s":"W","t":"Around a hundred and twenty. We were hoping for a buffet rather than a sit-down meal."},{"s":"M","t":"A buffet works well for a group that size. Do any of your guests have dietary restrictions?"},{"s":"W2","t":"Quite a few, actually. We sent out a survey, and about a third of our staff prefer vegetarian options."},{"s":"M","t":"Then I'd recommend at least three vegetarian main dishes, not just one."},{"s":"W2","t":"That sounds great. Could we try some of them before we decide?"},{"s":"M","t":"Of course. We hold tastings every Tuesday afternoon. I'll have my assistant e-mail you the available times."}],"graphic":null,"questions":[{"q":"Who most likely is the man?","choices":["A food service provider","An event photographer","A company president","A survey researcher"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"여자가 남자를 \"Chef Moreno\"라고 부르고, 남자가 메뉴와 시식회를 안내하므로 음식 서비스(케이터링) 업체 사람이다. 설문(survey)은 여자들 회사가 실시한 것이다."},{"q":"What did the women learn from a survey?","choices":["Many staff members want meat-free meals.","Most guests prefer a sit-down dinner.","The event date should change.","About 120 people cannot attend."],"answer":0,"type":"세부 사항","explanation":"안나가 \"about a third of our staff prefer vegetarian options\"라고 했으므로 많은 직원이 고기 없는 식사를 원한다는 것을 알게 되었다. vegetarian을 meat-free로 바꿔 표현했다. 120명은 예상 참석 인원이다."},{"q":"What does the man say he will do?","choices":["Prepare a full menu for the anniversary dinner","Cook a sample dish today","Arrange for scheduling information to be sent","Visit the women's office"],"answer":2,"type":"다음 할 일","explanation":"남자가 \"I'll have my assistant e-mail you the available times.\"라고 했으므로 가능한 시간 정보를 보내도록 조치할 것이다. 화요일은 시식회가 열리는 요일일 뿐이다."}],"translation":"W: 모레노 셰프님, 만나 주셔서 감사합니다. 동료 안나와 제가 회사 창립 기념 만찬을 준비하고 있어요.\nM: 천만에요. 손님은 몇 분 정도 예상하세요?\nW: 120명 정도요. 코스 식사보다는 뷔페를 원해요.\nM: 그 정도 인원이면 뷔페가 잘 맞아요. 손님 중에 식단 제한이 있는 분이 있나요?\nW2: 사실 꽤 있어요. 설문 조사를 했는데 직원의 3분의 1 정도가 채식 메뉴를 선호해요.\nM: 그렇다면 채식 메인 요리를 하나가 아니라 최소 세 가지는 추천드려요.\nW2: 좋네요. 결정하기 전에 몇 가지 맛볼 수 있을까요?\nM: 물론이죠. 매주 화요일 오후에 시식회를 해요. 제 조수가 가능한 시간을 이메일로 보내 드리도록 할게요.","part":3},{"id":"p3-020","level":4,"topic":"웹사이트 결제 오류 반복","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, Ahmed. Customers have been calling all morning saying they can't complete their payments on our Web site."},{"s":"M","t":"Again? That's the third time this month."},{"s":"W","t":"I know. The tech team says it's the same problem with the payment server."},{"s":"M","t":"We really need to switch to a more reliable payment provider. We lose sales every time this happens."},{"s":"W","t":"I agree. I actually looked into a few companies last week. One of them, PayStream, offers a free sixty-day trial."},{"s":"M","t":"That sounds promising. Could you put together a comparison of the options for the director?"},{"s":"W","t":"Sure. I'll include their fees and customer reviews."},{"s":"M","t":"Great. And in the meantime, let's post a notice on the homepage so customers know we're working on it."}],"graphic":null,"questions":[{"q":"What problem are the speakers discussing?","choices":["The phone lines are down.","A server was stolen from the data center.","Some sales staff are absent.","Customers are unable to pay online."],"answer":3,"type":"주제·목적","explanation":"여자가 \"they can't complete their payments on our Web site\"라고 했으므로 고객이 온라인 결제를 못 하는 것이 문제다. 전화(calling)는 고객이 문의한 방법일 뿐 전화가 고장 난 것이 아니다."},{"q":"What does the man imply when he says, \"That's the third time this month\"?","choices":["He needs to reschedule a meeting.","He has called some customers several times.","A monthly report is late.","He is frustrated that a problem keeps happening."],"answer":3,"type":"의도 파악","explanation":"\"Again?\"이라고 반응하며 이 말을 한 뒤 \"We really need to switch to a more reliable payment provider.\"라고 이어 가므로, 같은 문제가 반복되는 것에 대한 불만을 나타낸다."},{"q":"What does the man ask the woman to do?","choices":["Start a free trial with PayStream today","Call the tech team","Contact the director","Compare some service providers"],"answer":3,"type":"요청·제안","explanation":"남자가 \"Could you put together a comparison of the options for the director?\"라고 부탁했으므로 업체 비교다. 무료 체험은 한 업체의 조건일 뿐이고, 이사(director)는 자료를 받을 사람이다."}],"translation":"W: 안녕하세요, 아메드. 고객들이 오전 내내 우리 웹사이트에서 결제를 완료할 수 없다고 전화하고 있어요.\nM: 또요? 이번 달에만 세 번째네요.\nW: 그러니까요. 기술팀 말로는 결제 서버의 같은 문제래요.\nM: 정말 더 믿을 만한 결제 업체로 바꿔야 해요. 이런 일이 생길 때마다 매출을 놓치고 있어요.\nW: 동의해요. 사실 지난주에 몇몇 업체를 알아봤어요. 그중 페이스트림은 60일 무료 체험을 제공해요.\nM: 좋은 것 같네요. 이사님께 드릴 업체 비교 자료를 만들어 줄 수 있어요?\nW: 그럼요. 수수료와 고객 후기도 넣을게요.\nM: 좋아요. 그리고 그동안 고객들이 우리가 해결 중이라는 걸 알 수 있게 홈페이지에 공지를 올립시다.","part":3},{"id":"p3-021","level":5,"topic":"사무용품 주문서 검토","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Tariq, before I submit this supply order, could you give it a once-over? Finance has been cracking down on spending lately."},{"s":"M","t":"Sure. Hmm, thirty desk organizers seems like a lot. We've only got eighteen people on this floor."},{"s":"W","t":"Well, the new hires in design are moving up here next month, so I figured we'd get ahead of it."},{"s":"M","t":"Fair enough. What about the ink cartridges, though? Didn't we switch to that leasing program? The new printers come with toner included."},{"s":"W","t":"Oh, you're right. Those machines don't even take cartridges. I'll take that line off entirely."},{"s":"M","t":"That should knock a good chunk off the total. And twenty boxes of paper will be hard to find room for."},{"s":"W","t":"True, but we get a bulk rate on anything over fifteen, so it pays to stock up."},{"s":"M","t":"Makes sense. Once you've made that change, go ahead and send it to Olivia for sign-off."},{"s":"W","t":"Will do. I'll get it to her before lunch."}],"graphic":{"title":"Order Form — Crestview Office Supply","rows":[["Item","Quantity","Unit Price"],["Printer paper (box)","20","$32"],["Ink cartridges","15","$48"],["Desk organizers","30","$12"],["Whiteboard markers (pack)","40","$6"]]},"questions":[{"q":"What does the woman ask the man to do?","choices":["Approve a department's spending for next quarter","Deliver some supplies","Check a document before it is submitted","Place an order for her"],"answer":2,"type":"요청·제안","explanation":"여자가 \"before I submit this supply order, could you give it a once-over?\"라고 했다. give it a once-over는 '훑어보다'라는 뜻이므로 제출 전에 서류를 확인해 달라는 요청이다. 결재(sign-off)는 올리비아가 한다."},{"q":"Look at the graphic. What is the unit price of the item that the woman will remove?","choices":["$32","$48","$12","$6"],"answer":1,"type":"시각 자료 연계","explanation":"남자가 새 프린터에는 토너가 포함되어 있다고 하자 여자가 \"I'll take that line off entirely.\"라며 잉크 카트리지 항목을 빼겠다고 했다. 표에서 Ink cartridges의 단가는 $48이다."},{"q":"Why does the woman want to order twenty boxes of paper?","choices":["To prepare for new staff","To receive a lower price","Because there is plenty of storage space","Because the new printers use more paper"],"answer":1,"type":"세부 사항","explanation":"여자가 \"we get a bulk rate on anything over fifteen, so it pays to stock up\"이라고 했으므로 대량 구매 할인을 받기 위해서다. 신입 직원(new hires)은 책상 정리함을 많이 주문한 이유이고, 보관 공간은 오히려 부족하다고 했다."}],"translation":"W: 타리크, 이 비품 주문서를 제출하기 전에 한번 훑어봐 줄래요? 요즘 재무팀이 지출을 엄격하게 단속하고 있어서요.\nM: 그럼요. 음, 책상 정리함 서른 개는 많아 보이는데요. 이 층엔 열여덟 명밖에 없잖아요.\nW: 음, 디자인팀 신입들이 다음 달에 이 층으로 올라오니까 미리 준비해 두려고요.\nM: 그렇군요. 그런데 잉크 카트리지는요? 우리 리스 프로그램으로 바꾸지 않았어요? 새 프린터는 토너가 포함되어 나오잖아요.\nW: 아, 맞아요. 그 기계엔 카트리지가 들어가지도 않죠. 그 항목은 통째로 뺄게요.\nM: 그러면 총액이 꽤 줄겠네요. 그리고 종이 스무 상자는 둘 곳 찾기가 어려울 거예요.\nW: 맞아요, 그런데 열다섯 상자가 넘으면 대량 구매 할인이 적용돼서 많이 사 두는 게 이득이에요.\nM: 일리가 있네요. 수정하고 나면 올리비아에게 보내서 결재받으세요.\nW: 그럴게요. 점심 전에 전달할게요.","part":3},{"id":"p3-022","level":5,"topic":"합병 후 고객 데이터베이스 통합","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"So, where do we stand on merging the two customer databases? Leadership wants a single system up and running before the end of the quarter."},{"s":"M","t":"Honestly, it's been an uphill battle. Their records use a completely different format for account numbers, so nothing lines up."},{"s":"M2","t":"Plus, there are thousands of duplicate entries. You know, customers who bought from both companies before the merger."},{"s":"W","t":"Can't the software flag those automatically?"},{"s":"M2","t":"It catches the obvious ones, but anything with a slightly different spelling slips through the cracks."},{"s":"M","t":"We could bring in a data-cleaning firm. I've heard good things about Veritas Analytics."},{"s":"W","t":"Wouldn't that blow our budget?"},{"s":"M","t":"Not necessarily. They charge by the record, and if we clean up the easy ones ourselves first, what's left shouldn't cost much."},{"s":"W","t":"All right. Get a quote from them, and let's revisit this on Friday."}],"graphic":null,"questions":[{"q":"What are the speakers mainly discussing?","choices":["Integrating records from two companies","Choosing new accounting software","Recruiting data analysts","Contacting customers who have complained"],"answer":0,"type":"주제·목적","explanation":"여자가 \"where do we stand on merging the two customer databases?\"라고 물으며 합병 후 두 회사의 고객 기록을 합치는 일을 논의한다. merging을 integrating으로 바꿔 표현했다."},{"q":"What problem does one of the men mention?","choices":["Some customer names were deleted.","Some customers appear more than once.","The software is too expensive.","Leadership changed the deadline."],"answer":1,"type":"세부 사항","explanation":"두 번째 남자가 \"there are thousands of duplicate entries\"라고 했으므로 같은 고객이 여러 번 기록된 것이 문제다. 경영진은 분기 말 기한을 제시했을 뿐 바꾼 것이 아니다."},{"q":"What does the woman ask one of the men to do?","choices":["Hire an outside firm immediately","Remove duplicates by Friday","Obtain a price estimate","Reduce the project budget"],"answer":2,"type":"요청·제안","explanation":"베리타스를 제안한 남자에게 여자가 \"Get a quote from them\"이라고 했다. quote(견적)를 price estimate로 바꿔 표현했다. 아직 고용을 결정한 것은 아니고 금요일은 다시 논의할 날이다."}],"translation":"W: 자, 두 고객 데이터베이스 통합은 어디까지 진행됐나요? 경영진은 분기 말 전에 단일 시스템이 가동되기를 원해요.\nM: 솔직히 힘겨운 싸움이에요. 그쪽 기록은 계좌 번호 형식이 완전히 달라서 맞는 게 하나도 없어요.\nM2: 게다가 중복 항목이 수천 개예요. 그러니까 합병 전에 두 회사 모두에서 구매한 고객들이요.\nW: 소프트웨어가 그런 걸 자동으로 표시해 주지 못하나요?\nM2: 뻔한 건 잡아내지만, 철자가 조금만 달라도 걸러지지 않고 빠져나가요.\nM: 데이터 정제 전문 업체를 부를 수도 있어요. 베리타스 애널리틱스가 평판이 좋더라고요.\nW: 그러면 예산을 초과하지 않을까요?\nM: 꼭 그렇진 않아요. 기록 건수로 비용을 받으니까, 쉬운 건 우리가 먼저 정리하면 남은 건 비용이 많이 들지 않을 거예요.\nW: 좋아요. 그 업체에서 견적을 받아 오세요. 금요일에 다시 논의합시다.","part":3},{"id":"p3-023","level":5,"topic":"신규 매장 임대 검토","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Priya, I just got off the phone with the realtor about that storefront on Elm Street."},{"s":"W","t":"And? Is it still available?"},{"s":"M","t":"It is, but the landlord wants a five-year lease minimum. That's a big commitment for a location we haven't tested."},{"s":"W","t":"Right. And foot traffic on Elm has been hit or miss ever since they rerouted the bus line."},{"s":"M","t":"Exactly. Although the rent is about fifteen percent below anything else downtown."},{"s":"W","t":"Well, you get what you pay for."},{"s":"M","t":"Fair point. What if we ran a pop-up shop somewhere nearby for a couple of months first? We'd have real sales data before signing anything."},{"s":"W","t":"I like that. The farmers' market lets vendors rent stalls by the month."},{"s":"M","t":"Perfect. I'll call the market office this afternoon and see what's open."}],"graphic":null,"questions":[{"q":"What are the speakers mainly discussing?","choices":["How to redesign a store","Where to hold a farmers' market","When to hire a real estate agent","Whether to rent a retail space"],"answer":3,"type":"주제·목적","explanation":"남자가 엘름 가 매장(storefront)에 대한 중개인과의 통화 내용을 전하고, 5년 임대 조건과 입지를 따지므로 매장 임대 여부가 주제다. 농산물 직판장은 대안으로 나온 장소일 뿐이다."},{"q":"What does the woman imply when she says, \"Well, you get what you pay for\"?","choices":["The low rent may reflect the location's drawbacks.","The landlord should lower the rent further.","She is willing to spend more on advertising.","The realtor's fee is reasonable."],"answer":0,"type":"의도 파악","explanation":"남자가 임대료가 15퍼센트 싸다고 하자 여자가 이 말을 했다. 앞서 버스 노선 변경으로 유동 인구가 들쭉날쭉하다고 했으므로, 싼 데는 그만한 단점이 있다는 뜻이다. 남자도 \"Fair point.\"라며 동의한다."},{"q":"What will the man do this afternoon?","choices":["Sign a five-year lease for the Elm Street store","Inquire about short-term space","Visit Elm Street","Speak with the bus company"],"answer":1,"type":"다음 할 일","explanation":"남자가 \"I'll call the market office this afternoon and see what's open.\"이라고 했다. 월 단위로 빌리는 좌판을 알아보는 것이므로 단기 공간 문의다. 5년 임대는 부담스럽다고 했다."}],"translation":"M: 프리야, 방금 엘름 가 매장 건으로 부동산 중개인과 통화를 끝냈어요.\nW: 그래서요? 아직 비어 있대요?\nM: 네, 그런데 건물주가 최소 5년 임대를 원해요. 검증도 안 된 입지에 그건 큰 부담이에요.\nW: 맞아요. 게다가 버스 노선이 바뀐 뒤로 엘름 가 유동 인구는 들쭉날쭉했잖아요.\nM: 그러니까요. 그래도 임대료가 시내 다른 곳보다 15퍼센트 정도 싸긴 해요.\nW: 글쎄요, 싼 게 비지떡이죠.\nM: 일리 있어요. 먼저 근처 어딘가에서 두어 달 팝업 매장을 운영해 보면 어때요? 뭔가 계약하기 전에 실제 판매 데이터를 얻을 수 있잖아요.\nW: 좋아요. 농산물 직판장은 판매자들에게 좌판을 월 단위로 빌려줘요.\nM: 완벽하네요. 오늘 오후에 직판장 사무실에 전화해서 빈자리가 있는지 알아볼게요.","part":3},{"id":"p3-024","level":5,"topic":"학회 발표 순서 조정","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Jeff, we've got a problem with tomorrow's lineup. Marco Villa's flight got grounded in Frankfurt, and he won't make it in until late afternoon."},{"s":"M","t":"Ugh, that's the worst possible timing. His session is one of our biggest draws."},{"s":"W","t":"I know. I was thinking we could just swap him with whoever's in the last slot of the day."},{"s":"M","t":"That's what I'd do too, but Peter mentioned he's catching an evening train. Let me run it by him before we commit."},{"s":"W","t":"If he's fine with it, I'll have the tech crew update the digital signs tonight."},{"s":"M","t":"And we should send a push notification through the event app, too. People plan their whole day around that schedule."},{"s":"W","t":"Good call. I'll draft the message now so it's ready to go the minute Peter confirms."},{"s":"M","t":"I'm texting him as we speak."}],"graphic":{"title":"Sustainable Packaging Summit — Day 2","rows":[["Time","Speaker","Topic"],["9:30","Dr. Helen Cho","Plant-Based Plastics"],["11:00","Marco Villa","Recycling Logistics"],["1:30","Aisha Grant","Consumer Trends"],["3:00","Peter Lund","Packaging Regulations"]]},"questions":[{"q":"What problem does the woman mention?","choices":["A presenter's travel has been disrupted.","A flight has been overbooked.","A session room is unavailable.","The event app has stopped working."],"answer":0,"type":"주제·목적","explanation":"여자가 \"Marco Villa's flight got grounded in Frankfurt, and he won't make it in until late afternoon\"이라고 했으므로 발표자의 이동에 차질이 생긴 것이 문제다. 초과 예약(overbooked)은 언급되지 않았다."},{"q":"Look at the graphic. What time would Marco Villa speak if the change is made?","choices":["At 11:00","At 9:30","At 3:00","At 1:30"],"answer":2,"type":"시각 자료 연계","explanation":"여자는 마르코를 그날 마지막 순서(\"the last slot of the day\")인 사람과 바꾸자고 했다. 표에서 마지막 순서는 3:00의 Peter Lund이므로 마르코는 3:00에 발표하게 된다. 11:00은 원래 시간이다."},{"q":"What is the man doing at the end of the conversation?","choices":["Updating some digital signs","Contacting a speaker","Drafting a notification","Booking a train ticket"],"answer":1,"type":"다음 할 일","explanation":"남자가 \"I'm texting him as we speak.\"라고 했고 him은 피터이므로 발표자에게 연락하는 중이다. 알림 초안은 여자가, 안내판 업데이트는 기술팀이 할 일이다."}],"translation":"W: 제프, 내일 발표 순서에 문제가 생겼어요. 마르코 비야의 비행기가 프랑크푸르트에서 발이 묶여서 오후 늦게나 도착할 거래요.\nM: 아, 최악의 타이밍이네요. 그 세션은 우리 행사에서 가장 인기 있는 것 중 하나인데요.\nW: 그러니까요. 그날 마지막 순서인 사람과 그냥 바꾸면 어떨까 생각했어요.\nM: 저라도 그렇게 하겠지만, 피터가 저녁 기차를 탄다고 했거든요. 확정하기 전에 그에게 먼저 물어볼게요.\nW: 그가 괜찮다고 하면 오늘 밤 기술팀에게 디지털 안내판을 업데이트하라고 할게요.\nM: 그리고 행사 앱으로 푸시 알림도 보내야 해요. 사람들이 그 일정표에 맞춰 하루 계획을 다 짜니까요.\nW: 좋은 생각이에요. 피터가 확인해 주는 즉시 보낼 수 있게 지금 메시지 초안을 쓸게요.\nM: 지금 바로 문자 보내고 있어요.","part":3},{"id":"p3-025","level":5,"topic":"피트니스 앱 이용자 이탈","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Have you had a chance to look at the subscriber numbers for our fitness app?"},{"s":"M","t":"I have, and they're not pretty. We gained a lot of users in January, but nearly half dropped off by March."},{"s":"W","t":"That's pretty typical for New Year's sign-ups, though. People lose steam."},{"s":"M","t":"Sure, but our competitors held on to a much bigger share. I think our onboarding is the weak link. New users just get dumped on a menu with forty workouts."},{"s":"W","t":"So you're thinking of a guided first week, or something along those lines?"},{"s":"M","t":"Exactly. A short personalized plan based on their goals. The developers say it's a six-week job."},{"s":"W","t":"Six weeks? We're launching the summer promotion in four."},{"s":"M","t":"I hear you. We could roll out a stripped-down version in time and build on it later."},{"s":"W","t":"OK. Sketch out what that stripped-down version would include, and we'll take it to the product team on Monday."}],"graphic":null,"questions":[{"q":"What are the speakers mainly discussing?","choices":["Opening a new fitness center","Hiring more developers","Keeping users of an app from leaving","Planning a New Year's event"],"answer":2,"type":"주제·목적","explanation":"남자가 \"nearly half dropped off by March\"라고 하며 이용자 이탈 원인과 해결책을 논의하므로, 앱 이용자를 유지하는 방법이 주제다. 새해(New Year's)는 가입 시기를 말할 때 나온 단어다."},{"q":"Why does the woman say, \"We're launching the summer promotion in four\"?","choices":["To suggest postponing a summer promotion by a month","To correct a date the man gave","To show that sales will rise soon","To point out that a timeline is too long"],"answer":3,"type":"의도 파악","explanation":"개발에 6주가 걸린다는 말에 \"Six weeks?\"라고 반문하며 프로모션이 4주 뒤라고 말했다. 개발 기간이 프로모션 일정에 맞지 않는다는 뜻이며, 남자도 \"I hear you.\"라며 축소 버전을 제안한다."},{"q":"What does the woman ask the man to do?","choices":["Meet with competitors about their apps","Design forty new workouts","Cancel the summer promotion","Outline a simplified feature"],"answer":3,"type":"요청·제안","explanation":"여자가 \"Sketch out what that stripped-down version would include\"라고 했다. sketch out은 '대략 정리하다', stripped-down은 '간소화한'이라는 뜻이므로 간소화된 기능의 개요를 만들어 달라는 요청이다."}],"translation":"W: 우리 피트니스 앱 구독자 수치 볼 기회 있었어요?\nM: 봤어요, 좋지 않더라고요. 1월에 이용자가 많이 늘었는데 3월까지 거의 절반이 떨어져 나갔어요.\nW: 그래도 새해 가입자들은 대개 그래요. 사람들이 의욕을 잃거든요.\nM: 그렇긴 한데 경쟁사들은 훨씬 많은 비율을 유지했어요. 제 생각엔 신규 이용자 안내 과정이 약점이에요. 새 이용자는 운동 40가지가 있는 메뉴에 그냥 던져지거든요.\nW: 그러니까 첫 주 가이드 같은 걸 생각하는 거예요?\nM: 바로 그거예요. 목표에 맞춘 짧은 맞춤 계획이요. 개발자들은 6주짜리 작업이라고 해요.\nW: 6주요? 여름 프로모션은 4주 뒤에 시작하는데요.\nM: 무슨 말인지 알아요. 기능을 줄인 버전을 제때 내놓고 나중에 보완할 수 있어요.\nW: 좋아요. 그 간소화 버전에 무엇이 들어갈지 대략 정리해 주세요. 월요일에 제품팀에 가져가죠.","part":3},{"id":"p3-026","level":1,"topic":"렌터카 카운터에서 차량 인수","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Good afternoon. Welcome to Speedy Car Rental. How can I help you?"},{"s":"M","t":"Hi. I have a reservation under the name David Park. I booked a small car for three days."},{"s":"W","t":"Let me check. Yes, here it is. Can I see your driver's license, please?"},{"s":"M","t":"Sure, here you go."},{"s":"W","t":"Thank you. Your car is in parking space twelve, right outside this door."},{"s":"M","t":"Great. And where do I return it?"},{"s":"W","t":"Just bring it back here and leave the keys at this counter."}],"graphic":null,"questions":[{"q":"Where most likely are the speakers?","choices":["At a gas station","At an auto repair shop","At a driving school","At a car rental office"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"여자가 \"Welcome to Speedy Car Rental.\"이라고 인사하고 남자가 차를 3일간 예약했다고 하므로 렌터카 사무실이다. 운전면허증(driver's license)이 나온다고 운전 학원을 고르면 안 된다."},{"q":"What does the woman ask the man for?","choices":["His driver's license","His phone number and home address","His car keys","His credit card"],"answer":0,"type":"세부 사항","explanation":"여자가 \"Can I see your driver's license, please?\"라고 했으므로 운전면허증을 요청했다. 열쇠(keys)는 차를 반납할 때 카운터에 두라고 한 물건이다."},{"q":"Where is the man's car?","choices":["At the airport","Right outside the office","At another rental office","On the second floor"],"answer":1,"type":"세부 사항","explanation":"여자가 \"Your car is in parking space twelve, right outside this door.\"라고 했으므로 사무실 문 바로 밖에 있다. right outside this door를 right outside the office로 바꿔 표현했다."}],"translation":"W: 안녕하세요. 스피디 렌터카에 오신 것을 환영합니다. 무엇을 도와드릴까요?\nM: 안녕하세요. 데이비드 박이라는 이름으로 예약했어요. 소형차를 3일 동안 빌렸어요.\nW: 확인해 볼게요. 네, 여기 있네요. 운전면허증을 보여 주시겠어요?\nM: 물론이죠. 여기 있어요.\nW: 감사합니다. 차는 이 문 바로 밖 12번 주차 칸에 있어요.\nM: 좋네요. 그리고 반납은 어디에 하나요?\nW: 여기로 다시 가져오셔서 이 카운터에 열쇠를 두고 가시면 돼요.","part":3},{"id":"p3-027","level":1,"topic":"약국 처방약 수령","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hello. I'm here to pick up my prescription. My name is Ken Lee."},{"s":"W","t":"One moment, please. Hmm, I'm sorry, it isn't ready yet. We're very busy today."},{"s":"M","t":"Oh. How long will it take?"},{"s":"W","t":"About twenty minutes. You can wait here or come back later."},{"s":"M","t":"I'll go buy some groceries at the supermarket next door and come back."},{"s":"W","t":"OK. I'll have it ready for you then."}],"graphic":null,"questions":[{"q":"Who most likely is the woman?","choices":["A grocery clerk","A doctor","A pharmacist","A nurse"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"남자가 \"I'm here to pick up my prescription.\"이라며 처방약을 받으러 왔고, 여자가 약을 준비해 주겠다고 하므로 약사다. 식료품(groceries)은 남자가 옆 가게에서 살 물건이다."},{"q":"What problem does the woman mention?","choices":["The store is closing soon.","The medicine is not ready yet.","A doctor is not available.","The man's name is not on the list."],"answer":1,"type":"세부 사항","explanation":"여자가 \"it isn't ready yet. We're very busy today.\"라고 했으므로 약이 아직 준비되지 않은 것이 문제다. 가게가 곧 문을 닫는다는 말은 없다."},{"q":"What will the man do next?","choices":["Wait in the pharmacy","Call his doctor","Come back tomorrow","Go shopping at a nearby store"],"answer":3,"type":"다음 할 일","explanation":"남자가 \"I'll go buy some groceries at the supermarket next door and come back.\"이라고 했으므로 옆 가게에 장을 보러 간다. 여기서 기다려도 된다는 것은 여자의 제안이었지만 남자는 선택하지 않았다."}],"translation":"M: 안녕하세요. 처방약을 받으러 왔어요. 제 이름은 켄 리예요.\nW: 잠시만요. 음, 죄송하지만 아직 준비가 안 됐어요. 오늘 무척 바쁘거든요.\nM: 아. 얼마나 걸릴까요?\nW: 20분 정도요. 여기서 기다리셔도 되고 나중에 다시 오셔도 돼요.\nM: 옆 슈퍼마켓에서 장을 보고 다시 올게요.\nW: 알겠습니다. 그때까지 준비해 둘게요.","part":3},{"id":"p3-028","level":1,"topic":"헬스장 회원 가입과 시설 안내","speakers":{"M":"male","W":"female","M2":"male"},"script":[{"s":"M","t":"Hi, I'd like to join this gym. How much is a membership?"},{"s":"W","t":"It's forty dollars a month. That includes all of our exercise classes."},{"s":"M","t":"That sounds good. Can I look around first?"},{"s":"W","t":"Of course. This is Brian, one of our trainers. He can show you around."},{"s":"M2","t":"Hi, nice to meet you. Let's start with the swimming pool. It's on the first floor."},{"s":"M","t":"Great. I really like swimming."},{"s":"M2","t":"Then you'll love it. It opens at six every morning."}],"graphic":null,"questions":[{"q":"How much does a membership cost?","choices":["Sixty dollars a month","Forty dollars a week","Forty dollars a month","Fourteen dollars a month"],"answer":2,"type":"세부 사항","explanation":"여자가 \"It's forty dollars a month.\"라고 했으므로 한 달에 40달러다. fourteen과 forty의 발음 차이, month와 week의 차이에 주의한다. 6(six)은 수영장 개장 시각이다."},{"q":"Who is Brian?","choices":["A trainer","A new member","A swimmer","A receptionist"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"여자가 \"This is Brian, one of our trainers.\"라고 소개했으므로 브라이언은 트레이너다. 안내 데스크 직원(receptionist)은 여자다."},{"q":"What will Brian show the man first?","choices":["A café","A locker room","A swimming pool","A yoga room"],"answer":2,"type":"세부 사항","explanation":"브라이언이 \"Let's start with the swimming pool.\"이라고 했으므로 수영장을 먼저 본다. 나머지 장소는 대화에 나오지 않는다."}],"translation":"M: 안녕하세요, 이 헬스장에 가입하고 싶어요. 회원권은 얼마인가요?\nW: 한 달에 40달러예요. 모든 운동 수업이 포함돼 있어요.\nM: 좋네요. 먼저 둘러봐도 될까요?\nW: 물론이죠. 이분은 저희 트레이너 중 한 명인 브라이언이에요. 안내해 드릴 거예요.\nM2: 안녕하세요, 반갑습니다. 수영장부터 시작하죠. 1층에 있어요.\nM: 좋아요. 저는 수영을 정말 좋아해요.\nM2: 그럼 마음에 드실 거예요. 매일 아침 6시에 문을 열어요.","part":3},{"id":"p3-029","level":1,"topic":"치과 예약 시간 변경","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, this is Sam Wilson. I have a dental appointment tomorrow at ten."},{"s":"W","t":"Yes, Mr. Wilson. How can I help you?"},{"s":"M","t":"I have to work tomorrow morning. Can I change it to the afternoon?"},{"s":"W","t":"Let me see. Dr. Lee is free at three o'clock. Is that OK?"},{"s":"M","t":"Three is perfect. Thank you."},{"s":"W","t":"You're welcome. Please come ten minutes early to fill out a form."}],"graphic":null,"questions":[{"q":"Why is the man calling?","choices":["To change an appointment time","To find a new doctor","To ask about a bill","To cancel a meeting"],"answer":0,"type":"주제·목적","explanation":"남자가 \"Can I change it to the afternoon?\"이라며 내일 오전 10시 치과 예약을 오후로 바꾸려고 전화했다. 예약을 취소하는 것이 아니라 시간만 바꾼다."},{"q":"Why can't the man come in the morning?","choices":["His car is broken.","He has to work.","He will be on a trip.","He has a class."],"answer":1,"type":"세부 사항","explanation":"남자가 \"I have to work tomorrow morning.\"이라고 했으므로 일을 해야 하기 때문이다. 나머지는 대화에 나오지 않는 이유다."},{"q":"What does the woman ask the man to do?","choices":["Call back tomorrow","Bring his insurance card","Pay in advance","Arrive a little early"],"answer":3,"type":"요청·제안","explanation":"여자가 \"Please come ten minutes early to fill out a form.\"이라고 했으므로 조금 일찍 오라는 요청이다. come ten minutes early를 arrive a little early로 바꿔 표현했다."}],"translation":"M: 안녕하세요, 샘 윌슨입니다. 내일 10시에 치과 예약이 있는데요.\nW: 네, 윌슨 씨. 무엇을 도와드릴까요?\nM: 내일 오전에 일을 해야 해서요. 오후로 바꿀 수 있을까요?\nW: 확인해 볼게요. 이 선생님이 3시에 비어 있어요. 괜찮으세요?\nM: 3시 아주 좋아요. 감사합니다.\nW: 천만에요. 서류를 작성하셔야 하니 10분 일찍 와 주세요.","part":3},{"id":"p3-030","level":1,"topic":"식당 예약 인원 변경","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hello, I made a reservation for four people tonight at seven. The name is Roberts."},{"s":"W","t":"Yes, Mr. Roberts, I see it here."},{"s":"M","t":"Two more people are joining us. Can you make it a table for six?"},{"s":"W","t":"No problem. Would you like to sit inside or on the patio?"},{"s":"M","t":"Inside, please. It's a little cold tonight."},{"s":"W","t":"Sure. We'll see you at seven."}],"graphic":null,"questions":[{"q":"What does the man want to do?","choices":["Cancel his reservation","Add people to his reservation","Change the time of his reservation","Order food for delivery"],"answer":1,"type":"주제·목적","explanation":"남자가 \"Two more people are joining us. Can you make it a table for six?\"라고 했으므로 예약 인원을 늘리려는 것이다. 시간은 그대로 7시다."},{"q":"How many people will be at the table?","choices":["Six","Two","Four","Seven"],"answer":0,"type":"세부 사항","explanation":"원래 4명 예약에 2명이 더 와서 \"a table for six\"를 요청했으므로 6명이다. 4는 원래 인원, 2는 추가 인원, 7은 예약 시각이다."},{"q":"Why does the man want to sit inside?","choices":["It is raining.","The patio is full.","The weather is cold.","It is quieter inside."],"answer":2,"type":"세부 사항","explanation":"남자가 \"It's a little cold tonight.\"이라고 했으므로 날씨가 춥기 때문이다. 비가 온다는 말은 없다."}],"translation":"M: 안녕하세요, 오늘 저녁 7시에 4명으로 예약했어요. 이름은 로버츠예요.\nW: 네, 로버츠 씨, 여기 있네요.\nM: 두 명이 더 오게 됐어요. 6인석으로 바꿔 주실 수 있나요?\nW: 문제없어요. 실내와 테라스 중 어디에 앉으시겠어요?\nM: 실내로 해 주세요. 오늘 밤은 좀 춥네요.\nW: 알겠습니다. 7시에 뵐게요.","part":3},{"id":"p3-031","level":1,"topic":"은행 계좌 개설","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, I just moved to this city, and I want to open a bank account."},{"s":"W","t":"Welcome. Do you want a checking account or a savings account?"},{"s":"M","t":"A checking account, please. I need it for my new job."},{"s":"W","t":"OK. I need two pieces of ID and your new address."},{"s":"M","t":"I have my passport and my driver's license here."},{"s":"W","t":"Perfect. Please have a seat. This will take about fifteen minutes."}],"graphic":null,"questions":[{"q":"Where most likely are the speakers?","choices":["At a post office","At a moving company","At a travel agency","At a bank"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"남자가 \"I want to open a bank account.\"라고 했고 여자가 당좌·저축 계좌를 묻고 있으므로 은행이다. 이사(moved)라는 말에 이삿짐 업체를 고르면 안 된다."},{"q":"Why does the man need an account?","choices":["He wants to buy a house.","He lost his bank card.","He started a new job.","He is going on a trip."],"answer":2,"type":"세부 사항","explanation":"남자가 \"I need it for my new job.\"이라고 했으므로 새 직장 때문이다. 집을 사거나 여행을 간다는 말은 없다."},{"q":"How long will the process take?","choices":["About an hour","About fifteen minutes","About five minutes","About fifty minutes"],"answer":1,"type":"세부 사항","explanation":"여자가 \"This will take about fifteen minutes.\"라고 했다. fifteen과 fifty의 발음 차이에 주의한다."}],"translation":"M: 안녕하세요, 이 도시로 막 이사 와서 은행 계좌를 만들고 싶어요.\nW: 환영합니다. 입출금 계좌를 원하세요, 저축 계좌를 원하세요?\nM: 입출금 계좌로 해 주세요. 새 직장 때문에 필요해요.\nW: 알겠습니다. 신분증 두 가지와 새 주소가 필요해요.\nM: 여기 여권과 운전면허증이 있어요.\nW: 좋습니다. 앉아 계세요. 15분 정도 걸릴 거예요.","part":3},{"id":"p3-032","level":1,"topic":"사무실 생일 케이크 주문","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Hi, I want to order a cake for my coworker's birthday party on Friday."},{"s":"M","t":"Sure. How many people will be at the party?"},{"s":"W","t":"There are about fifteen people in our office."},{"s":"M","t":"OK. Then this size is right for you. What kind of cake would you like?"},{"s":"W","t":"Chocolate, please. Can you write \"Happy Birthday, Anna\" on it?"},{"s":"M","t":"Of course. You can pick it up on Friday morning."}],"graphic":{"title":"Sunny Bakery — Cake Prices","rows":[["Size","Serves","Price"],["Small","6 people","$20"],["Medium","10 people","$30"],["Large","15 people","$40"],["Extra Large","25 people","$55"]]},"questions":[{"q":"What is the woman planning?","choices":["A wedding","A retirement party","A business lunch","A birthday party"],"answer":3,"type":"주제·목적","explanation":"여자가 \"I want to order a cake for my coworker's birthday party\"라고 했으므로 동료의 생일 파티를 준비한다."},{"q":"Look at the graphic. How much will the woman most likely pay?","choices":["$40","$30","$55","$20"],"answer":0,"type":"시각 자료 연계","explanation":"여자가 사무실 인원이 \"about fifteen people\"이라고 하자 남자가 이 크기가 맞다고 했다. 표에서 15명용은 Large로 40달러다. 25명용(55달러)은 인원보다 크다."},{"q":"What does the woman ask the man to do?","choices":["Write a message on a cake","Deliver a cake to her office","Call her on Friday","Make a fruit cake"],"answer":0,"type":"요청·제안","explanation":"여자가 \"Can you write 'Happy Birthday, Anna' on it?\"이라고 했으므로 케이크에 문구를 써 달라는 요청이다. 케이크는 금요일 아침에 직접 찾아가므로 배달은 오답이다."}],"translation":"W: 안녕하세요, 금요일에 있을 동료 생일 파티용 케이크를 주문하고 싶어요.\nM: 네. 파티에 몇 명이 오나요?\nW: 저희 사무실에 15명 정도 있어요.\nM: 알겠습니다. 그럼 이 크기가 맞겠네요. 어떤 케이크를 원하세요?\nW: 초콜릿으로 해 주세요. 위에 \"생일 축하해요, 애나\"라고 써 주실 수 있나요?\nM: 물론이죠. 금요일 아침에 찾아가시면 됩니다.","part":3},{"id":"p3-033","level":2,"topic":"IT 헬프데스크 계정 잠금 해제","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Hi, is this the IT help desk? I can't log in to my computer. It says my account is locked."},{"s":"M","t":"That usually happens when someone enters the wrong password too many times. Did you change your password recently?"},{"s":"W","t":"Yes, yesterday. I guess I typed the old one a few times this morning."},{"s":"M","t":"OK. I can unlock it for you, but I need to confirm who you are first. What's your employee number?"},{"s":"W","t":"It's 4-5-8-2-0. But I have a presentation in ten minutes."},{"s":"M","t":"Don't worry. This will only take a second. There. Try logging in with your new password now."},{"s":"W","t":"It worked. Thanks so much."}],"graphic":null,"questions":[{"q":"Why is the woman calling?","choices":["She wants to change her password.","Her computer screen is broken.","She cannot access her account.","She forgot her employee number."],"answer":2,"type":"주제·목적","explanation":"여자가 \"I can't log in to my computer. It says my account is locked.\"라고 했으므로 계정에 접속하지 못해서 전화했다. 비밀번호는 어제 이미 바꿨으므로 비밀번호를 바꾸고 싶다는 것은 오답이다."},{"q":"What does the man ask the woman for?","choices":["A new password","A computer serial number","A manager's approval","An employee number"],"answer":3,"type":"세부 사항","explanation":"남자가 본인 확인을 위해 \"What's your employee number?\"라고 물었다. 새 비밀번호는 로그인할 때 여자가 직접 입력하는 것이다."},{"q":"Why does the woman say, \"But I have a presentation in ten minutes\"?","choices":["She wants to reschedule a meeting.","She needs the problem solved quickly.","She is inviting the man to attend.","She needs to borrow a projector."],"answer":1,"type":"의도 파악","explanation":"본인 확인을 해야 한다는 말 뒤에 곧 발표가 있다고 한 것은 빨리 해결해 달라는 뜻이다. 남자도 \"Don't worry. This will only take a second.\"라며 금방 끝난다고 안심시킨다."}],"translation":"W: 안녕하세요, IT 헬프데스크죠? 컴퓨터에 로그인이 안 돼요. 계정이 잠겼다고 나와요.\nM: 보통 비밀번호를 여러 번 틀리게 입력하면 그래요. 최근에 비밀번호를 바꾸셨나요?\nW: 네, 어제요. 오늘 아침에 예전 비밀번호를 몇 번 입력했나 봐요.\nM: 알겠습니다. 잠금을 풀어 드릴 수 있는데, 먼저 본인 확인이 필요해요. 사번이 어떻게 되세요?\nW: 4-5-8-2-0이에요. 그런데 제가 10분 뒤에 발표가 있어요.\nM: 걱정 마세요. 금방 돼요. 됐습니다. 이제 새 비밀번호로 로그인해 보세요.\nW: 되네요. 정말 고마워요.","part":3},{"id":"p3-034","level":2,"topic":"채용 박람회 포스터 인쇄 주문","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, I'd like to print some posters for our company's booth at a job fair."},{"s":"W","t":"Sure. How many do you need, and what size?"},{"s":"M","t":"Twenty posters. I was thinking of the biggest size, but that's too expensive for us."},{"s":"W","t":"Many customers choose the size just below that. It's still easy to see from a distance."},{"s":"M","t":"OK, let's do that. When can I pick them up?"},{"s":"W","t":"They'll be ready tomorrow afternoon. Could you e-mail me the design file today?"},{"s":"M","t":"Sure. I'll send it as soon as I get back to the office."}],"graphic":{"title":"Quick Print — Poster Printing","rows":[["Size","Price per Poster"],["A3","$3"],["A2","$6"],["A1","$10"],["A0","$15"]]},"questions":[{"q":"What will the posters be used for?","choices":["A product launch","A recruiting event","A store opening","A concert"],"answer":1,"type":"세부 사항","explanation":"남자가 \"posters for our company's booth at a job fair\"라고 했으므로 채용 박람회용이다. job fair를 recruiting event로 바꿔 표현했다."},{"q":"Look at the graphic. How much will the man pay for each poster?","choices":["$10","$3","$15","$6"],"answer":0,"type":"시각 자료 연계","explanation":"가장 큰 크기는 비싸다고 하자 여자가 \"the size just below that\"을 권했고 남자가 그렇게 하기로 했다. 표에서 가장 큰 A0 바로 아래는 A1로 장당 10달러다. 15달러는 남자가 포기한 가장 큰 크기다."},{"q":"What does the woman ask the man to do?","choices":["Pay in advance","Come back this afternoon","Choose a paper color","Send a file by e-mail"],"answer":3,"type":"요청·제안","explanation":"여자가 \"Could you e-mail me the design file today?\"라고 요청했다. 포스터는 내일 오후에 준비되므로 오늘 오후에 다시 오라는 것은 오답이다."}],"translation":"M: 안녕하세요, 채용 박람회에 차릴 저희 회사 부스용 포스터를 인쇄하고 싶어요.\nW: 네. 몇 장이 필요하고 크기는 어떻게 하시겠어요?\nM: 20장이요. 가장 큰 크기를 생각했는데 저희한테는 너무 비싸네요.\nW: 많은 고객분들이 그 바로 아래 크기를 고르세요. 그래도 멀리서 잘 보여요.\nM: 좋아요, 그걸로 할게요. 언제 찾으러 오면 되나요?\nW: 내일 오후에 준비될 거예요. 디자인 파일을 오늘 이메일로 보내 주실 수 있나요?\nM: 물론이죠. 사무실에 돌아가자마자 보낼게요.","part":3},{"id":"p3-035","level":2,"topic":"호텔 체크아웃 연장과 짐 보관","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Good morning. I'm in room 512, and I'm supposed to check out at eleven. Is it possible to stay a little later?"},{"s":"M","t":"Let me check. We can give you a late check-out until one o'clock at no extra charge."},{"s":"W","t":"That would be great. My flight isn't until six, though. Is there somewhere I can leave my bags after one?"},{"s":"M","t":"Yes, we can keep your luggage behind the front desk for free."},{"s":"W","t":"Perfect. And could you call a taxi for me at three?"},{"s":"M","t":"Certainly. I'll arrange it now."}],"graphic":null,"questions":[{"q":"Where does the man most likely work?","choices":["At a taxi company","At an airport","At a hotel","At a travel agency"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"여자가 \"I'm in room 512\"라며 체크아웃 시간을 묻고, 남자가 \"behind the front desk\"에 짐을 맡아 주겠다고 하므로 호텔 직원이다. 공항과 택시는 여자의 일정에 나온 단어다."},{"q":"Until what time can the woman stay in her room?","choices":["One o'clock","Eleven o'clock","Six o'clock","Three o'clock"],"answer":0,"type":"세부 사항","explanation":"남자가 \"a late check-out until one o'clock\"을 주겠다고 했다. 11시는 원래 체크아웃 시각, 3시는 택시 시각, 6시는 비행기 시각이다."},{"q":"What does the woman ask the man to do?","choices":["Give her a room upgrade","Change her flight","Book a taxi","Carry her bags to her room"],"answer":2,"type":"요청·제안","explanation":"여자가 \"could you call a taxi for me at three?\"라고 했으므로 택시를 불러 달라는 요청이다. call a taxi를 book a taxi로 바꿔 표현했다."}],"translation":"W: 안녕하세요. 512호에 묵고 있는데 11시에 체크아웃해야 해요. 조금 더 늦게 있어도 될까요?\nM: 확인해 볼게요. 추가 요금 없이 1시까지 늦은 체크아웃을 해 드릴 수 있어요.\nW: 잘됐네요. 그런데 비행기가 6시에야 있어요. 1시 이후에 짐을 맡길 곳이 있을까요?\nM: 네, 프런트 데스크 뒤에 무료로 짐을 보관해 드릴 수 있어요.\nW: 완벽해요. 그리고 3시에 택시를 불러 주실 수 있나요?\nM: 물론이죠. 지금 바로 준비해 둘게요.","part":3},{"id":"p3-036","level":2,"topic":"박물관 단체 관람 예약","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, I'm calling to book a group tour for our staff next Wednesday. There are twenty-two of us."},{"s":"W","t":"Great. Groups of more than twenty get a ten percent discount. Which tour are you interested in?"},{"s":"M","t":"We're having lunch together first, so it has to be in the afternoon. And we work for a shipping company, so the team is interested in boats."},{"s":"W","t":"Then this one is perfect for you."},{"s":"M","t":"Great. Do we need to pay now?"},{"s":"W","t":"No, you can pay at the ticket desk when you arrive. I'll send you a confirmation e-mail."}],"graphic":{"title":"City History Museum — Group Tours","rows":[["Tour","Start Time","Length"],["Early City Life","10:00","60 min"],["The Industrial Age","11:30","90 min"],["Harbor and Ships","1:00","60 min"],["The Modern City","3:00","45 min"]]},"questions":[{"q":"What does the woman say about large groups?","choices":["They can enter early.","They receive a discount.","They must pay in advance.","They need a guide."],"answer":1,"type":"세부 사항","explanation":"여자가 \"Groups of more than twenty get a ten percent discount.\"라고 했으므로 할인을 받는다. 결제는 도착해서 해도 된다고 했으므로 미리 내야 한다는 것은 오답이다."},{"q":"Look at the graphic. What time will the man's group tour start?","choices":["At 10:00","At 3:00","At 11:30","At 1:00"],"answer":3,"type":"시각 자료 연계","explanation":"남자는 오후여야 하고 팀이 배(boats)에 관심이 있다고 했다. 표에서 오후 투어 중 배와 관련된 것은 Harbor and Ships로 1시에 시작한다. 3시 투어도 오후지만 주제가 현대 도시다."},{"q":"What will the woman send the man?","choices":["A payment receipt","A booking confirmation","A museum map","A lunch menu"],"answer":1,"type":"다음 할 일","explanation":"여자가 \"I'll send you a confirmation e-mail.\"이라고 했으므로 예약 확인 메일을 보낸다. 결제는 현장에서 하므로 영수증은 아직 없다."}],"translation":"M: 안녕하세요, 다음 주 수요일에 저희 직원들 단체 관람을 예약하려고 전화했어요. 22명이에요.\nW: 좋습니다. 20명이 넘는 단체는 10퍼센트 할인을 받아요. 어떤 투어에 관심이 있으세요?\nM: 먼저 다 같이 점심을 먹을 거라서 오후여야 해요. 그리고 저희가 해운 회사에서 일해서 팀원들이 배에 관심이 많아요.\nW: 그럼 이 투어가 딱 맞겠네요.\nM: 좋아요. 지금 결제해야 하나요?\nW: 아니요, 도착하셔서 매표소에서 결제하시면 돼요. 예약 확인 이메일을 보내 드릴게요.","part":3},{"id":"p3-037","level":2,"topic":"이삿짐 업체 방문 견적","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"Hi, thanks for coming to give me an estimate. I'm moving to a new apartment on the twentieth."},{"s":"M","t":"My pleasure. This is Carlos, the leader of our moving crew. He'll look at your furniture."},{"s":"M2","t":"Hello. Hmm, this piano will need special equipment. We'll need four people instead of three."},{"s":"W","t":"Will that cost a lot more?"},{"s":"M","t":"It adds about a hundred dollars. But we're offering a discount this month if you book within a week."},{"s":"W","t":"Great. Then I'll book today. Can you also bring some boxes?"},{"s":"M2","t":"Sure. We'll drop off twenty boxes on Friday."}],"graphic":null,"questions":[{"q":"Who most likely is Carlos?","choices":["A piano teacher from the neighborhood","A furniture seller","The head of a moving team","A building manager"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"남자가 \"This is Carlos, the leader of our moving crew.\"라고 소개했으므로 이삿짐 작업팀의 책임자다. 피아노는 옮길 물건일 뿐이다."},{"q":"Why will an extra worker be needed?","choices":["A musical instrument must be moved.","The moving date was changed.","There are too many boxes.","The apartment has no elevator."],"answer":0,"type":"세부 사항","explanation":"카를로스가 \"this piano will need special equipment. We'll need four people instead of three.\"라고 했으므로 피아노 때문이다. piano를 musical instrument로 바꿔 표현했다."},{"q":"What will happen on Friday?","choices":["The woman will move.","A payment will be made to the moving company.","A piano will be tuned.","Some boxes will be delivered."],"answer":3,"type":"세부 사항","explanation":"카를로스가 \"We'll drop off twenty boxes on Friday.\"라고 했으므로 금요일에 상자가 배달된다. 이사 날짜는 20일이다."}],"translation":"W: 안녕하세요, 견적 내러 와 주셔서 감사해요. 20일에 새 아파트로 이사해요.\nM: 별말씀을요. 이쪽은 저희 이삿짐 작업팀 팀장인 카를로스예요. 가구를 살펴볼 거예요.\nM2: 안녕하세요. 음, 이 피아노는 특수 장비가 필요하겠네요. 세 명이 아니라 네 명이 필요해요.\nW: 비용이 많이 더 드나요?\nM: 100달러 정도 추가돼요. 하지만 이번 달에는 일주일 안에 예약하시면 할인해 드려요.\nW: 잘됐네요. 그럼 오늘 예약할게요. 상자도 좀 가져다주실 수 있나요?\nM2: 물론이죠. 금요일에 상자 20개를 가져다 드릴게요.","part":3},{"id":"p3-038","level":2,"topic":"자전거 브레이크 수리","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, my bike's brakes are making a strange noise. Could you take a look?"},{"s":"W","t":"Sure. Let's see. It looks like the brake pads are worn out. We'll need to replace them."},{"s":"M","t":"How long will that take? I ride my bike to work every day."},{"s":"W","t":"We're pretty busy, but I can finish it by five today."},{"s":"M","t":"That works. I'll take the bus home tonight and pick it up tomorrow morning, then."},{"s":"W","t":"OK. We open at eight. Just give me your phone number, and I'll send you a text when it's ready."}],"graphic":null,"questions":[{"q":"What is the problem with the man's bike?","choices":["A tire has a hole that must be patched.","The seat is too low.","The chain is broken.","Some parts need to be replaced."],"answer":3,"type":"세부 사항","explanation":"여자가 \"the brake pads are worn out. We'll need to replace them.\"라고 했으므로 부품을 교체해야 한다. brake pads를 some parts로 바꿔 표현했다."},{"q":"How does the man usually get to work?","choices":["By car","On foot","By bicycle","By bus"],"answer":2,"type":"세부 사항","explanation":"남자가 \"I ride my bike to work every day.\"라고 했으므로 평소 자전거로 출근한다. 버스는 오늘 밤 집에 갈 때만 타는 것이므로 함정이다."},{"q":"What does the woman ask the man for?","choices":["A receipt","His contact information","His home address for delivery","A deposit"],"answer":1,"type":"요청·제안","explanation":"여자가 \"Just give me your phone number\"라고 했으므로 연락처를 요청했다. phone number를 contact information으로 바꿔 표현했다."}],"translation":"M: 안녕하세요, 자전거 브레이크에서 이상한 소리가 나요. 좀 봐 주실 수 있나요?\nW: 물론이죠. 어디 봐요. 브레이크 패드가 닳은 것 같네요. 교체해야 해요.\nM: 얼마나 걸릴까요? 매일 자전거로 출근하거든요.\nW: 저희가 꽤 바쁘지만 오늘 5시까지는 끝낼 수 있어요.\nM: 괜찮아요. 그럼 오늘 밤은 버스로 집에 가고 내일 아침에 찾으러 올게요.\nW: 알겠습니다. 8시에 문을 열어요. 전화번호를 알려 주시면 다 되면 문자 드릴게요.","part":3},{"id":"p3-039","level":2,"topic":"신입 직원 주차 출입증 발급","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Hi, I just started working at Lawson Consulting on the fifth floor. I was told I could get a parking permit here."},{"s":"M","t":"That's right. Do you have your employee ID card yet?"},{"s":"W","t":"Not yet. The human resources department said it'll be ready on Thursday."},{"s":"M","t":"I see. Then I can give you a temporary permit for this week. Just bring your ID card here on Thursday, and I'll give you a permanent one."},{"s":"W","t":"Thank you. Where should I park?"},{"s":"M","t":"Employees use levels two and three of the underground garage. Level one is only for visitors."}],"graphic":null,"questions":[{"q":"Why is the woman talking to the man?","choices":["To get a parking permit","To pick up an ID card","To report a lost item","To meet a client"],"answer":0,"type":"주제·목적","explanation":"여자가 \"I was told I could get a parking permit here.\"라고 했으므로 주차 출입증을 받으러 왔다. 사원증은 인사부에서 목요일에 나온다."},{"q":"What will the woman receive today?","choices":["A permanent permit","A garage key","A temporary permit","An employee ID card"],"answer":2,"type":"세부 사항","explanation":"사원증이 아직 없으므로 남자가 \"I can give you a temporary permit for this week.\"라고 했다. 정식 출입증은 목요일에 사원증을 가져오면 받는다."},{"q":"According to the man, who can park on level one?","choices":["Managers","Visitors","New employees","Delivery drivers"],"answer":1,"type":"세부 사항","explanation":"남자가 \"Level one is only for visitors.\"라고 했으므로 1층은 방문객 전용이다. 직원은 2층과 3층을 쓴다."}],"translation":"W: 안녕하세요, 5층 로슨 컨설팅에서 막 일을 시작했어요. 여기서 주차 출입증을 받을 수 있다고 들었어요.\nM: 맞아요. 사원증은 벌써 받으셨나요?\nW: 아직이요. 인사부에서 목요일에 나온다고 했어요.\nM: 그렇군요. 그럼 이번 주에 쓸 임시 출입증을 드릴게요. 목요일에 사원증을 가지고 여기 오시면 정식 출입증을 드릴게요.\nW: 감사합니다. 어디에 주차하면 되나요?\nM: 직원은 지하 주차장 2층과 3층을 써요. 1층은 방문객 전용이에요.","part":3},{"id":"p3-040","level":3,"topic":"세입자의 난방기 고장 신고","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Hi, Mr. Grant. This is Olivia from apartment 3B. I'm calling because the heater in my living room stopped working last night."},{"s":"M","t":"Oh, I'm sorry to hear that. Is the one in the bedroom still working?"},{"s":"W","t":"Yes, but it's not enough to heat the whole apartment. And the forecast says it'll be below freezing this weekend."},{"s":"M","t":"I understand. The problem is that my usual repair person is on vacation until next Wednesday."},{"s":"W","t":"Next Wednesday? It's going to be really cold."},{"s":"M","t":"You're right. I'll call another company this afternoon and see if someone can come tomorrow. In the meantime, I can bring over a portable heater from my storage room."},{"s":"W","t":"That would help a lot. I'll be home all evening."}],"graphic":null,"questions":[{"q":"What problem does the woman report?","choices":["A heating unit is broken.","Her rent has increased since last month.","A window will not close.","A pipe is leaking."],"answer":0,"type":"주제·목적","explanation":"여자가 \"the heater in my living room stopped working last night\"라고 했으므로 난방기가 고장 났다. heater를 heating unit으로 바꿔 표현했다."},{"q":"Why does the woman say, \"It's going to be really cold\"?","choices":["She is explaining why she canceled a trip this weekend.","She is asking to borrow warm clothes.","She wants to move to another apartment.","She thinks waiting for the repair would be difficult."],"answer":3,"type":"의도 파악","explanation":"수리 기사가 다음 주 수요일까지 휴가라는 말에 \"Next Wednesday?\"라고 되물은 뒤 한 말이다. 그때까지 기다리기는 힘들다는 뜻이며, 남자도 \"You're right.\"라며 다른 업체에 연락하겠다고 한다."},{"q":"What does the man offer to do?","choices":["Lower the rent for the month","Repair the heater himself","Provide a temporary heating device","Visit the apartment next Wednesday"],"answer":2,"type":"요청·제안","explanation":"남자가 \"I can bring over a portable heater from my storage room.\"이라고 했으므로 임시로 쓸 난방기를 가져다주겠다는 제안이다. 직접 고치겠다는 말은 없다."}],"translation":"W: 안녕하세요, 그랜트 씨. 3B호의 올리비아예요. 거실 난방기가 어젯밤에 멈춰서 전화드렸어요.\nM: 아, 저런. 침실에 있는 건 아직 작동하나요?\nW: 네, 그런데 그것만으로는 집 전체가 따뜻해지지 않아요. 게다가 이번 주말에 영하로 내려간다는 예보가 있어요.\nM: 이해해요. 문제는 제가 늘 부르는 수리 기사가 다음 주 수요일까지 휴가라는 거예요.\nW: 다음 주 수요일이요? 정말 추울 텐데요.\nM: 맞아요. 오늘 오후에 다른 업체에 전화해서 내일 올 수 있는지 알아볼게요. 그동안 제 창고에 있는 휴대용 난방기를 가져다 드릴게요.\nW: 그러면 정말 도움이 되겠어요. 저녁 내내 집에 있을게요.","part":3},{"id":"p3-041","level":3,"topic":"무역 박람회 부스 전원 문제","speakers":{"W":"female","M2":"male","M":"male"},"script":[{"s":"W","t":"Excuse me. We're setting up booth forty-five, but the electrical outlet here doesn't seem to be working."},{"s":"M2","t":"Let me check. You're right. This one's been giving us trouble all week. I'll get an extension cord from our office."},{"s":"M","t":"Thanks. We need power for two monitors and a coffee machine."},{"s":"M2","t":"Hmm, with a coffee machine, you'll need a heavy-duty cord. It might take about half an hour to find one."},{"s":"W","t":"That's fine. The doors don't open to visitors until ten. Mike, while we wait, why don't we put up our banner?"},{"s":"M","t":"Good idea. I'll get the ladder out of the van."}],"graphic":null,"questions":[{"q":"Where most likely are the speakers?","choices":["At a coffee shop","At a hardware store","At an electronics repair shop","At an exhibition hall"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"여자가 \"We're setting up booth forty-five\"라고 했고 방문객 입장 시각(doors don't open to visitors until ten)을 언급하므로 박람회장이다. 커피 머신은 부스에서 쓸 장비일 뿐이다."},{"q":"Why will it take some time to solve the problem?","choices":["A special cable must be found.","The booth must be moved.","An electrician is busy with another booth.","The office is closed."],"answer":0,"type":"세부 사항","explanation":"행사 직원이 커피 머신 때문에 \"you'll need a heavy-duty cord. It might take about half an hour to find one.\"이라고 했다. heavy-duty cord를 special cable로 바꿔 표현했다."},{"q":"What will Mike do next?","choices":["Buy some coffee","Get some equipment from a vehicle","Greet some visitors","Set up some monitors"],"answer":1,"type":"다음 할 일","explanation":"여자가 \"Mike\"라고 부르며 현수막을 걸자고 하자 그가 \"I'll get the ladder out of the van.\"이라고 했다. ladder를 equipment로, van을 vehicle로 바꿔 표현했다."}],"translation":"W: 실례합니다. 45번 부스를 설치하고 있는데 여기 전기 콘센트가 안 되는 것 같아요.\nM2: 확인해 볼게요. 맞네요. 이게 일주일 내내 말썽이었어요. 저희 사무실에서 연장선을 가져올게요.\nM: 고마워요. 모니터 두 대와 커피 머신에 전원이 필요해요.\nM2: 음, 커피 머신까지 쓰시려면 고용량 연장선이 필요해요. 찾는 데 30분쯤 걸릴 수 있어요.\nW: 괜찮아요. 방문객 입장은 10시부터니까요. 마이크, 기다리는 동안 우리 현수막을 거는 게 어때요?\nM: 좋은 생각이에요. 밴에서 사다리를 꺼내 올게요.","part":3},{"id":"p3-042","level":3,"topic":"최종 면접 일정과 면접실 예약","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Hi, Daniel. The candidate for the marketing manager position, Ms. Chen, confirmed she can come in on Thursday for her final interview."},{"s":"M","t":"Great. I'm in a budget meeting all morning, so it'll have to be in the afternoon."},{"s":"W","t":"That's fine. She's flying in from Chicago that morning anyway. With the skills test, the interview will take about two hours."},{"s":"M","t":"The thing is, I have to leave by three thirty to pick up my son from school."},{"s":"W","t":"No problem. Then I'll book the room that's free right after lunch. Should I ask anyone else to join?"},{"s":"M","t":"Yes, please invite Priya from the design team. She'll be working closely with whoever we hire."},{"s":"W","t":"Will do. I'll also send Ms. Chen directions to our office."}],"graphic":{"title":"Interview Room Availability — Thursday","rows":[["Room","Available"],["Room 201","9:00–11:00"],["Room 204","10:00–12:00"],["Room 310","1:00–3:00"],["Room 315","3:00–5:00"]]},"questions":[{"q":"What position is the candidate applying for?","choices":["Graphic designer","Marketing manager","Budget analyst","Sales representative"],"answer":1,"type":"세부 사항","explanation":"여자가 \"The candidate for the marketing manager position\"이라고 했다. 예산(budget)은 남자의 오전 회의, 디자인팀은 프리야의 소속 부서다."},{"q":"Look at the graphic. Which room will the woman most likely reserve?","choices":["Room 204","Room 201","Room 315","Room 310"],"answer":3,"type":"시각 자료 연계","explanation":"면접은 오후에 약 2시간 걸리고 남자는 3시 30분까지 나가야 하며, 여자가 \"the room that's free right after lunch\"를 예약하겠다고 했다. 표에서 1시~3시에 비는 310호가 맞다. 315호는 오후지만 3시에 시작해 남자가 떠나야 하는 시각과 겹친다."},{"q":"Why does the man want Priya to attend the interview?","choices":["She will work with the new employee.","She is the head of the design department.","She designed the skills test.","She knows the candidate personally."],"answer":0,"type":"세부 사항","explanation":"남자가 \"She'll be working closely with whoever we hire.\"라고 했으므로 새로 뽑을 사람과 함께 일할 사람이기 때문이다."}],"translation":"W: 안녕하세요, 대니얼. 마케팅 매니저 자리 지원자인 첸 씨가 목요일에 최종 면접을 보러 올 수 있다고 확인해 줬어요.\nM: 잘됐네요. 제가 오전 내내 예산 회의라서 오후여야 해요.\nW: 괜찮아요. 어차피 그분이 그날 아침에 시카고에서 비행기로 오거든요. 실무 테스트까지 하면 면접은 두 시간 정도 걸릴 거예요.\nM: 문제는 제가 아들을 학교에서 데려오려면 3시 반까지는 나가야 한다는 거예요.\nW: 문제없어요. 그럼 점심 직후에 비는 방을 예약할게요. 다른 분도 함께하시도록 요청할까요?\nM: 네, 디자인팀의 프리야를 불러 주세요. 누구를 뽑든 그 사람과 긴밀하게 일하게 될 거예요.\nW: 그렇게 할게요. 첸 씨에게 사무실 오시는 길도 보내 드릴게요.","part":3},{"id":"p3-043","level":3,"topic":"공장 야간 근무 교대 요청","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hey, Grace. Are you working the night shift on Saturday?"},{"s":"W","t":"No, I'm on the day shift this week. Why?"},{"s":"M","t":"My sister's getting married on Saturday evening, and I'm scheduled for the night shift. I was hoping someone could switch with me."},{"s":"W","t":"I'd love to help, but I promised my kids I'd take them camping this weekend."},{"s":"M","t":"I understand. I'll ask around."},{"s":"W","t":"Have you tried Paul? He told me he wants more night shifts because of the extra pay."},{"s":"M","t":"Really? I didn't know that. I'll go find him at lunch."},{"s":"W","t":"Just remember that any shift change has to be approved by the supervisor by Thursday."}],"graphic":null,"questions":[{"q":"Why does the man want to change his schedule?","choices":["He has a doctor's appointment.","He is going camping.","He will attend a family event.","He wants to earn extra pay."],"answer":2,"type":"세부 사항","explanation":"남자가 \"My sister's getting married on Saturday evening\"이라고 했으므로 가족 행사(누나·여동생의 결혼식)에 가야 한다. 캠핑은 여자의 계획이고, 추가 수당은 폴이 원하는 것이다."},{"q":"Why does the woman say, \"I promised my kids I'd take them camping this weekend\"?","choices":["To ask for time off from her supervisor","To explain why she is tired","To recommend a campsite","To decline the man's request"],"answer":3,"type":"의도 파악","explanation":"남자가 교대해 줄 사람을 찾자 \"I'd love to help, but\"이라며 이 말을 했으므로 부탁을 거절하는 것이다. 남자도 \"I understand.\"라며 다른 사람에게 물어보겠다고 한다."},{"q":"What does the woman remind the man about?","choices":["The lunch schedule has changed.","Night shifts pay more on weekends.","A supervisor must approve a change by a deadline.","He must work an extra shift on Thursday."],"answer":2,"type":"세부 사항","explanation":"여자가 \"any shift change has to be approved by the supervisor by Thursday\"라고 했으므로 목요일까지 감독자의 승인을 받아야 한다는 점을 상기시켰다. 목요일은 근무일이 아니라 승인 기한이다."}],"translation":"M: 저기, 그레이스. 토요일에 야간 근무예요?\nW: 아니요, 이번 주는 주간 근무예요. 왜요?\nM: 제 여동생이 토요일 저녁에 결혼하는데 제가 야간 근무로 잡혀 있어요. 누가 바꿔 줄 수 있을까 해서요.\nW: 도와주고 싶지만 이번 주말에 아이들을 캠핑에 데려가기로 약속했어요.\nM: 이해해요. 다른 사람들한테 물어볼게요.\nW: 폴한테 물어봤어요? 추가 수당 때문에 야간 근무를 더 하고 싶다고 하던데요.\nM: 정말요? 몰랐어요. 점심때 찾아가 볼게요.\nW: 근무 변경은 모두 목요일까지 감독자 승인을 받아야 한다는 것만 기억하세요.","part":3},{"id":"p3-044","level":3,"topic":"창립 기념 파티 케이터링 시식","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Everything was delicious. Thank you for setting up this tasting."},{"s":"M","t":"I'm glad you enjoyed it. Have you decided on a main course for your company's anniversary party?"},{"s":"W","t":"Well, the salmon was my favorite, but our budget is tight this year. We can't spend more than twenty-five dollars per guest."},{"s":"M","t":"I understand. A lot of our clients also like to have a vegetarian dish so that everyone has something to eat."},{"s":"W","t":"Actually, the lasagna could work for everyone. It's filling, and it's the most affordable option."},{"s":"M","t":"Good choice. I'll need the final number of guests two weeks before the event."},{"s":"W","t":"I'll send it to you once all the replies come in."}],"graphic":{"title":"Garden Table Catering — Main Courses","rows":[["Dish","Price per Guest"],["Grilled Salmon","$28"],["Roast Chicken","$22"],["Beef Stew","$25"],["Vegetable Lasagna","$19"]]},"questions":[{"q":"What event is the woman planning?","choices":["A product launch","A company celebration","A cooking class","A wedding reception for a coworker"],"answer":1,"type":"주제·목적","explanation":"남자가 \"your company's anniversary party\"라고 했으므로 회사 창립 기념 행사다. anniversary party를 company celebration으로 바꿔 표현했다."},{"q":"Look at the graphic. How much will the woman most likely pay per guest?","choices":["$19","$25","$28","$22"],"answer":0,"type":"시각 자료 연계","explanation":"여자가 \"the lasagna could work for everyone ... it's the most affordable option\"이라며 라자냐를 골랐다. 표에서 Vegetable Lasagna는 1인당 19달러다. 25달러는 여자가 말한 예산 상한이고, 28달러는 마음에 들었지만 예산을 넘는 연어 요리다."},{"q":"What does the man need from the woman?","choices":["A deposit","A list of food allergies","The number of attendees","A signed contract"],"answer":2,"type":"요청·제안","explanation":"남자가 \"I'll need the final number of guests two weeks before the event.\"라고 했으므로 최종 참석자 수가 필요하다. number of guests를 number of attendees로 바꿔 표현했다."}],"translation":"W: 전부 맛있었어요. 시식 자리를 마련해 주셔서 감사해요.\nM: 즐기셨다니 다행이에요. 회사 창립 기념 파티의 메인 요리는 정하셨나요?\nW: 음, 연어가 제일 좋았지만 올해 예산이 빠듯해요. 손님 1인당 25달러 넘게는 쓸 수 없어요.\nM: 이해해요. 저희 고객들 중 상당수는 모두가 드실 수 있도록 채식 요리도 하나 두는 걸 좋아하세요.\nW: 사실 라자냐면 모두에게 괜찮겠어요. 든든하고 가장 저렴한 메뉴잖아요.\nM: 좋은 선택이에요. 행사 2주 전까지 최종 손님 수를 알려 주셔야 해요.\nW: 회신이 다 들어오면 보내 드릴게요.","part":3},{"id":"p3-045","level":3,"topic":"팟캐스트 녹음 전 안내","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Thanks for coming in, Mr. Adams. We'll start recording in about five minutes. Can I get you some water?"},{"s":"M","t":"Yes, please. By the way, how long will the episode be?"},{"s":"W","t":"The final episode will be about thirty minutes, but we usually record for an hour and edit it down."},{"s":"M","t":"I see. I brought some notes about my new book. Is it OK if I look at them while we talk?"},{"s":"W","t":"Of course. Just try not to rustle the pages near the microphone. It picks up every sound."},{"s":"M","t":"Good to know. And when will the episode be available?"},{"s":"W","t":"It'll go online a week from Monday. I'll e-mail you the link so you can share it with your readers."}],"graphic":null,"questions":[{"q":"Who most likely is the man?","choices":["An author","A bookstore owner","A sound engineer","A radio host"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"남자가 \"my new book\"에 관한 메모를 가져왔고 여자가 \"share it with your readers\"라고 하므로 책을 쓴 작가다. 녹음을 진행하는 쪽은 여자다."},{"q":"What does the woman warn the man about?","choices":["Speaking too quickly","Going over the time limit","Drinking water near the equipment","Making noise with his papers"],"answer":3,"type":"세부 사항","explanation":"여자가 \"try not to rustle the pages near the microphone. It picks up every sound.\"라고 했으므로 종이 넘기는 소리를 내지 말라는 주의다. 물은 여자가 권한 것이지 금지한 것이 아니다."},{"q":"What will the woman send the man?","choices":["A list of interview questions","A link to the episode","A copy of the raw recording","A payment"],"answer":1,"type":"다음 할 일","explanation":"여자가 \"I'll e-mail you the link so you can share it with your readers.\"라고 했으므로 방송분 링크를 보낸다."}],"translation":"W: 와 주셔서 감사해요, 애덤스 씨. 5분쯤 뒤에 녹음을 시작할 거예요. 물 좀 드릴까요?\nM: 네, 주세요. 그런데 이번 회차는 얼마나 긴가요?\nW: 최종본은 30분 정도지만, 보통 한 시간 녹음해서 편집으로 줄여요.\nM: 그렇군요. 제 새 책에 관한 메모를 가져왔는데, 이야기하면서 봐도 될까요?\nW: 물론이죠. 다만 마이크 근처에서 종이를 바스락거리지 않도록 해 주세요. 모든 소리가 다 들어가거든요.\nM: 알아 두면 좋겠네요. 그럼 언제 공개되나요?\nW: 돌아오는 월요일에서 일주일 뒤에 온라인에 올라가요. 독자들과 공유하실 수 있게 링크를 이메일로 보내 드릴게요.","part":3},{"id":"p3-046","level":3,"topic":"운행 취소된 기차표 환불","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"Hi, my train to Boston was canceled this morning, and I'd like a refund for my ticket."},{"s":"M","t":"I'm sorry about that. May I see your ticket? Oh, this is a discount ticket. Normally, these aren't refundable."},{"s":"W","t":"But I didn't cancel the trip. The railway did."},{"s":"M","t":"Let me ask my supervisor. Mr. Hughes, do you have a moment?"},{"s":"M2","t":"Sure. What's the situation?"},{"s":"M","t":"This passenger's train was canceled, but she has a non-refundable ticket."},{"s":"M2","t":"When we cancel a train, all tickets get a full refund, including discount tickets. Go ahead and process it."},{"s":"W","t":"Thank you. How long will it take to get my money back?"},{"s":"M2","t":"It should appear on your credit card in three to five business days."}],"graphic":null,"questions":[{"q":"Why does the woman want a refund?","choices":["She bought the wrong ticket.","Her train arrived late.","She changed her travel plans.","Her train service was called off."],"answer":3,"type":"주제·목적","explanation":"여자가 \"my train to Boston was canceled this morning\"이라며 \"I didn't cancel the trip. The railway did.\"라고 했다. 철도 회사가 운행을 취소한 것이지 여자가 계획을 바꾼 것이 아니다."},{"q":"Why does the man speak with Mr. Hughes?","choices":["The woman asked to see a manager about her complaint.","He is unsure whether a refund is allowed.","He needs a new ticket printer.","He wants to take a break."],"answer":1,"type":"세부 사항","explanation":"할인 승차권은 보통 환불이 안 된다고 했다가 여자가 항의하자 \"Let me ask my supervisor.\"라며 상사에게 물었다. 환불이 가능한지 확신하지 못해서다. 여자가 관리자를 요구한 것은 아니다."},{"q":"According to Mr. Hughes, when will the woman receive her money?","choices":["Immediately","Next month","In a few business days","After she mails a form"],"answer":2,"type":"세부 사항","explanation":"휴즈 씨가 \"It should appear on your credit card in three to five business days.\"라고 했으므로 영업일 기준 며칠 안에 돌려받는다."}],"translation":"W: 안녕하세요, 오늘 아침 보스턴행 기차가 취소돼서 표를 환불받고 싶어요.\nM: 불편을 드려 죄송합니다. 표를 볼 수 있을까요? 아, 할인 승차권이네요. 보통 이건 환불이 안 돼요.\nW: 하지만 제가 여행을 취소한 게 아니잖아요. 철도 회사가 취소한 거예요.\nM: 제 상사에게 물어볼게요. 휴즈 씨, 잠깐 시간 있으세요?\nM2: 그럼요. 무슨 일이죠?\nM: 이 승객분 기차가 취소됐는데 환불 불가 승차권을 갖고 계세요.\nM2: 우리가 기차를 취소한 경우에는 할인 승차권을 포함해 모든 표를 전액 환불해요. 처리해 드리세요.\nW: 감사합니다. 돈을 돌려받기까지 얼마나 걸리나요?\nM2: 영업일 기준 3일에서 5일 안에 신용카드로 들어올 거예요.","part":3},{"id":"p3-047","level":4,"topic":"포장 상자 공급 지연","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, Ms. Ortiz. It's Kevin from Delmar Packaging. I'm afraid I have some bad news about your order of shipping boxes."},{"s":"W","t":"Oh no. What happened?"},{"s":"M","t":"One of our cutting machines broke down, and the replacement part won't arrive until next week. We can only ship about half of your order this week. The rest will go out next Monday."},{"s":"W","t":"Well, our holiday gift sets go on sale this Saturday. We'll be packing hundreds of orders on Friday."},{"s":"M","t":"I understand. How about this? We'll send the first half by express delivery at no extra cost, so you'll have it by Thursday. That should cover your first few days of sales."},{"s":"W","t":"I suppose that could work, as long as the rest arrives early next week."},{"s":"M","t":"I'll confirm the date with our production manager and call you back this afternoon."}],"graphic":null,"questions":[{"q":"Why is the man calling?","choices":["To explain a problem with an order","To confirm a delivery address","To request an overdue payment","To introduce a new type of box"],"answer":0,"type":"주제·목적","explanation":"남자가 \"I have some bad news about your order of shipping boxes\"라며 기계 고장으로 절반만 보낼 수 있다고 했다. 주문 관련 문제를 알리려는 전화다."},{"q":"Why does the woman say, \"our holiday gift sets go on sale this Saturday\"?","choices":["To indicate that the delay could cause problems","To invite the man to a sales event","To suggest a new launch date","To explain why she ordered extra boxes for the gift sets"],"answer":0,"type":"의도 파악","explanation":"나머지가 다음 주 월요일에 발송된다는 말에 이번 주 토요일 판매 시작, 금요일 포장 작업을 언급했다. 그 일정이면 상자가 부족해 곤란하다는 뜻이며, 남자도 곧바로 대안을 제시한다."},{"q":"What does the man offer?","choices":["A refund for the entire order and a free replacement","Boxes from a different factory","A discount on the next order","Free faster shipping for part of an order"],"answer":3,"type":"요청·제안","explanation":"남자가 \"We'll send the first half by express delivery at no extra cost\"라고 했으므로 주문의 일부를 추가 비용 없이 빠른 배송으로 보내 주겠다는 것이다."}],"translation":"M: 안녕하세요, 오르티스 씨. 델마 패키징의 케빈입니다. 주문하신 배송용 상자와 관련해 안 좋은 소식이 있어요.\nW: 이런. 무슨 일이죠?\nM: 재단 기계 한 대가 고장 났는데 교체 부품이 다음 주에나 와요. 이번 주에는 주문의 절반 정도만 보낼 수 있어요. 나머지는 다음 주 월요일에 발송될 거예요.\nW: 음, 저희 연말 선물 세트가 이번 주 토요일에 판매를 시작해요. 금요일에 주문 수백 건을 포장해야 하고요.\nM: 이해합니다. 이렇게 하면 어떨까요? 앞의 절반을 추가 비용 없이 특급 배송으로 보내서 목요일까지 받으시게 할게요. 판매 첫 며칠은 그걸로 충분할 거예요.\nW: 나머지가 다음 주 초에 도착한다면 그렇게 해도 될 것 같아요.\nM: 생산 관리자와 날짜를 확인하고 오늘 오후에 다시 전화드릴게요.","part":3},{"id":"p3-048","level":4,"topic":"근무 일정 관리 소프트웨어 시연","speakers":{"M":"male","W":"female","W2":"female"},"script":[{"s":"M","t":"So that's how the scheduling module works. Staff can swap shifts on their phones, and managers approve the changes with one click."},{"s":"W","t":"That's impressive. Our store managers spend hours each week on schedules right now. Lisa, what do you think?"},{"s":"W2","t":"I like it, but I'm more interested in the payroll side. Can the hours go straight into our payroll system?"},{"s":"M","t":"Yes, we connect with most major payroll programs. Which one do you use?"},{"s":"W2","t":"We use a program our IT team built in-house about ten years ago."},{"s":"M","t":"Ah, then we'd need to build a custom connection. That's possible, but it would add about six weeks to the setup."},{"s":"W","t":"Hmm. We were hoping to have everything running before the holiday season."},{"s":"M","t":"Then one option is to start with scheduling now and add the payroll connection in January."}],"graphic":null,"questions":[{"q":"What is the man demonstrating?","choices":["A payroll accounting service","Software for managing work schedules","A new mobile phone","A store security system"],"answer":1,"type":"주제·목적","explanation":"남자가 \"that's how the scheduling module works\"라며 직원이 휴대전화로 근무를 바꾸고 관리자가 승인하는 기능을 보여 주고 있다. 급여 연동은 질문에서 나온 부가 기능이다."},{"q":"Why would the setup take longer than usual?","choices":["The software is still being tested.","The company has too many stores.","The company uses a system it developed itself.","The IT team is too busy."],"answer":2,"type":"세부 사항","explanation":"리사가 \"a program our IT team built in-house\"를 쓴다고 하자 남자가 맞춤 연동을 만들어야 해서 6주가 더 걸린다고 했다. built in-house를 developed itself로 바꿔 표현했다."},{"q":"What does the man suggest?","choices":["Introducing the product in stages","Replacing the payroll system","Postponing the purchase until January","Hiring additional IT staff"],"answer":0,"type":"요청·제안","explanation":"남자가 \"start with scheduling now and add the payroll connection in January\"라고 했으므로 단계적으로 도입하자는 제안이다. 구매 자체를 1월로 미루자는 것이 아니라 급여 연동만 1월에 추가하자는 것이다."}],"translation":"M: 일정 관리 모듈은 이렇게 작동합니다. 직원들은 휴대전화로 근무를 서로 바꾸고, 관리자는 클릭 한 번으로 변경을 승인하죠.\nW: 인상적이네요. 지금 저희 매장 관리자들은 매주 근무표에 몇 시간씩 써요. 리사, 어떻게 생각해요?\nW2: 마음에 들어요. 그런데 저는 급여 쪽이 더 궁금해요. 근무 시간이 저희 급여 시스템으로 바로 들어갈 수 있나요?\nM: 네, 주요 급여 프로그램 대부분과 연동됩니다. 어떤 걸 쓰시나요?\nW2: 저희 IT팀이 10년쯤 전에 자체 개발한 프로그램을 써요.\nM: 아, 그럼 맞춤 연동을 만들어야겠네요. 가능은 하지만 설치 기간이 6주 정도 늘어나요.\nW: 음. 연말 성수기 전에 모두 가동하길 바랐는데요.\nM: 그럼 한 가지 방법은 지금 일정 관리부터 시작하고 급여 연동은 1월에 추가하는 거예요.","part":3},{"id":"p3-049","level":4,"topic":"텀블러 신제품 마케팅 아이디어 회의","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"OK, everyone. Our new line of reusable water bottles launches in April, and we need a campaign idea. Any thoughts?"},{"s":"M","t":"What about partnering with local gyms? We could give out free bottles at their front desks."},{"s":"M2","t":"We did something similar with our lunch boxes last year."},{"s":"W","t":"Right, Ryan, and sales barely moved. What else have we got?"},{"s":"M2","t":"Well, the bottles keep drinks cold for twenty-four hours. What if customers posted videos testing that, say, at the beach or on a long hike?"},{"s":"M","t":"A social media challenge. And we could give a prize for the most creative video."},{"s":"W","t":"I like that. Tom, can you figure out what the prizes would cost? I'll need numbers before I take this to the director on Friday."},{"s":"M","t":"Sure. I'll have an estimate by Wednesday."}],"graphic":null,"questions":[{"q":"What product will be promoted?","choices":["Lunch boxes","Drink containers","Hiking boots","Exercise equipment"],"answer":1,"type":"주제·목적","explanation":"여자가 \"Our new line of reusable water bottles launches in April\"라고 했다. water bottles를 drink containers로 바꿔 표현했다. 도시락통은 작년 판촉에 쓴 제품이다."},{"q":"Why does Ryan say, \"We did something similar with our lunch boxes last year\"?","choices":["To suggest reusing an old design","To explain why a product was discontinued","To express doubt about a proposal","To praise a colleague's past work"],"answer":2,"type":"의도 파악","explanation":"헬스장에서 무료로 나눠 주자는 제안에 라이언이 작년에 비슷한 것을 했다고 말하자 여자가 \"sales barely moved\"라고 받는다. 효과가 없었던 방법이라며 제안에 의문을 제기한 것이다."},{"q":"What does the woman ask Tom to do?","choices":["Film a promotional video","Contact local gyms","Meet with the director","Estimate some expenses"],"answer":3,"type":"요청·제안","explanation":"여자가 \"Tom, can you figure out what the prizes would cost?\"라고 했으므로 비용을 산출해 달라는 요청이다. 이사에게 보고하는 것은 여자 자신이다."}],"translation":"W: 자, 여러분. 새 재사용 물병 제품군이 4월에 출시되니 캠페인 아이디어가 필요해요. 의견 있어요?\nM: 지역 헬스장과 제휴하는 건 어때요? 헬스장 안내 데스크에서 물병을 무료로 나눠 줄 수 있어요.\nM2: 작년에 도시락통으로 비슷한 걸 했었죠.\nW: 맞아요, 라이언, 그리고 판매는 거의 변화가 없었죠. 다른 건 뭐가 있을까요?\nM2: 음, 이 물병은 음료를 24시간 동안 차갑게 유지하잖아요. 고객들이 해변이나 긴 등산길에서 그걸 시험하는 영상을 올리게 하면 어떨까요?\nM: 소셜 미디어 챌린지네요. 그리고 가장 창의적인 영상에 상품을 줄 수도 있고요.\nW: 마음에 들어요. 톰, 상품 비용이 얼마나 들지 계산해 줄 수 있어요? 금요일에 이사님께 보고하기 전에 수치가 필요해요.\nM: 물론이죠. 수요일까지 견적을 드릴게요.","part":3},{"id":"p3-050","level":4,"topic":"공유 오피스 요금제 선택","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Thanks for the tour. The space is great. There are five of us on the team right now."},{"s":"M","t":"Then the Team plan would be too small for you. You'd need at least the next one up."},{"s":"W","t":"Right. We're also hiring two developers next month, though."},{"s":"M","t":"In that case, you might want to consider the Suite. Otherwise, you'd have to move again soon."},{"s":"W","t":"That's more than we can afford right now. If we sign up for six desks, can we add desks later without changing plans?"},{"s":"M","t":"Yes. Extra desks can be added for two hundred dollars each per month."},{"s":"W","t":"Then let's start with the six-desk plan. Could you send me the contract so I can review it with my business partner?"}],"graphic":{"title":"Hive Workspace — Monthly Plans","rows":[["Plan","Desks","Meeting Room Hours","Price"],["Solo","1","5","$300"],["Team","4","10","$1,000"],["Studio","6","20","$1,400"],["Suite","10","Unlimited","$2,200"]]},"questions":[{"q":"Who most likely is the woman?","choices":["An interior designer","A software developer","A business owner","A real estate agent"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"여자는 팀원 수와 채용 계획을 말하고 \"my business partner\"와 계약서를 검토하겠다고 하므로 회사를 운영하는 사업주다. 개발자는 앞으로 채용할 직원이다."},{"q":"Look at the graphic. Which plan will the woman most likely choose?","choices":["Team","Suite","Solo","Studio"],"answer":3,"type":"시각 자료 연계","explanation":"여자가 \"let's start with the six-desk plan\"이라고 했다. 표에서 책상 6개짜리는 Studio다. Suite는 남자가 권했지만 여자가 감당하기 어렵다고 했고, Team은 5명에게 너무 작다."},{"q":"What does the woman ask the man to do?","choices":["Send an agreement for review","Lower the monthly price","Reserve a meeting room","Give her a second tour"],"answer":0,"type":"요청·제안","explanation":"여자가 \"Could you send me the contract so I can review it with my business partner?\"라고 했다. contract를 agreement로 바꿔 표현했다."}],"translation":"W: 둘러보게 해 주셔서 감사해요. 공간이 훌륭하네요. 지금 저희 팀은 다섯 명이에요.\nM: 그럼 팀 요금제는 너무 작겠네요. 적어도 한 단계 위가 필요하실 거예요.\nW: 맞아요. 그런데 다음 달에 개발자 두 명을 더 뽑을 예정이에요.\nM: 그렇다면 스위트를 고려해 보셔도 좋겠어요. 그렇지 않으면 곧 또 옮기셔야 할 테니까요.\nW: 그건 지금 저희가 감당하기 어려워요. 책상 6개로 가입하면 나중에 요금제를 바꾸지 않고 책상을 추가할 수 있나요?\nM: 네. 추가 책상은 하나당 월 200달러에 늘릴 수 있어요.\nW: 그럼 책상 6개짜리 요금제로 시작할게요. 사업 파트너와 검토할 수 있게 계약서를 보내 주시겠어요?","part":3},{"id":"p3-051","level":4,"topic":"사내 봉사의 날 참여 신청","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, Sandra. I'm signing my team up for the company volunteer day. There are six of us, and we'd like to stay together."},{"s":"W","t":"Great. Here's the list of places that still have openings."},{"s":"M","t":"Hmm. Everyone wanted the food bank, but that won't work now. And Jake is recovering from a back injury, so we should avoid anything with digging or ladders."},{"s":"W","t":"That rules out a couple of options. But most teams find this one very rewarding, and it's easy on the body."},{"s":"M","t":"That could be fun. I'll check with the team and get back to you."},{"s":"W","t":"Just so you know, the sign-up form closes at noon today."},{"s":"M","t":"Oh, then I'll send a group message right now."}],"graphic":{"title":"Volunteer Day Options — May 14","rows":[["Organization","Activity","Spots Left"],["Riverside Park","Planting trees","12"],["City Food Bank","Sorting donations","3"],["Maple Library","Reading to children","8"],["Harbor Shelter","Painting walls","15"]]},"questions":[{"q":"What is the man trying to do?","choices":["Organize a fundraiser for the library","Register a group for an event","Recruit new employees","Book a meeting room"],"answer":1,"type":"주제·목적","explanation":"남자가 \"I'm signing my team up for the company volunteer day\"라고 했으므로 팀 단위로 행사 참가 신청을 하려는 것이다."},{"q":"Look at the graphic. Where will the man's team most likely volunteer?","choices":["City Food Bank","Harbor Shelter","Maple Library","Riverside Park"],"answer":2,"type":"시각 자료 연계","explanation":"6명이 함께해야 하는데 푸드뱅크는 3자리뿐이라 안 되고, 허리 부상 때문에 땅 파기(나무 심기)와 사다리(벽 칠하기)도 피해야 한다. 남은 것은 몸에 부담이 적은 Maple Library의 책 읽어 주기(8자리)다."},{"q":"Why does the woman say, \"the sign-up form closes at noon today\"?","choices":["To urge the man to respond soon","To apologize for a mistake","To explain why a list is incomplete","To ask the man to collect forms"],"answer":0,"type":"의도 파악","explanation":"남자가 팀원들과 확인한 뒤 알려 주겠다고 하자 신청이 오늘 정오에 마감된다고 알렸다. 서둘러 결정하라는 뜻이며, 남자도 \"then I'll send a group message right now\"라고 반응한다."}],"translation":"M: 안녕하세요, 샌드라. 회사 봉사의 날에 우리 팀을 신청하려고요. 여섯 명인데 다 같이 하고 싶어요.\nW: 좋아요. 아직 자리가 남은 곳 목록이 여기 있어요.\nM: 음. 다들 푸드뱅크를 원했는데 이제 그건 안 되겠네요. 그리고 제이크가 허리 부상에서 회복 중이라 땅을 파거나 사다리를 쓰는 일은 피해야 해요.\nW: 그러면 두어 개는 제외되네요. 그래도 대부분의 팀이 이곳을 아주 보람 있어 하고, 몸에도 무리가 없어요.\nM: 재미있겠네요. 팀원들과 확인하고 다시 알려 드릴게요.\nW: 참고로 신청서는 오늘 정오에 마감돼요.\nM: 아, 그럼 지금 바로 단체 메시지를 보낼게요.","part":3},{"id":"p3-052","level":4,"topic":"사용 설명서 번역 견적 문의","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, I received your quote for translating our user manual into Spanish and Portuguese. I just have a couple of questions."},{"s":"W","t":"Of course. What would you like to know?"},{"s":"M","t":"The price is a bit higher than we expected. Is there any way to bring it down?"},{"s":"W","t":"Well, much of the manual repeats the same safety instructions. If you send us the original design files instead of PDFs, our software can detect the repeated text, and we charge much less for those parts."},{"s":"M","t":"That's good to know. I'll ask our design team for the original files."},{"s":"W","t":"Also, the quote assumes a three-week schedule. If you need it sooner, there's a rush fee."},{"s":"M","t":"Three weeks is fine. The product won't be released in those markets until the fall."}],"graphic":null,"questions":[{"q":"What type of business does the woman most likely work for?","choices":["A design firm","A printing company","A software developer","A translation agency"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"남자가 \"your quote for translating our user manual\"이라며 여자 쪽 견적서를 언급하므로 번역 업체다. 소프트웨어와 디자인팀은 대화에 나온 단어를 이용한 오답이다."},{"q":"According to the woman, how could the man lower the cost?","choices":["By translating into only one language","By providing files in a different format","By removing the safety instructions","By accepting a longer schedule"],"answer":1,"type":"세부 사항","explanation":"여자가 \"If you send us the original design files instead of PDFs\"라면 반복되는 부분을 싸게 해 줄 수 있다고 했다. PDF 대신 다른 형식의 파일을 주면 비용이 준다."},{"q":"What does the man say about the product?","choices":["It is already sold in Spain.","Its design is being changed.","It has had safety problems.","It will be launched abroad later in the year."],"answer":3,"type":"세부 사항","explanation":"남자가 \"The product won't be released in those markets until the fall.\"이라고 했으므로 해외 시장 출시는 올가을이다. 안전 지침(safety instructions)은 설명서 내용일 뿐 안전 문제가 있었다는 말은 없다."}],"translation":"M: 안녕하세요, 저희 사용 설명서를 스페인어와 포르투갈어로 번역하는 견적서를 받았어요. 몇 가지 여쭤볼 게 있어서요.\nW: 물론이죠. 무엇이 궁금하세요?\nM: 가격이 예상보다 조금 높아요. 낮출 방법이 있을까요?\nW: 음, 설명서의 상당 부분이 같은 안전 지침을 반복해요. PDF 대신 원본 디자인 파일을 보내 주시면 저희 소프트웨어가 반복되는 문장을 찾아내서, 그 부분은 요금을 훨씬 적게 받아요.\nM: 좋은 정보네요. 디자인팀에 원본 파일을 요청할게요.\nW: 그리고 견적은 3주 일정을 기준으로 했어요. 더 빨리 필요하시면 긴급 요금이 붙어요.\nM: 3주면 괜찮아요. 그 시장들에는 가을이 돼야 제품이 출시되거든요.","part":3},{"id":"p3-053","level":4,"topic":"카탈로그 야외 촬영 날씨 문제","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Hi, Marcus. I've finished shooting the chairs for the spring catalog, but I'm having trouble with the outdoor table set."},{"s":"M","t":"What's the problem?"},{"s":"W","t":"The forecast says it'll rain all week, and your team wanted those photos taken in a garden."},{"s":"M","t":"Hmm. The catalog goes to the printer on the twelfth, so we really can't wait."},{"s":"W","t":"One option is to shoot it in my studio and add a garden background digitally. It looks quite natural these days."},{"s":"M","t":"I'd want to see an example first. Our director is very particular about how our products look."},{"s":"W","t":"No problem. I'll send you a few samples from past projects this afternoon."}],"graphic":null,"questions":[{"q":"What are the speakers mainly discussing?","choices":["A problem with a photo shoot","A delay at a printing company","A garden renovation","A change to a furniture design"],"answer":0,"type":"주제·목적","explanation":"여자가 야외용 테이블 세트 촬영이 \"trouble\"이라며 비 예보 때문에 정원에서 찍을 수 없다고 한다. 사진 촬영 문제에 관한 대화다. 인쇄소는 마감 일정으로만 언급된다."},{"q":"Why can't the man wait for better weather?","choices":["The director is leaving on a trip.","The studio is fully booked.","A publication has a fixed deadline.","The furniture must be returned soon."],"answer":2,"type":"세부 사항","explanation":"남자가 \"The catalog goes to the printer on the twelfth, so we really can't wait.\"라고 했으므로 카탈로그 인쇄 마감이 정해져 있기 때문이다."},{"q":"What will the woman do this afternoon?","choices":["Print a draft catalog","Send some sample images","Meet with the director","Take photos in a garden"],"answer":1,"type":"다음 할 일","explanation":"남자가 예시를 먼저 보고 싶다고 하자 여자가 \"I'll send you a few samples from past projects this afternoon.\"이라고 했다."}],"translation":"W: 안녕하세요, 마커스. 봄 카탈로그용 의자 촬영은 끝냈는데, 야외용 테이블 세트가 문제예요.\nM: 무슨 문제인데요?\nW: 일주일 내내 비가 온다는 예보가 있는데, 그쪽 팀은 그 사진을 정원에서 찍기를 원했잖아요.\nM: 음. 카탈로그가 12일에 인쇄소로 넘어가니 정말 기다릴 수가 없어요.\nW: 한 가지 방법은 제 스튜디오에서 찍고 정원 배경을 디지털로 합성하는 거예요. 요즘은 꽤 자연스러워 보여요.\nM: 먼저 예시를 보고 싶어요. 저희 이사님이 제품이 어떻게 보이는지에 아주 까다로우시거든요.\nW: 문제없어요. 오늘 오후에 예전 작업 샘플 몇 개를 보내 드릴게요.","part":3},{"id":"p3-054","level":5,"topic":"친환경 포장재 공급업체 선정","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"I've narrowed our packaging options down to four suppliers. We need to decide before the new product line ships."},{"s":"M","t":"That's in about five weeks, right? So anything that can't be delivered by then is out, regardless of price."},{"s":"W","t":"Agreed. Which is a shame, because the molded pulp was the cheapest by far."},{"s":"M","t":"What about the cornstarch film? It's the fastest."},{"s":"W","t":"I thought about that, but our biggest retail partner just announced that starting next year, all packaging has to go in standard recycling bins. Cornstarch film has to be composted instead."},{"s":"M","t":"Then there's really only one choice left. It's a few cents more than we pay now, though, so I'll have to justify it to finance."},{"s":"W","t":"I've already put together a summary of our customer survey showing how buyers feel about eco-friendly packaging. I'll forward it to you."}],"graphic":{"title":"Packaging Supplier Comparison","rows":[["Supplier","Material","Cost per Unit","Lead Time"],["EcoWrap","Recycled paper","$0.42","3 weeks"],["GreenFold","Mushroom foam","$0.55","6 weeks"],["PulpPro","Molded pulp","$0.38","8 weeks"],["TerraPak","Cornstarch film","$0.47","2 weeks"]]},"questions":[{"q":"What are the speakers mainly discussing?","choices":["Negotiating with a retail partner","Reducing shipping costs","Designing a new product line","Selecting a vendor"],"answer":3,"type":"주제·목적","explanation":"여자가 \"I've narrowed our packaging options down to four suppliers.\"라며 공급업체 넷 중 하나를 고르는 대화를 시작한다. 소매 협력사는 조건을 제시한 쪽으로만 언급될 뿐 협상하는 것이 아니다."},{"q":"Look at the graphic. Which supplier will the company most likely use?","choices":["GreenFold","EcoWrap","PulpPro","TerraPak"],"answer":1,"type":"시각 자료 연계","explanation":"약 5주 안에 받아야 하므로 납기 6주(GreenFold)와 8주(PulpPro)는 탈락하고, 옥수수 전분 필름(TerraPak)은 일반 재활용함에 넣을 수 없어 제외된다. 남는 것은 재생지를 쓰는 EcoWrap이다. PulpPro는 가장 싸지만 납기 때문에 탈락한 함정이다."},{"q":"What will the woman send to the man?","choices":["The results of a customer survey","A contract from a supplier","A revised budget","A sample package"],"answer":0,"type":"다음 할 일","explanation":"여자가 \"a summary of our customer survey showing how buyers feel about eco-friendly packaging. I'll forward it to you.\"라고 했으므로 고객 설문 결과를 보낸다. 재무팀 설득은 남자가 할 일이다."}],"translation":"W: 포장재 후보를 공급업체 네 곳으로 좁혔어요. 신제품 라인이 출하되기 전에 결정해야 해요.\nM: 그게 5주 정도 남았죠? 그럼 그때까지 납품하지 못하는 곳은 가격과 상관없이 제외예요.\nW: 동의해요. 아쉽긴 해요. 펄프 성형품이 단연 가장 쌌거든요.\nM: 옥수수 전분 필름은요? 그게 제일 빠르잖아요.\nW: 그것도 생각해 봤는데, 우리 최대 소매 협력사가 내년부터 모든 포장재는 일반 재활용함에 넣을 수 있어야 한다고 발표했어요. 옥수수 전분 필름은 퇴비로 처리해야 하고요.\nM: 그럼 사실상 선택지가 하나밖에 안 남네요. 그래도 지금 내는 것보다 몇 센트 더 비싸니까 재무팀에 근거를 대야 해요.\nW: 구매자들이 친환경 포장을 어떻게 생각하는지 보여 주는 고객 설문 요약을 이미 만들어 뒀어요. 전달해 드릴게요.","part":3},{"id":"p3-055","level":5,"topic":"멤버십 프로그램 개편 효과 분석","speakers":{"W":"female","M":"male","W2":"female"},"script":[{"s":"W","t":"The data's in. Since we switched our loyalty program from points to monthly coupons, sign-ups have doubled."},{"s":"M","t":"True, but average spending per visit has dropped about eight percent. Members seem to come in, use the coupon, and leave."},{"s":"W2","t":"That matches what my store managers are telling me. They say coupon users rarely pick up anything else."},{"s":"W","t":"Hmm. So we're attracting more members, but not the kind we want."},{"s":"M","t":"One idea is to make the coupon valid only on purchases over a certain amount, say thirty dollars."},{"s":"W2","t":"The staff would welcome that. Right now, they spend a lot of time explaining which items the coupons cover."},{"s":"W","t":"Well, the board meets on the tenth. Samir, could you model what spending would look like with that minimum in place?"},{"s":"M","t":"I can have something ready by Monday."}],"graphic":null,"questions":[{"q":"What change did the company recently make?","choices":["It raised the prices of many of its products.","It opened several new stores.","It replaced a points system with coupons.","It hired more store managers."],"answer":2,"type":"세부 사항","explanation":"여자가 \"we switched our loyalty program from points to monthly coupons\"라고 했으므로 포인트 제도를 월간 쿠폰으로 바꿨다."},{"q":"What does the woman mean when she says, \"we're attracting more members, but not the kind we want\"?","choices":["The program costs too much to advertise.","The new members are not spending enough.","Too many members are complaining.","Store staff need more training."],"answer":1,"type":"의도 파악","explanation":"가입자는 두 배가 됐지만 방문당 지출이 8퍼센트 줄고 쿠폰만 쓰고 떠난다는 말을 듣고 한 말이다. 회원 수는 늘었지만 돈을 충분히 쓰지 않는 회원이라는 뜻이다."},{"q":"What does the woman ask Samir to do?","choices":["Train store employees","Design a new coupon","Present the survey data to the board on the tenth","Project the effect of a proposed rule"],"answer":3,"type":"요청·제안","explanation":"여자가 \"Samir, could you model what spending would look like with that minimum in place?\"라고 했으므로 최소 구매 금액 조건을 두었을 때 지출이 어떻게 될지 예측해 달라는 요청이다. 이사회는 10일에 열리는 일정으로만 언급된다."}],"translation":"W: 데이터가 나왔어요. 멤버십 프로그램을 포인트에서 월간 쿠폰으로 바꾼 뒤로 가입자가 두 배가 됐어요.\nM: 맞아요, 하지만 방문당 평균 지출은 8퍼센트 정도 줄었어요. 회원들이 와서 쿠폰만 쓰고 가는 것 같아요.\nW2: 제 매장 관리자들이 하는 말과 같네요. 쿠폰 사용자들은 다른 물건을 거의 안 산대요.\nW: 음. 그러니까 회원은 더 많이 모으고 있지만 우리가 원하는 회원은 아닌 거네요.\nM: 한 가지 방법은 쿠폰을 일정 금액, 예를 들어 30달러 이상 구매할 때만 쓸 수 있게 하는 거예요.\nW2: 직원들이 반길 거예요. 지금은 어떤 품목에 쿠폰이 적용되는지 설명하느라 시간을 많이 쓰거든요.\nW: 음, 이사회가 10일에 열려요. 사미르, 그 최소 금액을 적용하면 지출이 어떻게 될지 모델을 만들어 줄 수 있어요?\nM: 월요일까지 준비할 수 있어요.","part":3},{"id":"p3-056","level":5,"topic":"프랜차이즈 매장 위생 점검","speakers":{"M":"male","W":"female","M2":"male"},"script":[{"s":"M","t":"Thanks for walking me through the restaurant, Ms. Rao. Overall, things look very good. The dining area is spotless."},{"s":"W","t":"I'm glad to hear it. Was there anything that concerned you?"},{"s":"M","t":"Just one thing. The temperature log for the walk-in refrigerator is missing entries for the past three evenings."},{"s":"M2","t":"As kitchen manager, that's my responsibility. Our evening supervisor left last week, and I never reassigned that task."},{"s":"M","t":"I understand, but it's a required check. Without it, I can't give this location a full pass."},{"s":"W","t":"What would we need to do?"},{"s":"M","t":"Send me the completed logs for the next two weeks, and I'll update the report. Until then, it'll be marked as conditional."},{"s":"M2","t":"I'll add it to the closing checklist today, so whoever closes will record the temperature."}],"graphic":null,"questions":[{"q":"Who most likely is the first man?","choices":["A restaurant customer","A refrigerator technician","An inspector from a head office","A new kitchen supervisor hired last week"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"첫 번째 남자가 매장을 둘러본 뒤 필수 점검 항목이 빠져 \"full pass\"를 줄 수 없고 보고서를 수정하겠다고 하므로 본사에서 나온 점검 담당자다. 냉장고는 점검 대상일 뿐 남자가 수리 기사인 것은 아니다."},{"q":"Why were some records not completed?","choices":["The person responsible for them had left.","The refrigerator was broken.","The forms had been misplaced.","The restaurant was closed in the evenings."],"answer":0,"type":"세부 사항","explanation":"주방 관리자가 \"Our evening supervisor left last week, and I never reassigned that task.\"라고 했다. 그 일을 맡던 사람이 그만둔 뒤 다른 사람에게 넘기지 않았기 때문이다."},{"q":"What does the kitchen manager say he will do today?","choices":["Hire an evening supervisor","Repair a refrigerator","Mail a report to the inspector","Revise a list of end-of-day tasks"],"answer":3,"type":"다음 할 일","explanation":"주방 관리자가 \"I'll add it to the closing checklist today\"라고 했으므로 마감 업무 목록을 고친다. closing checklist를 list of end-of-day tasks로 바꿔 표현했다. 기록을 보내는 것은 2주 뒤의 일이다."}],"translation":"M: 식당을 안내해 주셔서 감사합니다, 라오 씨. 전반적으로 아주 좋네요. 홀은 티 없이 깨끗하고요.\nW: 다행이네요. 걱정되는 점이 있었나요?\nM: 한 가지만요. 대형 냉장실 온도 기록부에 지난 사흘 저녁 기록이 빠져 있어요.\nM2: 주방 관리자로서 제 책임이에요. 저녁 담당 관리자가 지난주에 그만뒀는데 그 업무를 다른 사람에게 넘기지 않았어요.\nM: 이해하지만 필수 점검 항목이에요. 그게 없으면 이 매장에 완전 통과를 드릴 수 없어요.\nW: 저희가 무엇을 해야 할까요?\nM: 앞으로 2주 동안 작성한 기록부를 보내 주시면 보고서를 수정할게요. 그때까지는 조건부로 표시됩니다.\nM2: 오늘 마감 점검표에 그 항목을 넣어서 마감하는 사람이 누구든 온도를 기록하게 할게요.","part":3},{"id":"p3-057","level":5,"topic":"건물 설계 수정안 검토","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"I've looked over the revised floor plans. I like how you've opened up the lobby."},{"s":"W","t":"Thank you. We moved the reception desk so visitors can see the courtyard as soon as they walk in."},{"s":"M","t":"About the rooftop terrace, though. The board is concerned about the maintenance costs."},{"s":"W","t":"I see. Well, the terrace was what the city's planning committee liked most about the proposal."},{"s":"M","t":"Oh, I didn't realize it had come up during the approval process."},{"s":"W","t":"It did. If we remove it, we may have to go back for another review, and that could take two or three months."},{"s":"M","t":"Then I'd rather keep it. Could you put together an estimate of the yearly maintenance costs so I can show the board?"},{"s":"W","t":"Sure. I'll ask our landscape consultant for figures."}],"graphic":null,"questions":[{"q":"What does the man like about the revised plans?","choices":["The reduced construction budget","The location of the parking lot","The more open entrance area","The rooftop terrace"],"answer":2,"type":"세부 사항","explanation":"남자가 \"I like how you've opened up the lobby.\"라고 했으므로 탁 트인 로비가 마음에 든다. 옥상 테라스는 이사회가 유지비를 걱정하는 부분이다."},{"q":"Why does the woman say, \"the terrace was what the city's planning committee liked most about the proposal\"?","choices":["To take credit for the design of the rooftop terrace","To suggest that removing a feature could be risky","To complain about the committee's decision","To propose adding more green space"],"answer":1,"type":"의도 파악","explanation":"이사회가 테라스 유지비를 걱정한다는 말에 이렇게 답한 뒤, 없애면 재심사로 두세 달이 걸릴 수 있다고 덧붙인다. 테라스를 빼면 승인에 문제가 생길 수 있다는 점을 알리려는 것이다."},{"q":"What does the man ask the woman to do?","choices":["Estimate ongoing upkeep expenses","Hire a landscape consultant","Schedule a meeting with the city","Remove the terrace from the plans"],"answer":0,"type":"요청·제안","explanation":"남자가 \"Could you put together an estimate of the yearly maintenance costs\"라고 요청했다. yearly maintenance costs를 ongoing upkeep expenses로 바꿔 표현했다. 조경 컨설턴트는 여자가 이미 함께 일하는 사람으로 새로 고용하는 것이 아니다."}],"translation":"M: 수정된 평면도를 검토했어요. 로비를 탁 트이게 한 점이 마음에 들어요.\nW: 감사합니다. 방문객이 들어오자마자 안뜰이 보이도록 안내 데스크를 옮겼어요.\nM: 그런데 옥상 테라스 말인데요. 이사회가 유지 관리비를 걱정하고 있어요.\nW: 그렇군요. 음, 그 테라스가 시 도시계획위원회가 이 안에서 가장 마음에 들어 한 부분이었어요.\nM: 아, 그게 승인 과정에서 거론된 줄은 몰랐네요.\nW: 그랬어요. 그걸 없애면 다시 심사를 받아야 할 수도 있는데, 두세 달이 걸릴 수 있어요.\nM: 그럼 남겨 두는 게 낫겠네요. 이사회에 보여 줄 수 있게 연간 유지 관리비 견적을 정리해 주시겠어요?\nW: 물론이죠. 저희 조경 컨설턴트에게 수치를 요청할게요.","part":3},{"id":"p3-058","level":5,"topic":"해외 지사 급여 시스템 단계별 도입","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"How is the payroll system rollout going?"},{"s":"M","t":"The first phase went smoothly. Toronto ran its first payroll last week without a single error."},{"s":"W","t":"That's great news. And the next one is still on schedule?"},{"s":"M","t":"Yes, Mexico City is ready. The issue is the phase right after that. The local government just changed how employers have to report income tax, and the vendor hasn't updated the software yet."},{"s":"W","t":"How long do they need?"},{"s":"M","t":"They've promised a fix by the end of May, but I'd want at least three weeks of testing after that. So we're probably looking at a delay of about six weeks."},{"s":"W","t":"That's acceptable, as long as the last phase isn't pushed back as well. The team there is already hiring based on that date."},{"s":"M","t":"It shouldn't be. A separate team is handling it."}],"graphic":{"title":"Payroll System Rollout","rows":[["Phase","Office","Go-Live Date"],["1","Toronto","March 3"],["2","Mexico City","April 7"],["3","São Paulo","May 12"],["4","Madrid","June 9"]]},"questions":[{"q":"Who most likely is the man?","choices":["A software vendor","A tax accountant","A manager overseeing a system implementation","A recruiter"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"남자는 급여 시스템 도입 단계별 진행 상황을 보고하고 테스트 기간을 판단하므로 시스템 도입을 총괄하는 사람이다. 공급업체(vendor)는 남자가 기다리고 있는 외부 회사다."},{"q":"Look at the graphic. Which office's launch will be delayed?","choices":["Madrid","Toronto","Mexico City","São Paulo"],"answer":3,"type":"시각 자료 연계","explanation":"남자가 멕시코시티는 준비됐고 \"The issue is the phase right after that.\"이라고 했다. 표에서 멕시코시티(2단계) 바로 다음은 3단계 상파울루다. 마드리드는 마지막 단계로, 여자가 늦어지지 않기를 바라는 곳이다."},{"q":"Why is the woman concerned about the final phase?","choices":["It uses a different software vendor.","An office is making staffing decisions based on it.","It involves the largest number of employees.","Its tax rules have also changed."],"answer":1,"type":"세부 사항","explanation":"여자가 \"The team there is already hiring based on that date.\"라고 했으므로 그 지사가 도입 날짜에 맞춰 채용을 진행하고 있기 때문이다. hiring을 staffing decisions로 바꿔 표현했다."}],"translation":"W: 급여 시스템 도입은 어떻게 되고 있어요?\nM: 1단계는 순조로웠어요. 토론토가 지난주에 첫 급여를 오류 하나 없이 처리했어요.\nW: 좋은 소식이네요. 다음 단계도 여전히 일정대로인가요?\nM: 네, 멕시코시티는 준비됐어요. 문제는 그다음 단계예요. 그 나라 정부가 고용주의 소득세 신고 방식을 막 바꿨는데, 공급업체가 아직 소프트웨어를 업데이트하지 않았어요.\nW: 얼마나 필요하대요?\nM: 5월 말까지 수정본을 주겠다고 약속했지만, 그 뒤로 적어도 3주는 테스트하고 싶어요. 그래서 6주 정도 지연될 것 같아요.\nW: 마지막 단계까지 밀리지만 않는다면 괜찮아요. 그쪽 팀이 이미 그 날짜에 맞춰 채용을 진행하고 있거든요.\nM: 그럴 일은 없을 거예요. 별도 팀이 맡고 있어요.","part":3},{"id":"p3-059","level":5,"topic":"해외 박람회 부스 배정 취소와 예산 재배정","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"I just heard back from the Frankfurt trade fair organizers. The booth we reserved has been given to another company because we missed the deposit deadline."},{"s":"W","t":"What? I thought the finance team paid that in January."},{"s":"M","t":"Apparently, the invoice was sent to an old e-mail address. The only spaces left are in the back hall, near the food court."},{"s":"W","t":"Well, that's not ideal, but those areas do get a lot of foot traffic around lunchtime."},{"s":"M","t":"That's true. And they're thirty percent cheaper. We could use the savings to host a customer reception at a nearby hotel."},{"s":"W","t":"That's not a bad idea. Last year, most of our actual deals came from meetings outside the fair, anyway."},{"s":"M","t":"Then I'll book the back-hall booth and get quotes from a few hotels."},{"s":"W","t":"And please make sure finance updates the organizer's contact information so this doesn't happen again."}],"graphic":null,"questions":[{"q":"What problem does the man report?","choices":["A reserved space was lost.","A trade fair was canceled.","An invoice contained an error.","A hotel is fully booked."],"answer":0,"type":"주제·목적","explanation":"남자가 \"The booth we reserved has been given to another company because we missed the deposit deadline.\"이라고 했으므로 예약한 부스를 잃었다. 청구서는 옛 이메일로 간 것이지 내용에 오류가 있던 것은 아니다."},{"q":"What does the woman imply when she says, \"those areas do get a lot of foot traffic around lunchtime\"?","choices":["The booth should offer food samples.","The fair will be too crowded.","The new location may still be acceptable.","Staff should take lunch breaks in shifts."],"answer":2,"type":"의도 파악","explanation":"뒤쪽 홀밖에 남지 않았다는 말에 \"that's not ideal, but\"으로 시작해 점심시간에 사람이 많이 지나간다고 했다. 이상적이지는 않아도 그 자리도 괜찮을 수 있다는 뜻이다."},{"q":"What does the woman ask the man to make sure of?","choices":["That contact details are corrected","That a deposit is refunded","That the booth is near an entrance","That a hotel reception is canceled"],"answer":0,"type":"요청·제안","explanation":"여자가 \"make sure finance updates the organizer's contact information\"이라고 했으므로 연락처 정보가 바로잡히도록 챙겨 달라는 요청이다. 호텔 리셉션은 오히려 새로 열기로 한 행사다."}],"translation":"M: 방금 프랑크푸르트 무역 박람회 주최 측에서 답을 받았어요. 보증금 기한을 놓쳐서 우리가 예약한 부스가 다른 회사에 넘어갔대요.\nW: 뭐라고요? 재무팀이 1월에 낸 줄 알았는데요.\nM: 청구서가 옛 이메일 주소로 갔나 봐요. 남은 자리는 푸드코트 근처 뒤쪽 홀뿐이에요.\nW: 음, 이상적이진 않지만 그쪽은 점심시간 무렵에 지나다니는 사람이 정말 많긴 해요.\nM: 맞아요. 게다가 30퍼센트 더 싸요. 아낀 돈으로 근처 호텔에서 고객 리셉션을 열 수도 있어요.\nW: 나쁘지 않은 생각이네요. 작년에도 실제 계약은 대부분 박람회장 밖에서의 미팅에서 나왔으니까요.\nM: 그럼 뒤쪽 홀 부스를 예약하고 호텔 몇 곳에서 견적을 받을게요.\nW: 그리고 이런 일이 다시 없도록 재무팀이 주최 측 연락처 정보를 꼭 갱신하게 해 주세요.","part":3},{"id":"p3-060","level":5,"topic":"드라마 촬영 장소 섭외","speakers":{"W":"female","M":"male"},"script":[{"s":"W","t":"Thanks for meeting with me. As I mentioned on the phone, we'd like to film a few scenes in your lobby for a television series."},{"s":"M","t":"Yes. I talked to the property owners, and they're open to it, as long as it doesn't disrupt our tenants."},{"s":"W","t":"Understood. We'd film on two weekends in October, from six a.m. to eight p.m."},{"s":"M","t":"Weekends should be OK. But the building's heating system is being replaced in October, and there'll be contractors working in the lobby."},{"s":"W","t":"Hmm. Our director is set on this location. The marble staircase is exactly what she pictured."},{"s":"M","t":"Well, the contractors don't work on Sundays, so if you could fit everything into two Sundays..."},{"s":"W","t":"That would mean longer days, but I think we can manage. I'll need to check with our crew's union about overtime rules first, though."},{"s":"M","t":"Take your time. Once you confirm, I'll draft a location agreement."}],"graphic":null,"questions":[{"q":"What does the woman want to do?","choices":["Rent office space for her production company","Use a building as a filming location","Hire some building contractors","Renovate a lobby"],"answer":1,"type":"주제·목적","explanation":"여자가 \"we'd like to film a few scenes in your lobby for a television series\"라고 했으므로 건물을 촬영 장소로 쓰려는 것이다. 공사 업체는 건물 난방 교체 때문에 로비에 있는 사람들이다."},{"q":"Why does the woman say, \"Our director is set on this location\"?","choices":["To request another meeting with the property owners and the tenants","To complain about the director's choice","To suggest that the director visit the site","To explain why she does not want to give up on the building"],"answer":3,"type":"의도 파악","explanation":"10월에 로비에서 공사가 있다는 문제를 듣고 한 말로, 감독이 이 장소를 강하게 원하니 다른 곳을 찾기보다 방법을 찾고 싶다는 뜻이다. 이어서 남자가 일요일 촬영이라는 해결책을 제시한다."},{"q":"What does the woman say she needs to do first?","choices":["Sign a location agreement","Meet with the contractors","Check labor rules for longer workdays","Visit the building on a Sunday to take measurements"],"answer":2,"type":"다음 할 일","explanation":"여자가 \"I'll need to check with our crew's union about overtime rules first\"라고 했으므로 먼저 연장 근무 규정을 확인해야 한다. 계약서는 확정 후 남자가 작성한다."}],"translation":"W: 만나 주셔서 감사해요. 전화로 말씀드렸듯이 TV 드라마 몇 장면을 이 건물 로비에서 촬영하고 싶어요.\nM: 네. 건물주들과 이야기했는데, 입주자들에게 방해가 되지 않는다면 괜찮다고 해요.\nW: 알겠습니다. 10월 중 두 번의 주말에 오전 6시부터 오후 8시까지 촬영하려고 해요.\nM: 주말은 괜찮을 거예요. 그런데 10월에 건물 난방 시스템을 교체해서 로비에서 공사 인력이 작업할 거예요.\nW: 음. 저희 감독님이 이 장소를 꼭 쓰고 싶어 하세요. 대리석 계단이 감독님이 그리던 모습 그대로거든요.\nM: 음, 공사 인력이 일요일에는 일하지 않으니까 일요일 두 번 안에 다 찍을 수 있다면…\nW: 그러면 하루 촬영이 길어지겠지만 해낼 수 있을 것 같아요. 다만 먼저 스태프 노조에 초과 근무 규정을 확인해야 해요.\nM: 천천히 하세요. 확정되면 촬영 장소 계약서 초안을 작성할게요.","part":3},{"id":"p3-061","level":1,"topic":"공항 수하물 분실 신고","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hello. My suitcase didn't come out at baggage claim. I was on the flight from Singapore."},{"s":"M","t":"I'm sorry about that. Can I see your boarding pass and baggage tag?"},{"s":"W","t":"Here they are. It's a large blue suitcase with a black handle."},{"s":"M","t":"Thank you. It looks like your bag is still in Singapore. It will arrive on the next flight tonight."},{"s":"W","t":"Oh, good. But I'm staying at a hotel downtown."},{"s":"M","t":"No problem. We'll deliver it to your hotel tomorrow morning. Please write the hotel address on this form."}],"graphic":null,"questions":[{"q":"Where most likely are the speakers?","choices":["At a luggage store","At an airport","At a hotel","At a travel agency"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"여자가 \"My suitcase didn't come out at baggage claim\"이라고 하고 탑승권과 수하물표를 보여 주므로 공항 수하물 찾는 곳이다. 호텔은 여자가 묵을 곳일 뿐 대화 장소가 아니다."},{"q":"What does the man say about the woman's bag?","choices":["It will arrive later today.","It was damaged during the flight.","It is too heavy to carry.","It was sent to the wrong city."],"answer":0,"type":"세부 사항","explanation":"남자가 \"It will arrive on the next flight tonight\"라고 했으므로 오늘 밤 다음 비행기로 도착한다. 가방은 아직 싱가포르에 있을 뿐 다른 도시로 잘못 간 것이 아니다."},{"q":"What does the man ask the woman to do?","choices":["Write down an address","Come back tomorrow","Pay a delivery fee","Call the hotel"],"answer":0,"type":"요청·제안","explanation":"남자가 \"Please write the hotel address on this form\"이라고 했으므로 양식에 호텔 주소를 적어 달라는 요청이다. 다시 오라는 말은 없고 가방은 다음 날 아침 호텔로 배달된다."}],"translation":"W: 안녕하세요. 수하물 찾는 곳에서 제 여행 가방이 안 나왔어요. 싱가포르에서 오는 비행기를 탔어요.\nM: 죄송합니다. 탑승권과 수하물표를 보여 주시겠어요?\nW: 여기 있어요. 검은 손잡이가 달린 큰 파란색 가방이에요.\nM: 감사합니다. 가방이 아직 싱가포르에 있는 것 같네요. 오늘 밤 다음 비행기로 도착할 거예요.\nW: 아, 다행이네요. 그런데 저는 시내 호텔에 묵어요.\nM: 괜찮습니다. 내일 아침에 호텔로 배달해 드릴게요. 이 양식에 호텔 주소를 적어 주세요.","part":3},{"id":"p3-062","level":1,"topic":"옷 수선 맡기기","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi. I bought these pants last week, but they're too long. Can you make them shorter?"},{"s":"W","t":"Sure. Please put them on, and I'll check the length."},{"s":"M","t":"OK. How about now?"},{"s":"W","t":"I think about three centimeters shorter will look good. Is that OK?"},{"s":"M","t":"Yes, that's fine. When will they be ready?"},{"s":"W","t":"On Thursday afternoon. You can pay when you pick them up."}],"graphic":{"title":"Nina's Tailor Shop — Price List","rows":[["Service","Price"],["Shorten pants","$12"],["Shorten sleeves","$15"],["Replace zipper","$18"],["Take in waist","$20"]]},"questions":[{"q":"Why is the man visiting the shop?","choices":["His jacket is too small.","He lost a button.","He wants to buy new pants.","His pants are too long."],"answer":3,"type":"주제·목적","explanation":"남자가 \"they're too long. Can you make them shorter?\"라고 했으므로 바지가 길어서 수선하러 왔다. 새 바지는 지난주에 이미 샀다."},{"q":"Look at the graphic. How much will the man pay?","choices":["$12","$15","$18","$20"],"answer":0,"type":"시각 자료 연계","explanation":"남자는 바지 길이를 줄이려 하므로 표의 Shorten pants 항목, 12달러를 낸다. 소매 줄임(15달러)이나 허리 줄임(20달러)은 요청하지 않았다."},{"q":"When will the man pick up his item?","choices":["On Thursday","On Tuesday","Today","Next week"],"answer":0,"type":"세부 사항","explanation":"여자가 \"On Thursday afternoon\"이라고 했으므로 목요일에 찾아간다. next week는 바지를 산 시점(last week)과 헷갈리게 만든 오답이다."}],"translation":"M: 안녕하세요. 지난주에 이 바지를 샀는데 너무 길어요. 줄여 주실 수 있나요?\nW: 그럼요. 입어 보세요, 길이를 확인할게요.\nM: 네. 지금은 어때요?\nW: 3센티미터 정도 줄이면 보기 좋을 것 같아요. 괜찮으세요?\nM: 네, 좋아요. 언제 다 되나요?\nW: 목요일 오후에요. 돈은 찾아가실 때 내시면 돼요.","part":3},{"id":"p3-063","level":1,"topic":"보드게임 카페 이용","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"Welcome to Game Corner Café. How many people?"},{"s":"M","t":"Just two of us. How much does it cost to play?"},{"s":"W","t":"It's five dollars per person for two hours. Drinks are extra."},{"s":"M2","t":"Do you have any games for beginners? We've never played board games before."},{"s":"W","t":"Yes, we have a shelf of easy games by the window. I can explain the rules if you'd like."},{"s":"M2","t":"That would be great, thanks."},{"s":"M","t":"And can we order two iced teas, please?"},{"s":"W","t":"Of course. Please have a seat at table four, and I'll bring them over."}],"graphic":null,"questions":[{"q":"Where most likely does the woman work?","choices":["At a school","At a toy store","At a bookstore","At a café"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"여자가 \"Welcome to Game Corner Café\"라고 인사하고 이용 요금과 음료를 안내하므로 보드게임 카페 직원이다. 게임을 파는 장난감 가게가 아니라 시간당 요금을 받는 카페다."},{"q":"What do the men say about themselves?","choices":["They are new to board games.","They want to buy a game.","They are regular customers.","They are waiting for a friend."],"answer":0,"type":"세부 사항","explanation":"두 번째 남자가 \"We've never played board games before\"라고 했으므로 보드게임이 처음이다. 두 명뿐이라고 했으니 친구를 기다린다는 말은 없다."},{"q":"What does the woman offer to do?","choices":["Bring some snacks","Explain some game rules","Give a discount","Save a table by the window"],"answer":1,"type":"요청·제안","explanation":"여자가 \"I can explain the rules if you'd like\"라고 했으므로 게임 규칙 설명을 제안했다. 창가(window)는 쉬운 게임이 있는 선반 위치일 뿐 자리를 맡아 주겠다는 것이 아니다."}],"translation":"W: 게임 코너 카페에 오신 것을 환영합니다. 몇 분이세요?\nM: 저희 둘뿐이에요. 게임하는 데 얼마예요?\nW: 1인당 2시간에 5달러예요. 음료는 따로 받아요.\nM2: 초보자용 게임도 있나요? 저희는 보드게임을 한 번도 해 본 적이 없어요.\nW: 네, 창가 선반에 쉬운 게임들이 있어요. 원하시면 규칙을 설명해 드릴게요.\nM2: 그러면 좋죠, 고마워요.\nM: 그리고 아이스티 두 잔 주문할 수 있을까요?\nW: 물론이죠. 4번 테이블에 앉으세요, 가져다 드릴게요.","part":3},{"id":"p3-064","level":1,"topic":"스포츠 센터 테니스 코트 예약","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, I'd like to book a tennis court for Saturday."},{"s":"M","t":"Sure. What time would you like?"},{"s":"W","t":"In the morning, please. My friend and I want to play before lunch."},{"s":"M","t":"Let me see. The courts are full until eleven, but Court 3 is free from eleven to twelve."},{"s":"W","t":"That's perfect. We'll take it."},{"s":"M","t":"Great. Can I have your membership number?"},{"s":"W","t":"Oh, I'm not a member. Is that a problem?"},{"s":"M","t":"Not at all. Non-members just pay a little more. You can pay at the front desk on Saturday."}],"graphic":{"title":"Riverside Sports Center — Saturday Courts","rows":[["Time","Court"],["9:00 – 10:00","Court 1"],["10:00 – 11:00","Court 2"],["11:00 – 12:00","Court 3"],["1:00 – 2:00","Court 4"]]},"questions":[{"q":"What does the woman want to do?","choices":["Reserve a tennis court","Join a tennis class","Watch a tennis match","Buy a tennis racket"],"answer":0,"type":"주제·목적","explanation":"여자가 \"I'd like to book a tennis court for Saturday\"라고 했으므로 테니스 코트를 예약하려 한다. book을 reserve로 바꿔 표현했다."},{"q":"Look at the graphic. What time will the woman play tennis?","choices":["9:00 – 10:00","10:00 – 11:00","11:00 – 12:00","1:00 – 2:00"],"answer":2,"type":"시각 자료 연계","explanation":"남자가 \"Court 3 is free from eleven to twelve\"라고 하자 여자가 그것으로 하겠다고 했다. 표에서 Court 3은 11시~12시다. 오후 1시는 점심 전에 치고 싶다는 여자의 말과 맞지 않는다."},{"q":"What does the man say about non-members?","choices":["They must pay online.","They pay a higher price.","They cannot play on Saturday.","They need to fill out a form."],"answer":1,"type":"세부 사항","explanation":"남자가 \"Non-members just pay a little more\"라고 했으므로 비회원은 요금이 조금 더 비싸다. 결제는 토요일에 안내 데스크에서 하므로 온라인 결제는 오답이다."}],"translation":"W: 안녕하세요, 토요일에 테니스 코트를 예약하고 싶어요.\nM: 네. 몇 시로 하시겠어요?\nW: 오전으로요. 친구랑 점심 전에 치고 싶어요.\nM: 볼게요. 11시까지는 코트가 다 찼는데, 3번 코트가 11시부터 12시까지 비어 있어요.\nW: 딱 좋네요. 그걸로 할게요.\nM: 좋습니다. 회원 번호를 알려 주시겠어요?\nW: 아, 저는 회원이 아니에요. 문제가 되나요?\nM: 전혀요. 비회원은 요금을 조금 더 내시기만 하면 돼요. 토요일에 안내 데스크에서 결제하시면 됩니다.","part":3},{"id":"p3-065","level":1,"topic":"택배 방문 수거 요청","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hello, this is Fast Line Couriers. How can I help you?"},{"s":"W","t":"Hi. I need to send a box to our office in Chicago. Can someone pick it up today?"},{"s":"M","t":"Yes. Our driver can come between two and four this afternoon. What's your address?"},{"s":"W","t":"It's 45 Maple Street, the Brighton Building. We're on the fifth floor."},{"s":"M","t":"Got it. How big is the box?"},{"s":"W","t":"It's small. It has some sample products in it."},{"s":"M","t":"OK. Please print the shipping label from our Web site and put it on the box before the driver arrives."}],"graphic":null,"questions":[{"q":"Why is the woman calling?","choices":["To report a lost package","To arrange a package pickup","To change a delivery address","To order sample products"],"answer":1,"type":"주제·목적","explanation":"여자가 \"Can someone pick it up today?\"라고 했으므로 택배 수거를 요청하려고 전화했다. 샘플 제품은 상자 안에 든 물건일 뿐 주문하려는 것이 아니다."},{"q":"When will the driver arrive?","choices":["This morning","This evening","Tomorrow morning","This afternoon"],"answer":3,"type":"세부 사항","explanation":"남자가 \"Our driver can come between two and four this afternoon\"이라고 했으므로 오늘 오후에 온다."},{"q":"What does the man ask the woman to do?","choices":["Bring a box to the lobby","Attach a label to a box","Call back later","Pay the driver in cash"],"answer":1,"type":"요청·제안","explanation":"남자가 \"Please print the shipping label ... and put it on the box\"라고 했으므로 상자에 배송 라벨을 붙이라는 요청이다. put it on을 attach로 바꿔 표현했다."}],"translation":"M: 안녕하세요, 패스트 라인 택배입니다. 무엇을 도와드릴까요?\nW: 안녕하세요. 시카고 사무실로 상자 하나를 보내야 해요. 오늘 누가 가지러 올 수 있나요?\nM: 네. 오늘 오후 2시에서 4시 사이에 기사님이 갈 수 있어요. 주소가 어떻게 되세요?\nW: 메이플 가 45번지, 브라이턴 빌딩이에요. 저희는 5층에 있어요.\nM: 알겠습니다. 상자는 얼마나 큰가요?\nW: 작아요. 샘플 제품이 들어 있어요.\nM: 네. 기사님이 도착하기 전에 저희 웹사이트에서 배송 라벨을 출력해서 상자에 붙여 주세요.","part":3},{"id":"p3-066","level":1,"topic":"도서관 회원증 발급","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Excuse me. I just moved to this town. How can I get a library card?"},{"s":"M","t":"It's easy. I just need to see a photo ID and something with your new address on it."},{"s":"W","t":"I have my driver's license and a phone bill. Is that enough?"},{"s":"M","t":"Yes, that's fine. Please fill out this short form."},{"s":"W","t":"OK. How many books can I borrow at one time?"},{"s":"M","t":"Up to ten books, for three weeks. Here's your card. You can also use it to borrow movies."}],"graphic":null,"questions":[{"q":"Who most likely is the man?","choices":["A bookstore owner","A librarian","A real estate agent","A bank teller"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"여자가 도서관 회원증(library card) 발급을 묻고 남자가 대출 권수와 기간을 안내하므로 남자는 도서관 직원이다."},{"q":"What does the woman say she recently did?","choices":["She paid a phone bill.","She started a new job.","She lost her library card.","She moved to a new town."],"answer":3,"type":"세부 사항","explanation":"여자가 \"I just moved to this town\"이라고 했으므로 최근에 이사를 왔다. 전화 요금 고지서는 주소 확인용으로 가져온 서류다."},{"q":"How long can the woman keep the books?","choices":["Two weeks","Ten days","One week","Three weeks"],"answer":3,"type":"세부 사항","explanation":"남자가 \"Up to ten books, for three weeks\"라고 했으므로 3주 동안 빌릴 수 있다. ten은 빌릴 수 있는 책 권수다."}],"translation":"W: 실례합니다. 이 동네로 막 이사 왔는데요. 도서관 회원증은 어떻게 만들 수 있나요?\nM: 간단해요. 사진이 있는 신분증과 새 주소가 적힌 서류만 보여 주시면 돼요.\nW: 운전면허증이랑 전화 요금 고지서가 있어요. 그거면 될까요?\nM: 네, 됩니다. 이 짧은 양식을 작성해 주세요.\nW: 네. 한 번에 몇 권까지 빌릴 수 있나요?\nM: 최대 10권을 3주 동안 빌릴 수 있어요. 여기 회원증이요. 영화를 빌릴 때도 쓰실 수 있어요.","part":3},{"id":"p3-067","level":1,"topic":"꽃집에서 개업 축하 꽃 주문","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi. I'd like to send some flowers to a friend. She's opening a new restaurant on Monday."},{"s":"W","t":"How nice. We have some beautiful plants that are popular for new businesses."},{"s":"M","t":"Hmm, I think she'd like flowers more. Maybe something yellow?"},{"s":"W","t":"How about these sunflowers? They're very fresh."},{"s":"M","t":"They're great. Can you deliver them on Monday morning?"},{"s":"W","t":"Yes. Would you like to add a card? You can write a message here."}],"graphic":null,"questions":[{"q":"Why is the man sending flowers?","choices":["A friend is moving to a new house.","A friend is opening a business.","A friend is having a birthday.","A friend got a new job."],"answer":1,"type":"주제·목적","explanation":"남자가 \"She's opening a new restaurant on Monday\"라고 했으므로 친구의 식당 개업을 축하하려는 것이다. 새 식당을 business로 바꿔 표현했다."},{"q":"What kind of flowers does the man choose?","choices":["Lilies","Tulips","Sunflowers","Roses"],"answer":2,"type":"세부 사항","explanation":"여자가 \"How about these sunflowers?\"라고 하자 남자가 \"They're great\"라고 했으므로 해바라기를 골랐다."},{"q":"What does the woman suggest?","choices":["Picking up the flowers","Paying for delivery later","Adding a message card","Buying a vase"],"answer":2,"type":"요청·제안","explanation":"여자가 마지막에 \"Would you like to add a card?\"라고 했으므로 메시지 카드를 추가하라고 제안했다. 꽃병은 대화에 나오지 않는다."}],"translation":"M: 안녕하세요. 친구에게 꽃을 보내고 싶어요. 친구가 월요일에 새 식당을 열거든요.\nW: 좋네요. 개업 선물로 인기 있는 예쁜 화분들이 있어요.\nM: 음, 친구는 꽃을 더 좋아할 것 같아요. 노란색 꽃이면 좋겠어요.\nW: 이 해바라기는 어떠세요? 아주 싱싱해요.\nM: 좋네요. 월요일 아침에 배달해 주실 수 있나요?\nW: 네. 카드도 함께 넣으시겠어요? 여기에 메시지를 쓰시면 돼요.","part":3},{"id":"p3-068","level":1,"topic":"세차장 서비스 선택","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi. I'd like to get my car washed. What services do you have?"},{"s":"M","t":"We have a basic wash for ten dollars. It cleans the outside of the car."},{"s":"W","t":"What about the inside? There's a lot of sand in it from the beach."},{"s":"M","t":"Then you need the full service. It's twenty dollars, and we vacuum the inside too."},{"s":"W","t":"OK, I'll get that one. How long will it take?"},{"s":"M","t":"About thirty minutes. You can wait in our lounge. There's free coffee."}],"graphic":null,"questions":[{"q":"What problem does the woman mention?","choices":["Her car has sand inside.","Her car will not start.","Her car needs new tires.","Her car window is broken."],"answer":0,"type":"세부 사항","explanation":"여자가 \"There's a lot of sand in it from the beach\"라고 했으므로 차 안에 모래가 많다."},{"q":"How much will the woman most likely pay?","choices":["$15","$10","$20","$30"],"answer":2,"type":"세부 사항","explanation":"남자가 실내 청소까지 하는 full service는 \"twenty dollars\"라고 했고 여자가 그것으로 하겠다고 했으므로 20달러다. 10달러는 외부만 닦는 기본 세차다."},{"q":"What does the man suggest the woman do?","choices":["Pay in advance","Come back tomorrow","Leave her car keys","Wait in a lounge"],"answer":3,"type":"요청·제안","explanation":"남자가 \"You can wait in our lounge\"라고 했으므로 휴게실에서 기다리라고 권했다. 30분이면 끝나므로 내일 다시 오라는 말은 없다."}],"translation":"W: 안녕하세요. 세차를 하고 싶은데요. 어떤 서비스가 있나요?\nM: 10달러짜리 기본 세차가 있어요. 차 바깥을 닦아 드려요.\nW: 안쪽은요? 바닷가에 다녀와서 모래가 많아요.\nM: 그럼 풀서비스가 필요하시겠네요. 20달러이고, 실내도 진공청소기로 청소해 드려요.\nW: 좋아요, 그걸로 할게요. 얼마나 걸리나요?\nM: 30분 정도요. 저희 휴게실에서 기다리시면 돼요. 커피는 무료예요.","part":3},{"id":"p3-069","level":2,"topic":"어학원 스페인어 수업 등록","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, I'm calling about your Spanish classes. My company is sending me to Madrid in the spring, so I need to learn some basics."},{"s":"W","t":"Great. Have you studied Spanish before?"},{"s":"M","t":"No, never. I'm a complete beginner."},{"s":"W","t":"Then you should take Level 1. We have two sections."},{"s":"M","t":"I work until six on weekdays, so the evening one would be better for me."},{"s":"W","t":"OK. There are still a few seats left. You can register on our Web site, or I can sign you up over the phone."},{"s":"M","t":"Over the phone is fine. Do I need to buy a textbook?"},{"s":"W","t":"Yes, but you can get it at our front desk on the first day of class."}],"graphic":{"title":"City Language Institute — Spanish Classes","rows":[["Class","Days","Time"],["Level 1 (A)","Mon / Wed","10:00 A.M."],["Level 1 (B)","Tue / Thu","7:00 P.M."],["Level 2","Mon / Wed","7:00 P.M."],["Conversation","Saturday","9:00 A.M."]]},"questions":[{"q":"Why does the man want to learn Spanish?","choices":["He needs it for a job interview.","He wants to read Spanish books.","He is moving to Madrid permanently.","He is going on a business trip."],"answer":3,"type":"주제·목적","explanation":"남자가 \"My company is sending me to Madrid in the spring\"라고 했으므로 회사 일로 마드리드에 가게 되어 배운다. 영구 이주한다는 말은 없다."},{"q":"Look at the graphic. Which class will the man most likely take?","choices":["Level 1 (A)","Level 1 (B)","Level 2","Conversation"],"answer":1,"type":"시각 자료 연계","explanation":"남자는 완전 초보라 Level 1을 들어야 하고, 평일 6시까지 일해서 저녁 수업이 낫다고 했다. 표에서 저녁에 하는 Level 1은 화·목 오후 7시의 Level 1 (B)다. Level 1 (A)는 오전 수업이고, 월·수 저녁 수업은 Level 2다."},{"q":"Where can the man get a textbook?","choices":["At a nearby bookstore","On the institute's Web site","At the institute's front desk","From his company"],"answer":2,"type":"세부 사항","explanation":"여자가 \"you can get it at our front desk on the first day of class\"라고 했으므로 어학원 안내 데스크에서 산다. 웹사이트는 등록 방법으로 언급됐다."}],"translation":"M: 안녕하세요, 스페인어 수업 때문에 전화드렸어요. 회사에서 봄에 저를 마드리드로 보내서 기초를 좀 배워야 해요.\nW: 좋습니다. 스페인어를 공부해 보신 적 있나요?\nM: 아니요, 전혀요. 완전 초보예요.\nW: 그럼 1단계를 들으셔야 해요. 반이 두 개 있어요.\nM: 평일에는 6시까지 일해서 저녁반이 저한테 더 나아요.\nW: 네. 아직 자리가 몇 개 남아 있어요. 저희 웹사이트에서 등록하셔도 되고, 제가 전화로 등록해 드릴 수도 있어요.\nM: 전화로 해 주세요. 교재를 사야 하나요?\nW: 네, 하지만 첫 수업 날 저희 안내 데스크에서 사시면 돼요.","part":3},{"id":"p3-070","level":2,"topic":"자동차 대리점 정기 점검","speakers":{"M":"male","W":"female","M2":"male"},"script":[{"s":"M","t":"Good morning. I have an appointment at nine for an oil change and a regular checkup."},{"s":"W","t":"Yes, Mr. Harris. Let me get one of our mechanics. Kevin, this is Mr. Harris's car."},{"s":"M2","t":"Hi. I'll take a look. Is there anything else you've noticed with the car?"},{"s":"M","t":"Actually, yes. The brakes make a strange noise when I stop."},{"s":"M2","t":"OK, I'll check them too. That might take an extra hour."},{"s":"M","t":"Hmm. I have to be at work by ten."},{"s":"W","t":"We can give you a ride to your office. Our shuttle leaves every half hour."},{"s":"M","t":"That would be very helpful. Thank you."}],"graphic":null,"questions":[{"q":"Where are the speakers?","choices":["At a car dealership service center","At a gas station","At a car rental office","At a parking garage"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"여자가 정비사(mechanic)를 부르고 남자가 오일 교환과 정기 점검 예약을 했다고 하므로 자동차 정비 서비스 센터다."},{"q":"What problem does Mr. Harris mention?","choices":["His brakes make a noise.","His headlight is broken.","His tires are flat.","His engine will not start."],"answer":0,"type":"세부 사항","explanation":"해리스 씨가 \"The brakes make a strange noise when I stop\"이라고 했으므로 브레이크 소음이 문제다."},{"q":"What does the woman offer?","choices":["A free car wash","A rental car for the day","A discount on the repair","A ride to his workplace"],"answer":3,"type":"요청·제안","explanation":"10시까지 출근해야 한다는 말에 여자가 \"We can give you a ride to your office\"라고 했으므로 사무실까지 태워 주겠다고 제안했다. 대여 차량 제공은 언급되지 않았다."}],"translation":"M: 안녕하세요. 9시에 오일 교환과 정기 점검 예약을 했어요.\nW: 네, 해리스 씨. 정비사를 불러 드릴게요. 케빈, 해리스 씨 차예요.\nM2: 안녕하세요. 제가 살펴볼게요. 차에서 다른 이상한 점을 느끼신 게 있나요?\nM: 사실 있어요. 멈출 때 브레이크에서 이상한 소리가 나요.\nM2: 네, 그것도 점검할게요. 한 시간 정도 더 걸릴 수 있어요.\nM: 음. 10시까지 회사에 가야 하는데요.\nW: 사무실까지 태워 드릴 수 있어요. 저희 셔틀이 30분마다 출발해요.\nM: 그러면 정말 도움이 되겠네요. 감사합니다.","part":3},{"id":"p3-071","level":2,"topic":"지역 신문 광고 게재","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hello, Daily Herald advertising department. This is Lisa."},{"s":"M","t":"Hi, Lisa. I own a bakery on Pine Street, and I'd like to put an ad in your paper for our grand opening."},{"s":"W","t":"Wonderful. How big would you like the ad to be?"},{"s":"M","t":"I don't want to spend more than a hundred dollars, but I'd like it to be as big as possible."},{"s":"W","t":"I understand. Then this size would be the best choice for you."},{"s":"M","t":"Good. Can it run in this Saturday's paper?"},{"s":"W","t":"Yes, but we need the design by Wednesday. Could you e-mail me your logo and a photo of your shop?"}],"graphic":{"title":"Daily Herald — Ad Rates (one day)","rows":[["Ad Size","Price"],["Business card","$45"],["Quarter page","$95"],["Half page","$160"],["Full page","$280"]]},"questions":[{"q":"What kind of business does the man own?","choices":["A printing company","A bakery","A flower shop","A café"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"남자가 \"I own a bakery on Pine Street\"라고 했으므로 제과점 주인이다."},{"q":"Look at the graphic. Which ad size will the man most likely choose?","choices":["Business card","Quarter page","Half page","Full page"],"answer":1,"type":"시각 자료 연계","explanation":"남자는 100달러 넘게 쓰고 싶지 않지만 되도록 크게 하고 싶다고 했다. 표에서 100달러 이하 중 가장 큰 것은 95달러인 Quarter page다. Half page는 160달러로 예산을 넘는다."},{"q":"What does the woman ask the man to send?","choices":["A logo and a photo","A payment receipt","A list of prices","A signed contract"],"answer":0,"type":"요청·제안","explanation":"여자가 \"Could you e-mail me your logo and a photo of your shop?\"이라고 했으므로 로고와 가게 사진을 보내 달라고 했다."}],"translation":"W: 안녕하세요, 데일리 헤럴드 광고부 리사입니다.\nM: 안녕하세요, 리사. 파인 가에서 제과점을 하는데요, 개업 행사 광고를 신문에 내고 싶어요.\nW: 좋습니다. 광고 크기는 어느 정도로 하시겠어요?\nM: 100달러 넘게 쓰고 싶지는 않은데, 되도록 크게 하고 싶어요.\nW: 알겠습니다. 그럼 이 크기가 가장 좋겠네요.\nM: 좋아요. 이번 토요일 신문에 실릴 수 있나요?\nW: 네, 하지만 디자인은 수요일까지 필요해요. 로고와 가게 사진을 이메일로 보내 주시겠어요?","part":3},{"id":"p3-072","level":2,"topic":"사과 과수원 체험 투어 예약","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, I'm calling from Greenfield Elementary School. We'd like to bring our second-grade class to your orchard for an apple-picking tour."},{"s":"W","t":"We'd love to have you. How many students are there?"},{"s":"M","t":"Thirty students and four teachers. Is the first Friday in October available?"},{"s":"W","t":"Let me check. Yes, that day is open. The tour takes about two hours, and each child can take home a small bag of apples."},{"s":"M","t":"The kids will love that. Is there a place for them to eat lunch?"},{"s":"W","t":"Yes, we have picnic tables next to the barn. But if it rains, we'll have to move the date."},{"s":"M","t":"I see. Then I'll send you a list of the students' names this week."}],"graphic":null,"questions":[{"q":"Who most likely is the man?","choices":["A farm worker","A bus driver","A tour guide","A school teacher"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"남자가 초등학교에서 전화했다며 \"We'd like to bring our second-grade class\"라고 했으므로 학교 교사다. 여자가 과수원 측 사람이다."},{"q":"What will each student receive?","choices":["A picnic lunch","A photo of the class","A free T-shirt","A bag of apples"],"answer":3,"type":"세부 사항","explanation":"여자가 \"each child can take home a small bag of apples\"라고 했으므로 사과 한 봉지를 받는다. 점심은 먹을 장소(picnic tables)만 제공된다."},{"q":"What does the woman say could happen?","choices":["The tour could be shortened.","The orchard could be closed for repairs.","The date could be changed because of weather.","The price could go up."],"answer":2,"type":"세부 사항","explanation":"여자가 \"if it rains, we'll have to move the date\"라고 했으므로 비가 오면 날짜가 바뀔 수 있다. rains를 weather로, move the date를 date could be changed로 바꿔 표현했다."}],"translation":"M: 안녕하세요, 그린필드 초등학교에서 전화드렸어요. 2학년 반 학생들을 데리고 과수원에 사과 따기 체험을 가고 싶어요.\nW: 대환영이에요. 학생이 몇 명인가요?\nM: 학생 30명과 교사 4명이에요. 10월 첫째 주 금요일 가능할까요?\nW: 확인해 볼게요. 네, 그날 비어 있어요. 투어는 2시간 정도 걸리고, 아이들마다 사과 한 봉지씩 가져갈 수 있어요.\nM: 아이들이 정말 좋아하겠네요. 점심 먹을 곳이 있나요?\nW: 네, 헛간 옆에 피크닉 테이블이 있어요. 하지만 비가 오면 날짜를 옮겨야 해요.\nM: 알겠습니다. 그럼 이번 주에 학생 명단을 보내 드릴게요.","part":3},{"id":"p3-073","level":2,"topic":"영화제 자원봉사자 업무 안내","speakers":{"W":"female","M":"male","W2":"female"},"script":[{"s":"W","t":"Hi, everyone. Thanks for volunteering at this year's film festival. I'm Rachel, the volunteer coordinator."},{"s":"M","t":"Hi, Rachel. I'm Daniel. I signed up to work at the ticket booth."},{"s":"W2","t":"And I'm Grace. I'm supposed to help guests find their seats in Theater 2."},{"s":"W","t":"Great. Your festival T-shirts are in this box. Please wear them during your shifts so guests can find you easily."},{"s":"M","t":"What should we do if a guest asks about a movie schedule?"},{"s":"W","t":"Every volunteer gets a printed program. It lists all the showtimes."},{"s":"W2","t":"The first movie starts at ten, right?"},{"s":"W","t":"Yes, and the doors open at nine thirty."},{"s":"M","t":"Then we'd better get to our places."}],"graphic":null,"questions":[{"q":"Where is the conversation most likely taking place?","choices":["At a sports stadium","At a museum","At a concert hall","At a film festival"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"여자가 \"Thanks for volunteering at this year's film festival\"이라고 했으므로 영화제 현장이다."},{"q":"What does Rachel ask the volunteers to do?","choices":["Sell programs","Wear festival T-shirts","Arrive by nine o'clock","Check guests' bags"],"answer":1,"type":"요청·제안","explanation":"레이철이 \"Please wear them during your shifts\"라고 했으므로 영화제 티셔츠를 입으라고 요청했다. 프로그램은 자원봉사자에게 나눠 주는 것이지 판매하는 것이 아니다."},{"q":"What does the man imply when he says, \"Then we'd better get to our places\"?","choices":["They are in the wrong theater.","They want to leave early.","They need to find better seats.","They should start working soon."],"answer":3,"type":"의도 파악","explanation":"문을 9시 30분에 연다는 말을 들은 직후에 한 말이므로 곧 업무를 시작해야 하니 각자 자리로 가자는 뜻이다. places는 좌석이 아니라 각자 맡은 근무 위치를 말한다."}],"translation":"W: 안녕하세요, 여러분. 올해 영화제에 자원봉사해 주셔서 감사합니다. 저는 자원봉사 담당자 레이철이에요.\nM: 안녕하세요, 레이철. 저는 대니얼이에요. 매표소 근무를 신청했어요.\nW2: 저는 그레이스예요. 2관에서 관객들이 자리를 찾도록 돕기로 했어요.\nW: 좋아요. 영화제 티셔츠는 이 상자에 있어요. 관객들이 쉽게 찾을 수 있게 근무 시간에 입어 주세요.\nM: 관객이 영화 시간표를 물어보면 어떻게 해야 하나요?\nW: 자원봉사자 모두에게 인쇄된 프로그램을 드려요. 상영 시간이 전부 나와 있어요.\nW2: 첫 영화는 10시에 시작하죠?\nW: 네, 입장은 9시 30분부터예요.\nM: 그럼 각자 자리로 가는 게 좋겠네요.","part":3},{"id":"p3-074","level":2,"topic":"안경점에서 새 안경 맞추기","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi. I'd like to order some new glasses. Here's the prescription from my eye doctor."},{"s":"M","t":"Thank you. Have you chosen a frame yet?"},{"s":"W","t":"I like this black one, but it's a little expensive."},{"s":"M","t":"This brown frame looks almost the same, and it's forty dollars cheaper."},{"s":"W","t":"Oh, you're right. I'll take the brown one, then. How soon can I get them?"},{"s":"M","t":"Usually it takes a week. But we're very busy this month."},{"s":"W","t":"I see. Could you call me when they're ready? I'll leave my number."}],"graphic":null,"questions":[{"q":"What did the woman bring to the store?","choices":["A prescription","A receipt","A discount coupon","A broken pair of glasses"],"answer":0,"type":"세부 사항","explanation":"여자가 \"Here's the prescription from my eye doctor\"라고 했으므로 안과 처방전을 가져왔다."},{"q":"Why does the man recommend the brown frame?","choices":["It is available now.","It costs less.","It is more popular.","It is lighter."],"answer":1,"type":"세부 사항","explanation":"남자가 갈색 테가 거의 똑같아 보이고 \"forty dollars cheaper\"라고 했으므로 가격이 더 싸서 권했다."},{"q":"What does the man mean when he says, \"But we're very busy this month\"?","choices":["The store needs more workers.","The glasses may take longer than usual.","He cannot help the woman right now.","The woman should come back next month."],"answer":1,"type":"의도 파악","explanation":"보통은 일주일이 걸린다고 말한 뒤 이 말을 덧붙였으므로 이번에는 평소보다 더 오래 걸릴 수 있다는 뜻이다. 그래서 여자가 준비되면 전화해 달라고 한다. 다음 달에 다시 오라는 뜻은 아니다."}],"translation":"W: 안녕하세요. 새 안경을 맞추고 싶어요. 안과에서 받은 처방전이에요.\nM: 감사합니다. 안경테는 고르셨나요?\nW: 이 검은색이 마음에 드는데 좀 비싸네요.\nM: 이 갈색 테도 거의 똑같아 보이는데 40달러 더 싸요.\nW: 아, 그렇네요. 그럼 갈색으로 할게요. 얼마나 빨리 받을 수 있나요?\nM: 보통은 일주일 걸려요. 그런데 이번 달은 저희가 정말 바빠서요.\nW: 그렇군요. 준비되면 전화 주시겠어요? 번호를 남겨 둘게요.","part":3},{"id":"p3-075","level":2,"topic":"시청 주민 수영장 여름 프로그램 문의","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hello, Parks and Recreation office. How can I help you?"},{"s":"W","t":"Hi. I saw a flyer about summer swimming lessons at the community pool. Is it too late to sign up my son?"},{"s":"M","t":"Not at all. Registration is open until the end of this week. How old is he?"},{"s":"W","t":"He's eight, and he can swim a little."},{"s":"M","t":"Then he'd be in the intermediate group. Lessons are on Tuesday and Thursday mornings."},{"s":"W","t":"Perfect. How do I register?"},{"s":"M","t":"You'll need to come to this office in person with proof that you live in the city, like a utility bill."}],"graphic":null,"questions":[{"q":"How did the woman learn about the lessons?","choices":["From a newspaper","From a flyer","From a friend","From a Web site"],"answer":1,"type":"세부 사항","explanation":"여자가 \"I saw a flyer about summer swimming lessons\"라고 했으므로 전단지를 보고 알았다."},{"q":"When does registration close?","choices":["Next Tuesday","At the end of the month","Tomorrow","At the end of this week"],"answer":3,"type":"세부 사항","explanation":"남자가 \"Registration is open until the end of this week\"라고 했으므로 이번 주말에 등록이 마감된다."},{"q":"What does the woman need to bring?","choices":["Proof of her address","A registration fee in cash","A swimming certificate","A photo of her son"],"answer":0,"type":"요청·제안","explanation":"남자가 시에 산다는 증명으로 공과금 고지서 같은 것을 가져오라고 했으므로 주소 증빙이 필요하다. proof that you live in the city를 proof of her address로 바꿔 표현했다."}],"translation":"M: 안녕하세요, 공원여가과입니다. 무엇을 도와드릴까요?\nW: 안녕하세요. 주민 수영장 여름 수영 강습 전단지를 봤는데요. 아들을 등록하기엔 너무 늦었나요?\nM: 전혀요. 이번 주말까지 등록을 받아요. 아드님이 몇 살인가요?\nW: 여덟 살이고 수영을 조금 할 줄 알아요.\nM: 그럼 중급반이겠네요. 강습은 화요일과 목요일 오전이에요.\nW: 딱 좋네요. 어떻게 등록하나요?\nM: 공과금 고지서처럼 시에 거주한다는 증명서를 가지고 이 사무실로 직접 오셔야 해요.","part":3},{"id":"p3-076","level":2,"topic":"사진관 여권 사진 촬영","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi. I need passport photos. Can you take them now?"},{"s":"M","t":"Sure. It'll just take a few minutes. Please sit on this chair and look at the camera."},{"s":"W","t":"Should I take off my glasses?"},{"s":"M","t":"Yes, glasses aren't allowed in passport photos anymore."},{"s":"W","t":"OK. How many photos will I get?"},{"s":"M","t":"You'll get four photos. That's twelve dollars. If you want a digital copy too, it's three dollars more."},{"s":"W","t":"Just the printed ones, please. I'm sending in my passport application today."}],"graphic":null,"questions":[{"q":"What does the man tell the woman to do?","choices":["Come back later","Fill out a form","Change her shirt","Remove her glasses"],"answer":3,"type":"요청·제안","explanation":"남자가 여권 사진에는 안경이 허용되지 않는다며 벗으라고 했으므로 안경을 벗으라는 요청이다. take off를 remove로 바꿔 표현했다."},{"q":"How much will the woman most likely pay?","choices":["$15","$3","$12","$4"],"answer":2,"type":"세부 사항","explanation":"사진 4장은 12달러이고 디지털 파일은 3달러 추가인데, 여자가 \"Just the printed ones\"라고 했으므로 12달러를 낸다. 15달러는 디지털 파일까지 포함한 금액이다."},{"q":"What does the woman say she will do today?","choices":["Buy new glasses","Print some documents","Take a flight","Submit a passport application"],"answer":3,"type":"다음 할 일","explanation":"여자가 \"I'm sending in my passport application today\"라고 했으므로 오늘 여권 신청서를 제출한다. sending in을 submit으로 바꿔 표현했다."}],"translation":"W: 안녕하세요. 여권 사진이 필요한데요. 지금 찍을 수 있나요?\nM: 그럼요. 몇 분이면 돼요. 이 의자에 앉아서 카메라를 봐 주세요.\nW: 안경을 벗어야 하나요?\nM: 네, 이제 여권 사진에는 안경이 허용되지 않아요.\nW: 알겠어요. 사진은 몇 장 나오나요?\nM: 네 장이요. 12달러입니다. 디지털 파일도 원하시면 3달러 추가예요.\nW: 인화한 것만 주세요. 오늘 여권 신청서를 낼 거예요.","part":3},{"id":"p3-077","level":3,"topic":"시청 인허가 창구에서 간판 설치 허가 신청","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Good morning. I'm opening a hair salon on Oak Avenue next month, and I was told I need a permit to put up a sign outside."},{"s":"W","t":"That's right. Will the sign hang over the sidewalk, or will it be attached flat against the wall?"},{"s":"M","t":"It'll hang over the sidewalk. The designer said it would be easier for people walking by to see."},{"s":"W","t":"In that case, you'll need a projecting sign permit. It takes longer to process because a city inspector has to approve the location."},{"s":"M","t":"Hmm, the salon opens on the fifteenth. Will I get it in time?"},{"s":"W","t":"If you submit everything today, you should. Just make sure you include a drawing that shows the sign's measurements."},{"s":"M","t":"The designer has that. I'll ask her to e-mail it to me right now."}],"graphic":{"title":"City Permit Office — Sign Permits","rows":[["Permit Type","Fee","Processing Time"],["Wall sign","$50","3 business days"],["Window sign","$25","1 business day"],["Projecting sign","$120","10 business days"],["Temporary banner","$15","Same day"]]},"questions":[{"q":"What is the man preparing to do?","choices":["Design a building","Repair a sidewalk","Apply for a city job","Open a new business"],"answer":3,"type":"주제·목적","explanation":"남자가 \"I'm opening a hair salon on Oak Avenue next month\"라고 했으므로 새 가게를 열 준비를 하고 있다. hair salon을 business로 바꿔 표현했다."},{"q":"Look at the graphic. How long will it most likely take to process the man's permit?","choices":["3 business days","1 business day","10 business days","Same day"],"answer":2,"type":"시각 자료 연계","explanation":"간판이 인도 위로 걸린다고 하자 여자가 projecting sign permit이 필요하다고 했다. 표에서 Projecting sign의 처리 기간은 영업일 10일이다. 3일은 벽에 붙이는 간판(Wall sign)이다."},{"q":"What will the man most likely do next?","choices":["Pay a fee online","Contact his designer","Meet an inspector","Visit the salon location"],"answer":1,"type":"다음 할 일","explanation":"여자가 간판 치수가 나온 도면을 첨부하라고 하자 남자가 \"I'll ask her to e-mail it to me right now\"라고 했다. her는 디자이너이므로 디자이너에게 연락할 것이다."}],"translation":"M: 안녕하세요. 다음 달에 오크 가에 미용실을 여는데, 밖에 간판을 달려면 허가가 필요하다고 들었어요.\nW: 맞아요. 간판이 인도 위로 튀어나오게 걸리나요, 아니면 벽에 평평하게 붙나요?\nM: 인도 위로 걸려요. 디자이너 말로는 지나가는 사람들이 보기 더 쉽대요.\nW: 그렇다면 돌출 간판 허가가 필요해요. 시 조사관이 위치를 승인해야 해서 처리가 더 오래 걸려요.\nM: 음, 미용실이 15일에 문을 여는데요. 그때까지 받을 수 있을까요?\nW: 오늘 서류를 다 내시면 될 거예요. 간판 치수가 나온 도면만 꼭 넣어 주세요.\nM: 디자이너가 갖고 있어요. 지금 바로 이메일로 보내 달라고 할게요.","part":3},{"id":"p3-078","level":3,"topic":"사무실 화분 관리 서비스 계약","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, this is Amanda from Green Office Plant Service. I'm calling to follow up on the quote I sent you last week."},{"s":"M","t":"Oh, thanks for calling. We looked it over, and we're interested in having plants placed in our lobby and meeting rooms."},{"s":"W","t":"Great. Our standard plan includes a weekly visit for watering and trimming. And if any plant dies, we replace it for free."},{"s":"M","t":"That sounds good. One concern, though. Our lobby doesn't get much sunlight."},{"s":"W","t":"That's not a problem. Many of our plants grow well in low light."},{"s":"M","t":"OK. Could someone come by to look at the space before we sign anything?"},{"s":"W","t":"Of course. I'm in your area on Thursday. I can stop by around two, if that works."}],"graphic":null,"questions":[{"q":"Why is the woman calling?","choices":["To follow up on a price estimate","To apologize for a late visit","To ask for payment","To schedule a delivery of furniture"],"answer":0,"type":"주제·목적","explanation":"여자가 \"I'm calling to follow up on the quote I sent you last week\"라고 했으므로 보낸 견적에 대한 후속 연락이다. quote를 price estimate로 바꿔 표현했다."},{"q":"What does the woman imply when she says, \"Many of our plants grow well in low light\"?","choices":["The lobby is suitable for plants.","The man should move his office.","The plants need less water.","Some plants will cost more."],"answer":0,"type":"의도 파악","explanation":"남자가 로비에 햇빛이 잘 들지 않는다고 걱정하자 한 말이므로, 빛이 적은 로비에도 식물을 둘 수 있다는 뜻이다. 물을 덜 줘도 된다는 내용은 없다."},{"q":"What does the woman offer to do on Thursday?","choices":["Sign a contract","Deliver some plants","Visit the man's office","Send a revised quote"],"answer":2,"type":"요청·제안","explanation":"남자가 계약 전에 공간을 봐 달라고 하자 여자가 \"I can stop by around two\"라고 했으므로 목요일에 사무실을 방문하겠다고 제안했다. 계약은 방문 후의 일이다."}],"translation":"W: 안녕하세요, 그린 오피스 식물 관리 서비스의 어맨다입니다. 지난주에 보내 드린 견적 관련해서 다시 연락드렸어요.\nM: 아, 전화 주셔서 고마워요. 검토해 봤는데, 로비와 회의실에 식물을 두는 데 관심이 있어요.\nW: 좋습니다. 기본 요금제에는 매주 방문해서 물 주기와 가지치기가 포함돼요. 그리고 식물이 죽으면 무료로 교체해 드려요.\nM: 좋네요. 그런데 걱정되는 게 하나 있어요. 저희 로비에는 햇빛이 많이 들지 않아요.\nW: 문제없어요. 저희 식물 중에는 빛이 적은 곳에서도 잘 자라는 게 많아요.\nM: 알겠어요. 계약하기 전에 누가 와서 공간을 봐 줄 수 있나요?\nW: 물론이죠. 목요일에 그쪽 근처에 가요. 괜찮으시면 2시쯤 들를 수 있어요.","part":3},{"id":"p3-079","level":3,"topic":"병원 간호사 교대 근무 인수인계","speakers":{"W":"female","M":"male","W2":"female"},"script":[{"s":"W","t":"Good morning, Marcus. Before I go home, let me update you on the patients in rooms 5 through 8."},{"s":"M","t":"Thanks, Helen. Anything I should know about right away?"},{"s":"W","t":"The patient in room 6 had a fever overnight. It's down now, but the doctor wants his temperature checked every two hours."},{"s":"M","t":"Got it. I'll make a note of that."},{"s":"W2","t":"Sorry to interrupt. Marcus, the patient in room 8 is being discharged this morning. His family is coming to pick him up at eleven."},{"s":"M","t":"OK. Has the paperwork been prepared?"},{"s":"W2","t":"Not yet. The doctor still needs to sign the discharge form."},{"s":"M","t":"I'll call her office after I check on room 6."}],"graphic":null,"questions":[{"q":"Who most likely are the speakers?","choices":["Patients' relatives","Hospital staff","Pharmacy workers","Hotel employees"],"answer":1,"type":"화자 정보(직업·장소)","explanation":"병실(rooms 5 through 8)의 환자 상태, 체온 측정, 퇴원 서류를 이야기하며 교대 인수인계를 하므로 병원 직원들이다."},{"q":"What does Helen say about the patient in room 6?","choices":["His family will visit him at eleven.","He needs to change rooms.","He is leaving the hospital today.","His temperature needs to be monitored."],"answer":3,"type":"세부 사항","explanation":"헬렌이 6호실 환자가 밤에 열이 났으며 의사가 \"his temperature checked every two hours\"를 원한다고 했으므로 체온을 계속 확인해야 한다. 오늘 퇴원하는 사람은 8호실 환자다."},{"q":"What will Marcus do after checking on room 6?","choices":["Contact a doctor's office","Prepare a new room","Go home","Meet a patient's family"],"answer":0,"type":"다음 할 일","explanation":"마커스가 \"I'll call her office after I check on room 6\"라고 했고 her는 퇴원 서류에 서명해야 하는 의사이므로 의사 사무실에 연락할 것이다. 집에 가는 사람은 교대를 마친 헬렌이다."}],"translation":"W: 좋은 아침이에요, 마커스. 퇴근하기 전에 5호실부터 8호실 환자들 상황을 알려 줄게요.\nM: 고마워요, 헬렌. 바로 알아야 할 게 있나요?\nW: 6호실 환자가 밤새 열이 났어요. 지금은 내렸지만, 의사 선생님이 두 시간마다 체온을 재 달래요.\nM: 알겠어요. 적어 둘게요.\nW2: 말씀 중에 죄송해요. 마커스, 8호실 환자가 오늘 오전에 퇴원해요. 가족분들이 11시에 데리러 오세요.\nM: 네. 서류는 준비됐나요?\nW2: 아직이요. 의사 선생님이 퇴원 서류에 서명을 해야 해요.\nM: 6호실 확인하고 나서 선생님 사무실에 전화할게요.","part":3},{"id":"p3-080","level":3,"topic":"엘리베이터 정기 점검 일정 조율","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, Ms. Kim. This is Paul from Summit Elevator Services. We're scheduled to do maintenance at your building next week, and I wanted to confirm the times."},{"s":"W","t":"Thanks, Paul. I have the schedule you sent in front of me. Is there a problem?"},{"s":"M","t":"Actually, one of our technicians is out sick, so we can't do the job on Tuesday. We'd like to move it to Friday, same time."},{"s":"W","t":"Friday's a bit difficult. Our company is moving some furniture to the eighth floor that afternoon, and we'll need the freight elevator."},{"s":"M","t":"I see. What if we do it Friday morning instead, from eight to ten?"},{"s":"W","t":"That should work. The movers won't arrive until one."},{"s":"M","t":"Great. I'll send you an updated schedule by e-mail today."}],"graphic":{"title":"Summit Elevator Services — Maintenance Schedule","rows":[["Day","Elevator","Time"],["Monday","Elevator A (lobby)","8:00 – 10:00 A.M."],["Tuesday","Freight elevator","1:00 – 3:00 P.M."],["Wednesday","Elevator B (lobby)","8:00 – 10:00 A.M."],["Thursday","Parking garage elevator","1:00 – 3:00 P.M."]]},"questions":[{"q":"Why does the man want to change the schedule?","choices":["A worker is not available.","The building will be closed.","The job will take longer than expected.","Some parts have not arrived."],"answer":0,"type":"세부 사항","explanation":"남자가 \"one of our technicians is out sick\"이라고 했으므로 기술자 한 명이 아파서 일할 수 없기 때문이다."},{"q":"Look at the graphic. Which elevator's maintenance will be rescheduled?","choices":["Elevator A (lobby)","Freight elevator","Elevator B (lobby)","Parking garage elevator"],"answer":1,"type":"시각 자료 연계","explanation":"남자가 화요일 작업을 할 수 없다고 했고, 표에서 화요일 점검 대상은 화물용 엘리베이터(Freight elevator)다. 여자가 금요일 오후 가구 이동에 화물 엘리베이터가 필요하다고 한 것도 이와 맞는다."},{"q":"What will happen on Friday afternoon?","choices":["A new elevator will be installed.","Furniture will be moved.","A company meeting will be held.","A safety inspection will take place."],"answer":1,"type":"세부 사항","explanation":"여자가 \"Our company is moving some furniture to the eighth floor that afternoon\"이라고 했으므로 금요일 오후에 가구를 옮긴다. 엘리베이터 점검은 금요일 오전으로 옮겨졌다."}],"translation":"M: 안녕하세요, 김 선생님. 서밋 엘리베이터 서비스의 폴입니다. 다음 주에 건물 점검이 잡혀 있어서 시간을 확인하려고 연락드렸어요.\nW: 고마워요, 폴. 보내 주신 일정표를 보고 있어요. 문제가 있나요?\nM: 사실 기술자 한 명이 아파서 화요일 작업을 못 하게 됐어요. 금요일 같은 시간으로 옮기고 싶어요.\nW: 금요일은 좀 곤란해요. 그날 오후에 저희 회사가 8층으로 가구를 옮기는데 화물 엘리베이터가 필요하거든요.\nM: 그렇군요. 그럼 금요일 오전 8시부터 10시까지 하면 어떨까요?\nW: 그건 괜찮을 것 같아요. 이삿짐 업체는 1시나 돼야 오거든요.\nM: 좋습니다. 오늘 수정된 일정표를 이메일로 보내 드릴게요.","part":3},{"id":"p3-081","level":3,"topic":"자선 경매 기부 물품 모집","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, Tony. You're on the planning committee for the children's hospital charity auction, aren't you?"},{"s":"M","t":"Yes, I am. We're still collecting items for it. The auction is on the twentieth."},{"s":"W","t":"Well, my sister owns a pottery studio, and she said she'd be happy to donate a set of handmade bowls."},{"s":"M","t":"That's wonderful. Last year, the handmade items raised the most money."},{"s":"W","t":"She was also wondering whether she could put a small sign next to the bowls with the name of her studio."},{"s":"M","t":"I'll have to check with the committee chair. But we did that for a few local businesses last year."},{"s":"W","t":"OK. When does she need to drop off the bowls?"},{"s":"M","t":"By the fifteenth. She can bring them to the community center."}],"graphic":null,"questions":[{"q":"What event are the speakers discussing?","choices":["A hospital opening","A fund-raising auction","A pottery class","A community festival"],"answer":1,"type":"주제·목적","explanation":"여자가 \"the children's hospital charity auction\"을 언급하고 기부 물품 이야기를 하므로 기금 마련 경매를 논의하고 있다. charity를 fund-raising으로 바꿔 표현했다."},{"q":"What does the man imply when he says, \"we did that for a few local businesses last year\"?","choices":["The committee needs more volunteers.","The woman's sister has donated before.","The request will probably be approved.","The auction was more successful last year."],"answer":2,"type":"의도 파악","explanation":"스튜디오 이름이 적힌 안내판을 둘 수 있는지 묻자 위원장에게 확인해야 하지만 작년에도 몇몇 지역 업체에 그렇게 해 줬다고 했으므로 요청이 받아들여질 가능성이 높다는 뜻이다."},{"q":"What should the woman's sister do by the fifteenth?","choices":["Pay a fee","Contact the committee chair","Register for the auction","Deliver her donation"],"answer":3,"type":"세부 사항","explanation":"남자가 그릇을 가져다 놓아야 하는 날짜를 \"By the fifteenth\"라고 했으므로 15일까지 기부 물품을 전달해야 한다. 위원장에게 확인하는 것은 남자가 할 일이다."}],"translation":"W: 안녕하세요, 토니. 어린이 병원 자선 경매 기획위원이시죠?\nM: 네, 맞아요. 아직 경매 물품을 모으고 있어요. 경매는 20일이에요.\nW: 그런데 제 여동생이 도자기 공방을 하는데, 수제 그릇 세트를 기꺼이 기부하겠대요.\nM: 정말 좋네요. 작년에 수제 물품이 가장 많은 돈을 모았어요.\nW: 그리고 그릇 옆에 공방 이름이 적힌 작은 안내판을 둘 수 있는지 궁금해하더라고요.\nM: 위원장님께 확인해 봐야 해요. 하지만 작년에 몇몇 지역 업체에는 그렇게 해 드렸어요.\nW: 알겠어요. 그릇은 언제까지 가져다 놓아야 하나요?\nM: 15일까지요. 주민 센터로 가져오시면 돼요.","part":3},{"id":"p3-082","level":3,"topic":"사내 식당 메뉴 설문 결과","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Olivia, have you seen the results of the cafeteria survey?"},{"s":"W","t":"I just finished reading them. Most employees are happy with the lunch menu, but a lot of people want more vegetarian options."},{"s":"M","t":"I noticed that too. Our current food supplier only offers two vegetarian dishes."},{"s":"W","t":"Right. And several people complained that the cafeteria closes too early. Some of the engineers work late and can't get dinner."},{"s":"M","t":"Extending the hours would cost more, though. We'd have to hire another cook."},{"s":"W","t":"What if we just put in a few vending machines with sandwiches and salads? That would be much cheaper."},{"s":"M","t":"Good idea. Why don't you look into some vending companies and bring a few options to Monday's meeting?"}],"graphic":null,"questions":[{"q":"What did many employees request in the survey?","choices":["A bigger dining area","Lower prices","More vegetarian meals","Faster service"],"answer":2,"type":"세부 사항","explanation":"여자가 \"a lot of people want more vegetarian options\"라고 했으므로 채식 메뉴를 더 원했다."},{"q":"Why does the man hesitate to extend the cafeteria's hours?","choices":["It would increase costs.","The building closes early.","Few employees work late.","The supplier cannot deliver at night."],"answer":0,"type":"세부 사항","explanation":"남자가 \"Extending the hours would cost more\"라며 요리사를 더 뽑아야 한다고 했으므로 비용 증가 때문이다. 늦게까지 일하는 엔지니어들이 있다고 했으니 야근자가 적다는 것은 틀리다."},{"q":"What does the man ask the woman to do?","choices":["Hire a new cook","Conduct another survey","Research some vending companies","Change food suppliers"],"answer":2,"type":"요청·제안","explanation":"남자가 \"Why don't you look into some vending companies and bring a few options\"라고 했으므로 자판기 업체를 알아봐 달라는 요청이다. look into를 research로 바꿔 표현했다."}],"translation":"M: 올리비아, 구내식당 설문 결과 봤어요?\nW: 방금 다 읽었어요. 직원 대부분이 점심 메뉴에 만족하는데, 채식 메뉴를 더 원하는 사람이 많아요.\nM: 저도 그걸 봤어요. 지금 식자재 업체는 채식 요리를 두 가지밖에 안 해요.\nW: 맞아요. 그리고 식당이 너무 일찍 닫는다는 불만도 여럿 있었어요. 늦게까지 일하는 엔지니어들이 저녁을 못 먹는대요.\nM: 그런데 운영 시간을 늘리면 비용이 더 들어요. 요리사를 한 명 더 뽑아야 하거든요.\nW: 샌드위치랑 샐러드를 파는 자판기를 몇 대 들이면 어때요? 그게 훨씬 저렴할 거예요.\nM: 좋은 생각이네요. 자판기 업체를 몇 군데 알아보고 월요일 회의에 몇 가지 안을 가져와 줄래요?","part":3},{"id":"p3-083","level":3,"topic":"회사 야유회 전세 버스 선택","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Jason, I'm booking the bus for our company picnic at Lake Hartley. Can you help me choose a company?"},{"s":"M","t":"Sure. How many people have signed up?"},{"s":"W","t":"Forty-two so far, and a few more might join."},{"s":"M","t":"Then we need a bus with at least fifty seats, just to be safe."},{"s":"W","t":"I agree. There are two options with enough seats. One of them has free Wi-Fi, but it's more expensive."},{"s":"M","t":"The drive is only an hour. I don't think people need Wi-Fi. Let's go with the cheaper one."},{"s":"W","t":"OK. I'll call them this afternoon. By the way, could you send a reminder to everyone that the sign-up deadline is Friday?"}],"graphic":{"title":"Charter Bus Options","rows":[["Company","Seats","Wi-Fi","Price"],["Road Star","35","Yes","$450"],["Blue Line","45","No","$520"],["Metro Coach","55","No","$600"],["Express Tours","55","Yes","$720"]]},"questions":[{"q":"What are the speakers planning?","choices":["A training session","A client meeting","Transportation for a company outing","A business trip abroad"],"answer":2,"type":"주제·목적","explanation":"여자가 \"I'm booking the bus for our company picnic\"이라고 했으므로 회사 야유회 교통편을 준비하고 있다."},{"q":"Look at the graphic. Which company will the woman most likely call?","choices":["Road Star","Blue Line","Metro Coach","Express Tours"],"answer":2,"type":"시각 자료 연계","explanation":"50석 이상인 버스는 Metro Coach와 Express Tours인데, 남자가 와이파이가 필요 없으니 더 싼 곳으로 하자고 했다. 표에서 와이파이가 없고 더 싼 600달러짜리 Metro Coach다."},{"q":"What does the woman ask the man to do?","choices":["Remind employees about a deadline","Collect money from participants","Call a bus company","Reserve a picnic area"],"answer":0,"type":"요청·제안","explanation":"여자가 \"could you send a reminder to everyone that the sign-up deadline is Friday?\"라고 했으므로 신청 마감일을 직원들에게 다시 알려 달라고 했다. 버스 회사에는 여자가 직접 전화한다."}],"translation":"W: 제이슨, 하틀리 호수로 가는 회사 야유회 버스를 예약하려는데요. 업체 고르는 것 좀 도와줄래요?\nM: 그럼요. 몇 명이 신청했어요?\nW: 지금까지 42명이고, 몇 명 더 올 수도 있어요.\nM: 그럼 만일을 위해 적어도 50석짜리 버스가 필요하겠네요.\nW: 동감이에요. 좌석이 충분한 곳이 두 군데 있어요. 한 곳은 무료 와이파이가 있는데 더 비싸요.\nM: 한 시간밖에 안 걸리잖아요. 와이파이는 필요 없을 것 같아요. 더 싼 곳으로 해요.\nW: 좋아요. 오늘 오후에 전화할게요. 그런데 신청 마감이 금요일이라고 모두에게 다시 알려 줄 수 있어요?","part":3},{"id":"p3-084","level":3,"topic":"배송 트럭 경로 변경","speakers":{"M":"male","W":"female","M2":"male"},"script":[{"s":"M","t":"Sandra, Eric, have you heard? The city is closing the Fulton Bridge for repairs starting Monday."},{"s":"W","t":"Oh no. Half of our delivery trucks use that bridge every morning."},{"s":"M2","t":"I just checked the map. If the drivers take the Harbor Road instead, it adds about twenty minutes to each trip."},{"s":"W","t":"That means some stores won't get their deliveries before they open."},{"s":"M","t":"Could we start loading the trucks earlier? Say, at five instead of six?"},{"s":"M2","t":"The warehouse crew won't be thrilled."},{"s":"W","t":"Maybe we can offer them a bonus for the early shift while the bridge is closed. I'll talk to the operations manager about the budget."},{"s":"M","t":"Good. And Eric, can you update the route plans for the drivers?"}],"graphic":null,"questions":[{"q":"What problem are the speakers discussing?","choices":["A store has canceled an order.","A bridge will be closed.","A truck has broken down.","A warehouse is short of space."],"answer":1,"type":"주제·목적","explanation":"첫 남자가 \"The city is closing the Fulton Bridge for repairs\"라고 했고 그 영향으로 배송 경로를 바꾸는 이야기를 하므로 다리 폐쇄가 문제다."},{"q":"What does Eric imply when he says, \"The warehouse crew won't be thrilled\"?","choices":["The warehouse will close early.","Workers are not trained for the new route.","Workers may not like starting earlier.","The warehouse needs more staff."],"answer":2,"type":"의도 파악","explanation":"트럭 적재를 6시에서 5시로 앞당기자는 제안에 대한 반응이므로 창고 직원들이 일찍 출근하는 것을 싫어할 것이라는 뜻이다. 그래서 여자가 조기 근무 보너스를 제안한다."},{"q":"What will the woman most likely do next?","choices":["Call the city office","Speak with a manager","Update the route plans","Load the trucks"],"answer":1,"type":"다음 할 일","explanation":"여자가 \"I'll talk to the operations manager about the budget\"이라고 했으므로 운영 관리자와 이야기할 것이다. 경로 계획 수정은 에릭에게 맡긴 일이다."}],"translation":"M: 샌드라, 에릭, 소식 들었어요? 시에서 월요일부터 보수 공사 때문에 풀턴 다리를 막는대요.\nW: 이런. 우리 배송 트럭 절반이 매일 아침 그 다리를 이용하잖아요.\nM2: 방금 지도를 봤어요. 기사들이 대신 하버 로드로 가면 운행마다 20분 정도 더 걸려요.\nW: 그럼 몇몇 매장은 문 열기 전에 물건을 못 받겠네요.\nM: 트럭 싣는 걸 더 일찍 시작하면 어때요? 6시 말고 5시로요.\nM2: 창고 직원들이 반기지는 않을 거예요.\nW: 다리가 막혀 있는 동안 조기 근무 수당을 주는 방법도 있어요. 제가 운영 관리자에게 예산 얘기를 해 볼게요.\nM: 좋아요. 그리고 에릭, 기사들 경로 계획을 수정해 줄 수 있어요?","part":3},{"id":"p3-085","level":4,"topic":"연구실 원심분리기 구매 검토","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Dr. Singh, I've narrowed down the centrifuge options for the lab. Do you have a minute to go over them?"},{"s":"M","t":"Sure. Remember, whatever we order has to fit on the bench by the window, so nothing wider than sixty centimeters."},{"s":"W","t":"Right, I've already ruled out the one that was too big. Of the remaining three, the fastest one is also the most expensive."},{"s":"M","t":"We don't really need top speed for the blood samples we process. What matters more is how quiet it is. The research assistants have been complaining about the noise from our old one."},{"s":"W","t":"In that case, this model is clearly the best choice. It's also within our budget."},{"s":"M","t":"Great. Go ahead and place the order. And ask the supplier whether they'll take our old unit away when they deliver the new one."}],"graphic":{"title":"Centrifuge Comparison","rows":[["Model","Width","Max Speed","Noise Level"],["CX-200","55 cm","15,000 rpm","58 dB"],["CX-300","58 cm","18,000 rpm","62 dB"],["LabSpin 5","59 cm","12,000 rpm","48 dB"],["ProSpin X","72 cm","20,000 rpm","65 dB"]]},"questions":[{"q":"What requirement does the man mention first?","choices":["The equipment must be made by a certain company.","The equipment must be delivered this week.","The equipment must come with training.","The equipment must fit in a limited space."],"answer":3,"type":"세부 사항","explanation":"남자가 처음에 \"it has to fit on the bench by the window, so nothing wider than sixty centimeters\"라고 했으므로 정해진 공간에 들어가야 한다는 조건이다."},{"q":"Look at the graphic. Which model will the woman most likely order?","choices":["CX-200","CX-300","LabSpin 5","ProSpin X"],"answer":2,"type":"시각 자료 연계","explanation":"폭 72cm인 ProSpin X는 이미 제외됐고, 남자는 속도보다 소음이 적은 것이 중요하다고 했다. 나머지 셋 중 소음이 가장 낮은 48dB의 LabSpin 5가 답이다. CX-300은 남은 것 중 가장 빠른 모델이다."},{"q":"What does the man ask the woman to find out?","choices":["Whether a discount is available","How long the warranty lasts","When the research assistants are available","Whether the supplier will remove old equipment"],"answer":3,"type":"요청·제안","explanation":"남자가 \"ask the supplier whether they'll take our old unit away\"라고 했으므로 공급업체가 기존 장비를 수거해 가는지 알아봐 달라고 했다. take away를 remove로 바꿔 표현했다."}],"translation":"W: 싱 박사님, 연구실 원심분리기 후보를 좁혀 봤어요. 잠깐 같이 검토해 주실 수 있나요?\nM: 그럼요. 무엇을 주문하든 창가 실험대 위에 들어가야 하니까 폭이 60센티미터를 넘으면 안 돼요.\nW: 맞아요, 너무 큰 건 이미 뺐어요. 남은 세 개 중에서 가장 빠른 게 가장 비싸기도 해요.\nM: 우리가 처리하는 혈액 샘플에는 최고 속도가 꼭 필요하진 않아요. 더 중요한 건 얼마나 조용하냐예요. 연구 보조원들이 예전 장비 소음 때문에 계속 불평하고 있거든요.\nW: 그렇다면 이 모델이 확실히 가장 좋겠네요. 예산 안에도 들어가고요.\nM: 좋아요. 주문 진행해 주세요. 그리고 새 장비를 배송할 때 예전 장비를 가져가 주는지 공급업체에 물어봐 주세요.","part":3},{"id":"p3-086","level":4,"topic":"미술관 신규 전시 조명 설치","speakers":{"W":"female","M":"male","W2":"female"},"script":[{"s":"W","t":"Thanks for coming in on short notice, Victor. As you can see, the new photography exhibit opens on Saturday, and the lighting still isn't right."},{"s":"M","t":"I noticed that when I walked in. There's a lot of glare on the glass frames along this wall."},{"s":"W2","t":"That's what worries me as the curator. Visitors won't be able to see the photos clearly."},{"s":"M","t":"The problem is the angle of the ceiling lights. If we replace these fixtures with adjustable track lights, we can point them away from the glass."},{"s":"W","t":"How long would that take?"},{"s":"M","t":"My team could install them on Thursday, but I'd need to order the fixtures today."},{"s":"W2","t":"Our budget for the exhibit is almost used up, though."},{"s":"W","t":"I'll ask the director if we can use some of the funds from next quarter. Victor, please send me a written estimate within the hour."}],"graphic":null,"questions":[{"q":"What problem are the speakers discussing?","choices":["Some photographs were damaged.","The ceiling needs to be repaired.","Light is reflecting off some frames.","The exhibit opening was postponed."],"answer":2,"type":"주제·목적","explanation":"남자가 \"There's a lot of glare on the glass frames\"라고 했고 큐레이터도 관람객이 사진을 제대로 못 볼 것을 걱정하므로 액자 유리에 빛이 반사되는 문제다. glare를 light reflecting으로 바꿔 표현했다."},{"q":"What is the man's proposed solution?","choices":["Closing the window blinds","Installing adjustable lights","Using a different type of glass","Moving the photos to another wall"],"answer":1,"type":"세부 사항","explanation":"남자가 \"replace these fixtures with adjustable track lights\"를 제안하고 빛을 유리 반대쪽으로 향하게 하자고 했으므로 각도 조절 조명 설치가 해결책이다."},{"q":"What does the first woman ask Victor to do?","choices":["Speak with the director","Install the lights today","Provide a cost estimate","Reduce his team's fee"],"answer":2,"type":"요청·제안","explanation":"첫 번째 여자가 \"Victor, please send me a written estimate within the hour\"라고 했으므로 서면 견적을 요청했다. 관장과 이야기하는 것은 여자 자신이 할 일이다."}],"translation":"W: 급하게 불렀는데 와 줘서 고마워요, 빅터. 보다시피 새 사진전이 토요일에 개막하는데 조명이 아직 제대로 안 돼 있어요.\nM: 들어오면서 봤어요. 이쪽 벽 유리 액자에 빛 반사가 심하네요.\nW2: 큐레이터로서 제가 걱정하는 게 그거예요. 관람객들이 사진을 제대로 못 볼 거예요.\nM: 문제는 천장 조명의 각도예요. 이 조명 기구를 각도 조절이 되는 트랙 조명으로 바꾸면 빛을 유리 반대쪽으로 돌릴 수 있어요.\nW: 얼마나 걸릴까요?\nM: 저희 팀이 목요일에 설치할 수 있는데, 조명 기구는 오늘 주문해야 해요.\nW2: 그런데 전시 예산이 거의 다 떨어졌어요.\nW: 다음 분기 자금을 일부 쓸 수 있는지 관장님께 여쭤볼게요. 빅터, 한 시간 안에 서면 견적서를 보내 주세요.","part":3},{"id":"p3-087","level":4,"topic":"온라인 교육 플랫폼 계약 갱신","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, Monica. Our contract with LearnPoint is up for renewal next month. Have you had a chance to look at the usage report?"},{"s":"W","t":"I have. Only about a third of our staff logged in more than once last year."},{"s":"M","t":"That's lower than I expected, considering what we pay for it."},{"s":"W","t":"I asked a few people why, and they said most of the courses are too general. They want training that's specific to our industry."},{"s":"M","t":"LearnPoint did say they're adding a logistics series this spring."},{"s":"W","t":"They've been saying that for two years."},{"s":"M","t":"Fair enough. Then let's ask a couple of other providers for proposals before we decide anything. Could you put together a list of the topics our staff want most?"}],"graphic":null,"questions":[{"q":"What did the woman find in the usage report?","choices":["The number of users has doubled.","The platform is too expensive to maintain.","Most courses were completed on time.","Few employees use the platform regularly."],"answer":3,"type":"세부 사항","explanation":"여자가 \"Only about a third of our staff logged in more than once last year\"라고 했으므로 플랫폼을 꾸준히 쓰는 직원이 적다. 가격이 비싸다는 것은 남자의 반응이지 보고서 내용이 아니다."},{"q":"What does the woman imply when she says, \"They've been saying that for two years\"?","choices":["She wants a two-year contract.","She already took the new courses.","She doubts the company's promise.","She thinks the courses are outdated."],"answer":2,"type":"의도 파악","explanation":"물류 과정을 이번 봄에 추가한다는 말에 2년째 그 말만 하고 있다고 답했으므로 그 약속을 믿지 않는다는 뜻이다. 그래서 남자도 \"Fair enough\"라며 다른 업체를 알아보자고 한다."},{"q":"What does the man ask the woman to do?","choices":["Identify employees' preferred training topics","Design a new logistics course","Renew the current contract","Contact LearnPoint's sales team"],"answer":0,"type":"요청·제안","explanation":"남자가 \"Could you put together a list of the topics our staff want most?\"라고 했으므로 직원들이 가장 원하는 교육 주제를 정리해 달라는 요청이다. 다른 업체에 제안을 받는 것은 결정 전에 할 일이지 여자에게 맡긴 일이 아니다."}],"translation":"M: 안녕하세요, 모니카. 런포인트와의 계약이 다음 달에 갱신이에요. 이용 현황 보고서 볼 기회가 있었어요?\nW: 봤어요. 작년에 두 번 이상 접속한 직원이 3분의 1 정도밖에 안 돼요.\nM: 우리가 내는 비용을 생각하면 예상보다 낮네요.\nW: 몇 사람한테 이유를 물었더니 과정 대부분이 너무 일반적이래요. 우리 업계에 맞는 교육을 원한대요.\nM: 런포인트가 이번 봄에 물류 시리즈를 추가한다고는 했어요.\nW: 2년째 그 말만 하고 있어요.\nM: 그렇긴 하네요. 그럼 결정하기 전에 다른 업체 두어 곳에 제안서를 받아 봅시다. 직원들이 가장 원하는 주제 목록을 정리해 줄 수 있어요?","part":3},{"id":"p3-088","level":4,"topic":"식당 메뉴 개편용 식자재 공급업체 선택","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Carlos, I've been comparing suppliers for the seafood on our new summer menu. Here are the four I contacted."},{"s":"M","t":"Thanks. Freshness is my top priority, so I'd rather not use anyone who delivers less than three times a week."},{"s":"W","t":"That leaves two of them. One is a bit cheaper, but they require a minimum order that's way more than we'd use."},{"s":"M","t":"Then we'd end up throwing food away. Let's go with the other one."},{"s":"W","t":"OK. I'll ask them to send a sample of their salmon and shrimp this week so you can test the new recipes."},{"s":"M","t":"Perfect. And let's keep the menu launch on the first of June. If the samples aren't good, though, we'll have to rethink the whole seafood section."}],"graphic":{"title":"Seafood Supplier Comparison","rows":[["Supplier","Deliveries per Week","Minimum Order"],["Ocean Harvest","2","$300"],["Blue Bay Foods","5","$1,500"],["Coastline Market","3","$400"],["Northern Catch","1","$200"]]},"questions":[{"q":"What is the man's main concern about suppliers?","choices":["How quickly they respond","How they package the food","Where they are located","How fresh the food will be"],"answer":3,"type":"세부 사항","explanation":"남자가 \"Freshness is my top priority\"라며 주 3회 미만 배송 업체는 쓰지 않겠다고 했으므로 식재료 신선도가 가장 중요하다."},{"q":"Look at the graphic. Which supplier will the speakers most likely use?","choices":["Ocean Harvest","Blue Bay Foods","Coastline Market","Northern Catch"],"answer":2,"type":"시각 자료 연계","explanation":"주 3회 이상 배송하는 곳은 Blue Bay Foods(5회)와 Coastline Market(3회)이다. 여자가 한 곳은 최소 주문량이 너무 많다고 했고 남자가 음식을 버리게 될 것이라며 다른 곳으로 하자고 했으므로, 최소 주문액 1,500달러인 Blue Bay가 아닌 Coastline Market이다."},{"q":"What will the woman request from the supplier?","choices":["Product samples","A signed contract","A lower price","A delivery schedule"],"answer":0,"type":"요청·제안","explanation":"여자가 \"I'll ask them to send a sample of their salmon and shrimp\"라고 했으므로 샘플을 요청할 것이다."}],"translation":"W: 카를로스, 새 여름 메뉴에 쓸 해산물 공급업체를 비교해 봤어요. 연락해 본 네 곳이에요.\nM: 고마워요. 저는 신선도가 가장 중요해서 일주일에 세 번 미만으로 배송하는 곳은 쓰고 싶지 않아요.\nW: 그러면 두 곳이 남아요. 한 곳이 조금 더 싼데, 최소 주문량이 우리가 쓰는 양보다 훨씬 많아요.\nM: 그럼 결국 음식을 버리게 되겠네요. 다른 곳으로 하죠.\nW: 알겠어요. 새 레시피를 시험해 보실 수 있게 이번 주에 연어와 새우 샘플을 보내 달라고 할게요.\nM: 좋아요. 그리고 메뉴 출시는 6월 1일로 유지합시다. 다만 샘플이 별로면 해산물 부문 전체를 다시 생각해야 해요.","part":3},{"id":"p3-089","level":4,"topic":"고객센터 통화 대기 시간 단축","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Nadia, I just saw last month's numbers for the customer service center. The average wait time on the phone was over twelve minutes."},{"s":"W","t":"I know. Since we launched the new smartphone, calls about setting it up have tripled."},{"s":"M","t":"Is there anything we can do quickly? Hiring and training new agents would take at least two months."},{"s":"W","t":"Well, most callers are asking the same five or six questions."},{"s":"M","t":"So you're thinking of a video guide?"},{"s":"W","t":"Exactly. We could post short setup videos on our Web site and play a message during the wait that tells callers where to find them."},{"s":"M","t":"I like that. Can you get the product team to help with the scripts? They know the features best."},{"s":"W","t":"I'll set up a meeting with them tomorrow."}],"graphic":null,"questions":[{"q":"What caused the increase in calls?","choices":["A change in prices","A problem with the Web site","The release of a new product","A shortage of agents"],"answer":2,"type":"세부 사항","explanation":"여자가 \"Since we launched the new smartphone, calls about setting it up have tripled\"라고 했으므로 신제품 출시 이후 문의가 늘었다. launched를 release로 바꿔 표현했다."},{"q":"Why does the woman say, \"most callers are asking the same five or six questions\"?","choices":["To complain that customers do not read manuals","To show that the problem is not serious","To explain why agents need more training","To suggest that common questions could be answered another way"],"answer":3,"type":"의도 파악","explanation":"신입 상담원을 뽑는 데 오래 걸린다는 말에 이어 한 말이고, 남자가 곧바로 영상 안내를 떠올리므로 반복되는 질문은 다른 방법으로 해결할 수 있다는 제안이다."},{"q":"What will the woman do tomorrow?","choices":["Meet with the product team","Record a phone message","Interview new agents","Update the Web site"],"answer":0,"type":"다음 할 일","explanation":"남자가 제품팀에 대본 작성 도움을 받으라고 하자 여자가 \"I'll set up a meeting with them tomorrow\"라고 했으므로 내일 제품팀과 회의한다."}],"translation":"M: 나디아, 방금 고객센터 지난달 수치를 봤어요. 전화 평균 대기 시간이 12분이 넘더라고요.\nW: 알아요. 새 스마트폰을 출시한 뒤로 설정 관련 전화가 세 배로 늘었어요.\nM: 빨리 할 수 있는 방법이 있을까요? 새 상담원을 뽑아서 교육하려면 적어도 두 달은 걸릴 거예요.\nW: 음, 전화하는 사람 대부분이 똑같은 대여섯 가지 질문을 해요.\nM: 그럼 영상 안내를 생각하는 거예요?\nW: 맞아요. 웹사이트에 짧은 설정 영상을 올리고, 대기 중에 영상 위치를 알려 주는 안내 메시지를 틀면 돼요.\nM: 좋네요. 제품팀에 대본 작성을 도와 달라고 해 줄래요? 기능은 그 사람들이 제일 잘 아니까요.\nW: 내일 그 팀과 회의를 잡을게요.","part":3},{"id":"p3-090","level":4,"topic":"사옥 옥상 정원 조성 공사","speakers":{"M":"male","W":"female","M2":"male"},"script":[{"s":"M","t":"Thanks for meeting with us, Ms. Porter. We'd like to turn the roof of our building into a garden where employees can take breaks."},{"s":"W","t":"That's a great idea. Before we design anything, though, we'll need an engineer to confirm that the roof can support the extra weight of soil and planters."},{"s":"M2","t":"I'm the facilities manager here. The building was renovated five years ago, and I have the structural reports from that project."},{"s":"W","t":"That would save a lot of time. If the reports are recent enough, we might not need a new inspection at all."},{"s":"M","t":"How long would the whole project take?"},{"s":"W","t":"Usually about three months. But we don't plant anything during winter, so if we don't start by October, it'll have to wait until spring."},{"s":"M2","t":"I'll send you the reports this afternoon."}],"graphic":null,"questions":[{"q":"What does the company want to create?","choices":["A vegetable garden to sell produce","A new parking area","A larger lobby","A rooftop space for employees"],"answer":3,"type":"주제·목적","explanation":"첫 남자가 \"turn the roof of our building into a garden where employees can take breaks\"라고 했으므로 직원용 옥상 정원을 만들려 한다."},{"q":"Why might the project be completed more quickly?","choices":["The design is already finished.","Existing documents may be sufficient.","The plants have been ordered.","The company has hired extra workers."],"answer":1,"type":"세부 사항","explanation":"시설 관리자가 5년 전 보수 공사 때의 구조 보고서가 있다고 하자 여자가 최근 것이면 새 점검이 필요 없을 수도 있어 시간이 많이 절약된다고 했다. 기존 문서로 충분할 수 있다는 것이 이유다."},{"q":"According to the woman, what could delay the project?","choices":["Starting after a certain month","Bad weather in the spring","A change in city regulations","A shortage of materials"],"answer":0,"type":"세부 사항","explanation":"여자가 \"if we don't start by October, it'll have to wait until spring\"이라고 했으므로 10월 이후에 시작하면 봄까지 미뤄진다. 겨울에 심지 않기 때문이지 봄 날씨가 문제가 아니다."}],"translation":"M: 만나 주셔서 감사합니다, 포터 씨. 저희 건물 옥상을 직원들이 쉴 수 있는 정원으로 바꾸고 싶어요.\nW: 좋은 생각이네요. 다만 설계를 하기 전에 옥상이 흙과 화분의 추가 무게를 견딜 수 있는지 엔지니어가 확인해야 해요.\nM2: 제가 이곳 시설 관리자예요. 건물을 5년 전에 보수했는데, 그때 만든 구조 보고서가 있어요.\nW: 그러면 시간이 많이 절약되겠네요. 보고서가 충분히 최근 것이면 새로 점검할 필요가 아예 없을 수도 있어요.\nM: 전체 공사는 얼마나 걸릴까요?\nW: 보통 석 달 정도요. 하지만 겨울에는 아무것도 심지 않아서 10월까지 시작하지 못하면 봄까지 기다려야 해요.\nM2: 오늘 오후에 보고서를 보내 드릴게요.","part":3},{"id":"p3-091","level":4,"topic":"출판사 원고 교정 일정 조정","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, Ben. It's Laura from Maple Press. I'm calling about the production schedule for your cookbook."},{"s":"M","t":"Hi, Laura. Is everything on track?"},{"s":"W","t":"Mostly. But the photographer just told us she needs another week to reshoot the dessert chapter. The lighting in the first photos wasn't right."},{"s":"M","t":"I see. Does that push back the publication date?"},{"s":"W","t":"Not necessarily. We could give you less time for your final review. Instead of two weeks, you'd have one."},{"s":"M","t":"That's tight, but I think I can manage. I've already read most of the text twice."},{"s":"W","t":"Great. Then the only step that moves is the photo shoot, and everything after it stays the same. I'll send you a revised schedule this afternoon."}],"graphic":{"title":"Maple Press — Production Schedule","rows":[["Stage","Deadline"],["Photo shoot","March 3"],["Page layout","March 17"],["Author's final review","March 31"],["Printing","April 14"]]},"questions":[{"q":"Who most likely is the man?","choices":["A printer","A chef at a restaurant","An author","A photographer"],"answer":2,"type":"화자 정보(직업·장소)","explanation":"여자가 \"the production schedule for your cookbook\"이라고 했고 남자가 최종 검토를 맡으므로 요리책의 저자다. 사진작가는 대화에 언급된 제3자다."},{"q":"Why is there a delay?","choices":["A printer is out of order.","Some photos must be taken again.","The text needs to be rewritten.","A chapter was added to the book."],"answer":1,"type":"세부 사항","explanation":"여자가 사진작가가 \"needs another week to reshoot the dessert chapter\"라고 했으므로 사진을 다시 찍어야 해서 늦어진다. reshoot를 taken again으로 바꿔 표현했다."},{"q":"Look at the graphic. Which deadline will be changed?","choices":["March 3","March 17","March 31","April 14"],"answer":0,"type":"시각 자료 연계","explanation":"여자가 \"the only step that moves is the photo shoot\"이라고 했으므로 표에서 Photo shoot의 마감일인 3월 3일이 바뀐다. 최종 검토 기간은 줄어들지만 마감일(3월 31일)은 그대로다."}],"translation":"W: 안녕하세요, 벤. 메이플 출판사의 로라예요. 요리책 제작 일정 때문에 전화했어요.\nM: 안녕하세요, 로라. 다 순조롭게 진행되고 있나요?\nW: 대체로요. 그런데 사진작가가 디저트 장을 다시 찍는 데 일주일이 더 필요하다고 방금 알려 왔어요. 처음 사진의 조명이 좋지 않았대요.\nM: 그렇군요. 그럼 출간일이 미뤄지나요?\nW: 꼭 그렇진 않아요. 작가님의 최종 검토 기간을 줄이면 돼요. 2주 대신 1주가 되는 거죠.\nM: 빠듯하지만 할 수 있을 것 같아요. 본문 대부분은 이미 두 번 읽었거든요.\nW: 좋아요. 그럼 바뀌는 건 사진 촬영 단계뿐이고 그 이후는 모두 그대로예요. 오늘 오후에 수정 일정표를 보내 드릴게요.","part":3},{"id":"p3-092","level":4,"topic":"공유 자전거 업체와의 직원 복지 제휴","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Greg, a representative from CityCycle contacted me. They're offering discounted bike-share memberships to companies in this district."},{"s":"M","t":"Interesting. How much of a discount?"},{"s":"W","t":"Forty percent off the annual fee if at least twenty employees sign up. And they'd install a docking station right outside our building."},{"s":"M","t":"That could really help with the parking shortage. We have more cars than spaces as it is."},{"s":"W","t":"That's what I was thinking. The only catch is that we'd have to commit for two years."},{"s":"M","t":"Two years is nothing if people actually use it."},{"s":"W","t":"True. Maybe we should send out a quick survey first to see how many people are interested."},{"s":"M","t":"Good idea. Put one together, and I'll mention it at Friday's staff meeting."}],"graphic":null,"questions":[{"q":"What is CityCycle offering?","choices":["Free bicycle repairs","Discounted memberships","Bicycle safety training","A new parking garage"],"answer":1,"type":"세부 사항","explanation":"여자가 CityCycle이 \"discounted bike-share memberships\"를 제안한다고 했으므로 할인된 회원권이다."},{"q":"What does the man mean when he says, \"Two years is nothing if people actually use it\"?","choices":["Two years is too short for the program.","Employees rarely ride bicycles.","The company should wait two years.","The contract length is not a serious concern."],"answer":3,"type":"의도 파악","explanation":"2년 약정이 유일한 단점이라는 말에 대한 대답이므로, 직원들이 실제로 이용한다면 약정 기간은 큰 문제가 아니라는 뜻이다."},{"q":"What will the woman most likely do next?","choices":["Create a survey","Lead a staff meeting","Visit a docking station","Sign a contract"],"answer":0,"type":"다음 할 일","explanation":"남자가 \"Put one together\"라고 설문을 만들라고 했으므로 여자는 설문지를 만들 것이다. 직원 회의에서 이 안건을 언급하는 사람은 남자다."}],"translation":"W: 그레그, 시티사이클 담당자에게서 연락이 왔어요. 이 지역 회사들에 공유 자전거 회원권을 할인해 준대요.\nM: 흥미롭네요. 얼마나 할인되나요?\nW: 직원이 최소 20명 가입하면 연회비 40퍼센트 할인이요. 그리고 우리 건물 바로 앞에 거치대도 설치해 준대요.\nM: 주차난 해결에 정말 도움이 될 수 있겠네요. 지금도 차가 주차 공간보다 많잖아요.\nW: 저도 그렇게 생각했어요. 단 하나 걸리는 건 2년 약정을 해야 한다는 거예요.\nM: 사람들이 실제로 이용하기만 하면 2년은 아무것도 아니죠.\nW: 맞아요. 먼저 간단한 설문을 돌려서 관심 있는 사람이 몇 명인지 보는 게 좋겠어요.\nM: 좋은 생각이에요. 설문을 만들어 주세요, 제가 금요일 직원 회의에서 얘기할게요.","part":3},{"id":"p3-093","level":5,"topic":"임상시험 데이터 외부 감사 대비","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Priya, the external auditors confirmed they'll be here the week of the ninth to review the data from our Phase Two trial."},{"s":"W","t":"That's earlier than we'd planned. Two of the partner clinics still haven't uploaded their final patient records."},{"s":"M","t":"I know. I called both of them this morning. One promised to finish by Friday. The other said they're, quote, doing their best."},{"s":"W","t":"So, in other words, don't count on it."},{"s":"M","t":"Pretty much. I'm wondering if we should ask the auditors to review that clinic's data separately, at a later date."},{"s":"W","t":"They might agree, as long as we explain it in writing. Auditors tend to be more flexible when the request is documented ahead of time."},{"s":"M","t":"Then could you draft a letter explaining the situation? I'll review it before it goes out, and we'll copy the legal department."}],"graphic":null,"questions":[{"q":"What problem does the woman mention?","choices":["A clinic has left the study.","The trial results were disappointing.","An auditor has canceled a visit.","Some records have not been submitted."],"answer":3,"type":"주제·목적","explanation":"여자가 \"Two of the partner clinics still haven't uploaded their final patient records\"라고 했으므로 일부 기록이 아직 제출되지 않았다. 감사 일정은 취소된 것이 아니라 예상보다 앞당겨졌다."},{"q":"What does the woman imply when she says, \"So, in other words, don't count on it\"?","choices":["She is not sure the trial will continue.","The auditors will not accept late data.","One clinic will probably miss the deadline.","The man should not call the clinic again."],"answer":2,"type":"의도 파악","explanation":"한 병원이 그저 \"doing their best\"라고만 답했다는 말에 대한 반응이므로 그 병원은 기한을 맞추지 못할 가능성이 높다는 뜻이다. 남자가 그 병원 데이터를 따로 검토받자고 이어 가는 것도 이를 뒷받침한다."},{"q":"What does the man ask the woman to do?","choices":["Contact the legal department","Prepare a written request","Visit the partner clinics","Postpone the audit"],"answer":1,"type":"요청·제안","explanation":"남자가 \"could you draft a letter explaining the situation?\"이라고 했으므로 상황을 설명하는 서면 요청서를 작성해 달라는 것이다. 법무팀은 참조로 넣을 대상일 뿐 여자에게 연락을 맡긴 것이 아니다."}],"translation":"M: 프리야, 외부 감사단이 2상 시험 데이터를 검토하러 9일이 있는 주에 온다고 확정했어요.\nW: 우리가 계획했던 것보다 이르네요. 협력 병원 두 곳이 아직 최종 환자 기록을 올리지 않았어요.\nM: 알아요. 오늘 아침에 두 곳 모두 전화했어요. 한 곳은 금요일까지 끝내겠다고 약속했고요. 다른 곳은, 그대로 옮기자면, '최선을 다하고 있다'고 하더군요.\nW: 그러니까 다시 말해 기대하지 말라는 거네요.\nM: 거의 그렇죠. 감사단에 그 병원 데이터는 나중에 따로 검토해 달라고 요청해야 하나 싶어요.\nW: 서면으로 설명하면 동의해 줄 수도 있어요. 감사단은 요청이 미리 문서로 오면 좀 더 유연한 편이거든요.\nM: 그럼 상황을 설명하는 서한 초안을 써 줄래요? 보내기 전에 제가 검토하고, 법무팀도 참조로 넣을게요.","part":3},{"id":"p3-094","level":5,"topic":"물류센터 자동화 로봇 공급업체 비교","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Now that we've seen all the demonstrations, I think we can eliminate a couple of the robot vendors for the distribution center."},{"s":"M","t":"Agreed. Frankly, anything that takes longer than six months to install is off the table. We can't have the floor disrupted through the holiday season."},{"s":"W","t":"That rules out two of them. And I'd be hesitant about the one with the lowest per-unit price. Their maintenance contract only covers the first year."},{"s":"M","t":"Right, and repair costs after that could easily wipe out the savings. So we're down to one option."},{"s":"W","t":"Its price is higher, but the three-year warranty and the installation time make it the safest choice."},{"s":"M","t":"I'll present it to the board on Tuesday. Could you get me the reference contacts they mentioned? I'd like to talk to a couple of their existing clients first."}],"graphic":{"title":"Warehouse Robot Vendors","rows":[["Vendor","Price per Unit","Installation","Maintenance Coverage"],["AutoMove","$38,000","4 months","1 year"],["StackPro","$45,000","9 months","3 years"],["LiftLogic","$47,500","5 months","3 years"],["Robonet","$52,000","8 months","2 years"]]},"questions":[{"q":"Why does the man want to avoid a long installation?","choices":["It would interfere with a busy period.","It would exceed the budget.","It would delay a board meeting.","It would require extra staff."],"answer":0,"type":"세부 사항","explanation":"남자가 설치가 길면 \"We can't have the floor disrupted through the holiday season\"이라고 했으므로 성수기 업무에 지장을 주기 때문이다. holiday season을 busy period로 바꿔 표현했다."},{"q":"Look at the graphic. Which vendor will the man most likely recommend?","choices":["AutoMove","StackPro","LiftLogic","Robonet"],"answer":2,"type":"시각 자료 연계","explanation":"설치 6개월 초과(StackPro 9개월, Robonet 8개월)는 제외되고, 단가가 가장 낮은 AutoMove는 유지보수가 1년뿐이라 뺐다. 남은 곳은 설치 5개월, 보증 3년인 LiftLogic이다."},{"q":"What does the man ask the woman for?","choices":["A report on the demonstrations","A revised price quote","Contact information for current customers","A copy of the warranty"],"answer":2,"type":"요청·제안","explanation":"남자가 \"Could you get me the reference contacts they mentioned?\"라며 기존 고객과 이야기하고 싶다고 했으므로 현재 고객들의 연락처를 요청했다. existing clients를 current customers로 바꿔 표현했다."}],"translation":"W: 시연을 다 봤으니 물류센터 로봇 업체 두어 곳은 제외할 수 있을 것 같아요.\nM: 동의해요. 솔직히 설치에 6개월 넘게 걸리는 곳은 고려 대상이 아니에요. 연말 성수기 내내 현장이 어수선하면 안 되니까요.\nW: 그러면 두 곳이 빠지네요. 그리고 단가가 가장 낮은 곳도 망설여져요. 유지보수 계약이 첫해만 적용되거든요.\nM: 맞아요, 그 이후 수리비가 절감액을 쉽게 다 까먹을 수 있죠. 그럼 선택지가 하나로 줄었네요.\nW: 가격은 더 높지만 3년 보증과 설치 기간을 보면 가장 안전한 선택이에요.\nM: 화요일에 이사회에 보고할게요. 업체가 말한 추천 고객 연락처를 받아 줄래요? 기존 고객 두어 곳과 먼저 이야기해 보고 싶어요.","part":3},{"id":"p3-095","level":5,"topic":"호텔 체인과 항공사 마일리지 제휴 협상","speakers":{"W":"female","M":"male","W2":"female"},"script":[{"s":"W","t":"Thanks for joining the call, Hiroshi. As we mentioned, Crestline Hotels is interested in letting our loyalty members earn miles with your airline."},{"s":"M","t":"We're very interested as well. The main sticking point for us is the rate. Your proposal offers one mile per dollar spent, and our other hotel partners offer two."},{"s":"W2","t":"I understand, but most of those partners are budget chains. Our average room rate is nearly double theirs."},{"s":"M","t":"That's a fair point."},{"s":"W","t":"What if we kept the rate at one mile per dollar, but added a bonus of five hundred miles for stays of three nights or more?"},{"s":"M","t":"That could work. Our frequent flyers do tend to take longer trips. I'd need to run the numbers with our finance team, though."},{"s":"W2","t":"Of course. We can send you our booking data from last year to help with that."},{"s":"M","t":"That would be helpful. Let's plan to talk again next Thursday."}],"graphic":null,"questions":[{"q":"What are the speakers mainly discussing?","choices":["The terms of a partnership","Changes to room rates","A hotel booking error","A new flight route"],"answer":0,"type":"주제·목적","explanation":"호텔 회원이 항공 마일리지를 적립하는 제휴를 두고 적립률과 보너스를 협상하고 있으므로 제휴 조건이 주제다."},{"q":"Why does the second woman mention budget chains?","choices":["To justify a lower earning rate","To complain about competitors' prices","To suggest new partners","To explain a drop in bookings"],"answer":0,"type":"세부 사항","explanation":"남자가 다른 호텔은 달러당 2마일을 준다고 하자 두 번째 여자가 그 호텔들은 저가 체인이고 자사 객실 요금은 거의 두 배라고 했다. 자사가 더 낮은 적립률을 제시하는 것이 타당하다는 근거를 댄 것이다."},{"q":"What does the man mean when he says, \"That's a fair point\"?","choices":["He believes the rate should be doubled.","He accepts the woman's reasoning.","He wants to end the negotiation.","He thinks the price is fair."],"answer":1,"type":"의도 파악","explanation":"객실 요금이 두 배라서 1마일만 줘도 된다는 설명에 대한 답이므로 상대의 논리를 인정한다는 뜻이다. 적립률을 두 배로 올려야 한다는 의미가 아니다."}],"translation":"W: 통화에 참여해 주셔서 감사합니다, 히로시. 말씀드렸듯이 크레스트라인 호텔은 저희 회원들이 귀사 항공사 마일리지를 적립할 수 있게 하고 싶어요.\nM: 저희도 관심이 많습니다. 저희 쪽에서 걸리는 건 적립률이에요. 제안서에는 1달러당 1마일인데, 다른 호텔 제휴사들은 2마일을 줍니다.\nW2: 이해합니다만, 그 제휴사들은 대부분 저가 체인이에요. 저희 평균 객실 요금은 그들의 거의 두 배입니다.\nM: 일리 있는 말씀이네요.\nW: 적립률은 달러당 1마일로 유지하되, 3박 이상 투숙하면 500마일 보너스를 더하면 어떨까요?\nM: 괜찮을 수 있겠네요. 저희 상용 고객들은 여행을 길게 하는 편이거든요. 다만 재무팀과 수치를 따져 봐야 해요.\nW2: 물론이죠. 도움이 되도록 작년 예약 데이터를 보내 드릴게요.\nM: 그러면 도움이 되겠네요. 다음 주 목요일에 다시 이야기하죠.","part":3},{"id":"p3-096","level":5,"topic":"공연장 좌석 재배치와 소방 규정","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Ms. Dubois, I've reviewed your plan to add more seating for the jazz festival, and I'm afraid there's an issue with the fire code."},{"s":"W","t":"Oh? We only wanted to add seats in one section, in front of the stage."},{"s":"M","t":"Yes, but the aisle in that section would end up narrower than the legal minimum. Emergency exits have to stay clear at all times."},{"s":"W","t":"What if we added the seats to a different section instead? We really need to increase capacity. Ticket sales have been far stronger than we expected."},{"s":"M","t":"The balcony can't take any more. But the section with the widest aisles could absorb the additional seats without violating the code."},{"s":"W","t":"Then we'll do that. Will you need to inspect the hall again?"},{"s":"M","t":"Yes. Submit a revised floor plan, and I'll schedule a final inspection before opening night."}],"graphic":{"title":"Harbor Concert Hall — Seating Sections","rows":[["Section","Current Seats","Aisle Width"],["Floor Front","220","1.1 m"],["Floor Rear","260","1.8 m"],["Side Terraces","140","1.4 m"],["Balcony","180","1.2 m"]]},"questions":[{"q":"Who most likely is the man?","choices":["A stage designer","A ticket agent","A concert promoter","A safety inspector"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"남자가 좌석 계획을 소방 규정(fire code) 기준으로 검토하고 최종 점검 일정을 잡겠다고 하므로 안전 점검관이다."},{"q":"Why does the woman want to add seats?","choices":["Some seats were damaged.","A sponsor asked for more seats.","Demand for tickets is high.","A larger stage is being built."],"answer":2,"type":"세부 사항","explanation":"여자가 \"Ticket sales have been far stronger than we expected\"라고 했으므로 표 수요가 많아서 좌석을 늘리려 한다."},{"q":"Look at the graphic. Where will the additional seats most likely be placed?","choices":["Floor Front","Floor Rear","Side Terraces","Balcony"],"answer":1,"type":"시각 자료 연계","explanation":"남자가 통로가 가장 넓은 구역이면 규정 위반 없이 좌석을 추가할 수 있다고 했고 여자가 그렇게 하겠다고 했다. 표에서 통로 폭이 가장 넓은 곳은 1.8m인 Floor Rear다. 무대 앞(Floor Front)은 원래 계획이었지만 통로가 좁아 불가하다."}],"translation":"M: 뒤부아 씨, 재즈 페스티벌 좌석 증설 계획을 검토했는데, 소방 규정에 문제가 있습니다.\nW: 네? 저희는 무대 앞 한 구역에만 좌석을 추가하려고 했는데요.\nM: 네, 하지만 그렇게 하면 그 구역 통로가 법정 최소 폭보다 좁아져요. 비상구는 늘 막힘없이 유지돼야 합니다.\nW: 대신 다른 구역에 좌석을 추가하면 어떨까요? 수용 인원을 꼭 늘려야 해요. 표가 예상보다 훨씬 많이 팔렸거든요.\nM: 발코니는 더 이상 안 됩니다. 하지만 통로가 가장 넓은 구역이면 규정을 어기지 않고 추가 좌석을 둘 수 있어요.\nW: 그럼 그렇게 할게요. 공연장을 다시 점검하셔야 하나요?\nM: 네. 수정한 평면도를 제출하시면 개막 공연 전에 최종 점검 일정을 잡겠습니다.","part":3},{"id":"p3-097","level":5,"topic":"식품 제조사 자발적 리콜 대응","speakers":{"M":"male","W":"female","W2":"female"},"script":[{"s":"M","t":"Thanks for coming on such short notice. Quality control found that one batch of our granola bars may contain traces of peanuts that aren't listed on the label."},{"s":"W","t":"How many units are we talking about?"},{"s":"M","t":"Roughly eight thousand boxes, all shipped to stores in the Northeast last week."},{"s":"W2","t":"Has anyone reported getting sick?"},{"s":"M","t":"Not so far. But we can't take any chances with allergens. I'd like to issue a voluntary recall today."},{"s":"W","t":"I'll contact our distributors and ask them to pull the product from the shelves immediately."},{"s":"W2","t":"And I'll draft a public statement. It should explain which batch numbers are affected and how customers can get a refund."},{"s":"M","t":"Good. Please have it ready for legal review by three o'clock."}],"graphic":null,"questions":[{"q":"What problem did quality control find?","choices":["A batch of products was underweight.","Some boxes were damaged in shipping.","An ingredient was missing from a label.","A machine produced bars of the wrong size."],"answer":2,"type":"주제·목적","explanation":"남자가 그래놀라 바에 \"traces of peanuts that aren't listed on the label\"이 들어 있을 수 있다고 했으므로 라벨에 성분이 빠진 문제다."},{"q":"According to the man, why will the company issue a recall?","choices":["Because many customers have complained","To comply with a court order","Because a store has requested it","To avoid any risk to customers"],"answer":3,"type":"세부 사항","explanation":"아직 아픈 사람은 없지만 남자가 \"we can't take any chances with allergens\"라고 했으므로 알레르기 위험을 조금도 감수하지 않으려고 자발적으로 리콜한다. 신고된 사례는 아직 없다."},{"q":"What will the second woman do?","choices":["Issue customer refunds","Call some distributors","Write an announcement","Test more samples"],"answer":2,"type":"다음 할 일","explanation":"두 번째 여자가 \"I'll draft a public statement\"라고 했으므로 대외 발표문을 작성한다. 유통업체에 연락하는 것은 첫 번째 여자의 일이다."}],"translation":"M: 급하게 모였는데 와 주셔서 감사합니다. 품질관리팀이 우리 그래놀라 바 한 묶음에 라벨에 표시되지 않은 땅콩 성분이 소량 들어 있을 수 있다는 걸 발견했어요.\nW: 수량이 얼마나 되나요?\nM: 대략 8천 상자이고, 전부 지난주에 북동부 지역 매장으로 출고됐어요.\nW2: 아프다고 신고한 사람이 있나요?\nM: 아직은 없어요. 하지만 알레르기 유발 성분은 조금도 위험을 감수할 수 없어요. 오늘 자발적 리콜을 발표하고 싶어요.\nW: 제가 유통업체에 연락해서 즉시 매대에서 제품을 빼 달라고 할게요.\nW2: 저는 대외 발표문 초안을 쓸게요. 어떤 제조 번호가 해당되는지, 소비자가 어떻게 환불받을 수 있는지 설명해야겠죠.\nM: 좋아요. 3시까지 법무 검토를 받을 수 있게 준비해 주세요.","part":3},{"id":"p3-098","level":5,"topic":"재생에너지 전력 구매 계약 선택","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Andrew, the energy consultant sent over four renewable power contracts for our factories. Headquarters wants us to pick one by the end of the month."},{"s":"M","t":"Our goal is to cover at least seventy percent of our electricity with renewables, right?"},{"s":"W","t":"Right. Two of the contracts get us there. The cheaper of those two requires a fifteen-year commitment, though."},{"s":"M","t":"That's a long time. Energy prices could fall considerably in that period."},{"s":"W","t":"Exactly my concern. The other one costs slightly more per unit, but it's only a ten-year term, and we can renegotiate the price after five years."},{"s":"M","t":"Given how quickly the technology is changing, flexibility is worth paying for."},{"s":"W","t":"I'll let the consultant know, then. Should I copy the finance director?"},{"s":"M","t":"Yes, and ask her to confirm that the extra cost fits within next year's budget."}],"graphic":{"title":"Renewable Power Contract Options","rows":[["Provider","Renewable Share","Term","Price per kWh"],["SunGrid","50%","5 years","$0.09"],["WindPath","75%","15 years","$0.10"],["TerraVolt","80%","10 years","$0.11"],["Horizon Power","60%","12 years","$0.08"]]},"questions":[{"q":"What must the speakers do by the end of the month?","choices":["Choose an energy contract","Hire a new consultant","Submit next year's budget","Reduce factory output"],"answer":0,"type":"세부 사항","explanation":"여자가 \"Headquarters wants us to pick one by the end of the month\"라고 했으므로 월말까지 전력 계약을 골라야 한다."},{"q":"What does the man imply when he says, \"flexibility is worth paying for\"?","choices":["He thinks the consultant charges too much.","He supports the more expensive option.","He prefers to buy new equipment.","He wants to delay the decision."],"answer":1,"type":"의도 파악","explanation":"단가는 조금 더 비싸지만 10년 계약에 5년 뒤 재협상이 가능한 안을 두고 한 말이므로, 유연성을 위해 더 비싼 안을 택하자는 뜻이다."},{"q":"Look at the graphic. Which provider will the speakers most likely choose?","choices":["SunGrid","WindPath","TerraVolt","Horizon Power"],"answer":2,"type":"시각 자료 연계","explanation":"재생에너지 70% 이상인 곳은 WindPath(75%)와 TerraVolt(80%)다. 더 싼 WindPath는 15년 약정이라 우려했고, 단가가 조금 더 높은 10년 계약을 택하기로 했으므로 TerraVolt다."}],"translation":"W: 앤드루, 에너지 컨설턴트가 우리 공장용 재생에너지 전력 계약안을 네 가지 보내왔어요. 본사에서는 월말까지 하나를 고르라고 해요.\nM: 우리 목표가 전력의 최소 70퍼센트를 재생에너지로 충당하는 거였죠?\nW: 맞아요. 그 기준을 맞추는 계약이 두 개예요. 그런데 그중 더 싼 쪽은 15년 약정이 필요해요.\nM: 긴 기간이네요. 그동안 에너지 가격이 상당히 내려갈 수도 있어요.\nW: 제가 걱정하는 게 바로 그거예요. 다른 하나는 단가가 약간 더 높지만 10년 계약이고, 5년 뒤에 가격을 재협상할 수 있어요.\nM: 기술이 얼마나 빨리 바뀌는지 생각하면 유연성은 돈을 더 낼 만한 가치가 있어요.\nW: 그럼 컨설턴트에게 알릴게요. 재무 이사님도 참조로 넣을까요?\nM: 네, 그리고 추가 비용이 내년 예산 안에 들어가는지 확인해 달라고 해 주세요.","part":3},{"id":"p3-099","level":5,"topic":"동남아 시장 진출 현지 유통 파트너 선정","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Elena, I read your report on potential distributors for our entry into the Vietnamese market. You seem to favor Linh Phat Trading."},{"s":"W","t":"I do. They're not the largest distributor, but they already carry two brands of kitchen appliances similar to ours, so their sales staff know the category."},{"s":"M","t":"Wouldn't that be a conflict of interest? They'd be selling our competitors' products alongside ours."},{"s":"W","t":"I raised that with them directly. Their director pointed out that neither of those brands has a high-end line, which is exactly where we'd be positioned."},{"s":"M","t":"Hmm. So we wouldn't be competing for the same customers."},{"s":"W","t":"Right. And they have warehouses in both Hanoi and Ho Chi Minh City, which the larger firm doesn't."},{"s":"M","t":"I'm persuaded. Before we commit, though, I'd like to meet their director in person. Can you see if she's available the week after next?"}],"graphic":null,"questions":[{"q":"What is the woman's report about?","choices":["Possible business partners in a new market","A competitor's new product line","Customer complaints about appliances","The cost of building a warehouse"],"answer":0,"type":"주제·목적","explanation":"남자가 \"your report on potential distributors for our entry into the Vietnamese market\"라고 했으므로 새 시장의 잠재적 유통 파트너에 관한 보고서다."},{"q":"Why does the man say, \"So we wouldn't be competing for the same customers\"?","choices":["To suggest targeting a different market","To question the woman's research","To explain why sales have fallen","To show that his concern has been addressed"],"answer":3,"type":"의도 파악","explanation":"이해 상충을 걱정했는데 경쟁 브랜드들에 고급 라인이 없어 자사와 겹치지 않는다는 설명을 듣고 한 말이므로, 자신의 우려가 해소됐음을 나타낸다. 이어서 \"I'm persuaded\"라고 한 것도 같은 맥락이다."},{"q":"What does the man ask the woman to do?","choices":["Draft a contract","Visit a warehouse","Revise her report","Arrange a meeting"],"answer":3,"type":"요청·제안","explanation":"남자가 상대 이사를 직접 만나고 싶다며 \"Can you see if she's available the week after next?\"라고 했으므로 만남 일정을 잡아 달라는 요청이다. 계약은 그 이후의 일이다."}],"translation":"M: 엘레나, 베트남 시장 진출을 위한 유통업체 후보 보고서를 읽었어요. 린팟 무역을 선호하는 것 같더군요.\nW: 네. 가장 큰 유통업체는 아니지만, 우리와 비슷한 주방 가전 브랜드를 이미 두 개 취급하고 있어서 영업 직원들이 이 품목을 잘 알아요.\nM: 그건 이해 상충 아닌가요? 우리 제품 옆에서 경쟁사 제품을 파는 거잖아요.\nW: 그 문제를 직접 물어봤어요. 그쪽 이사가 두 브랜드 모두 고급 라인이 없다고 짚더라고요. 바로 우리가 자리 잡으려는 곳이죠.\nM: 음. 그럼 같은 고객을 두고 경쟁하지는 않겠네요.\nW: 맞아요. 그리고 하노이와 호찌민 두 곳 모두에 창고가 있는데, 더 큰 업체는 그렇지 않아요.\nM: 설득됐어요. 다만 확정하기 전에 그쪽 이사를 직접 만나 보고 싶어요. 다다음 주에 시간이 되는지 알아봐 줄래요?","part":3},{"id":"p3-100","level":5,"topic":"해외 미술관 소장품 대여 보험","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Mr. Albright, I've heard back from the insurers about the paintings we're borrowing from the Lisbon museum for our spring exhibition."},{"s":"M","t":"Good. The lending agreement says the coverage has to include both transit and the full exhibition period, correct?"},{"s":"W","t":"Yes. And the museum also insists that the insurer have experience handling fine art. Two of the four quotes don't meet that requirement."},{"s":"M","t":"What about the other two?"},{"s":"W","t":"Both qualify. One has a lower premium, but its deductible is much higher. If a painting were damaged, we'd have to pay a large amount ourselves before the policy covered anything."},{"s":"M","t":"With works this valuable, I'd rather keep our own exposure as small as possible, even if the premium is higher."},{"s":"W","t":"I agree. I'll send the policy to the museum's registrar for approval before we sign."}],"graphic":{"title":"Insurance Quotes — Lisbon Loan","rows":[["Insurer","Fine Art Experience","Premium","Deductible"],["Atlas Mutual","No","$18,000","$5,000"],["Veritas Art Cover","Yes","$26,000","$10,000"],["Meridian Group","No","$21,000","$15,000"],["Castellan Insurance","Yes","$22,500","$50,000"]]},"questions":[{"q":"What are the speakers preparing for?","choices":["The opening of a museum in Lisbon","The restoration of damaged art","An exhibition of borrowed artwork","The sale of some paintings"],"answer":2,"type":"주제·목적","explanation":"여자가 \"the paintings we're borrowing from the Lisbon museum for our spring exhibition\"이라고 했으므로 대여 작품 전시를 준비하고 있다."},{"q":"Look at the graphic. Which insurer will the speakers most likely choose?","choices":["Atlas Mutual","Veritas Art Cover","Meridian Group","Castellan Insurance"],"answer":1,"type":"시각 자료 연계","explanation":"미술품 경험이 있는 곳은 Veritas와 Castellan이다. Castellan은 보험료가 더 낮지만 자기부담금이 5만 달러로 높고, 남자가 보험료가 높더라도 자체 부담을 최소화하겠다고 했으므로 자기부담금이 1만 달러인 Veritas Art Cover다."},{"q":"What will the woman do before signing?","choices":["Get approval from the lending museum","Inspect the paintings","Request more quotes","Negotiate a lower premium"],"answer":0,"type":"다음 할 일","explanation":"여자가 \"I'll send the policy to the museum's registrar for approval before we sign\"이라고 했으므로 대여 미술관의 승인을 받는다. registrar는 소장품 관리 담당자다."}],"translation":"W: 올브라이트 씨, 봄 전시를 위해 리스본 미술관에서 빌리는 그림들의 보험 건으로 보험사들에게서 답을 받았어요.\nM: 좋아요. 대여 계약서에 따르면 보장 범위에 운송과 전시 기간 전체가 모두 포함돼야 하죠?\nW: 네. 그리고 미술관 측은 보험사가 미술품을 다뤄 본 경험이 있어야 한다고 강조해요. 견적 네 개 중 두 개는 그 조건을 충족하지 못해요.\nM: 나머지 두 개는요?\nW: 둘 다 조건에 맞아요. 한 곳은 보험료가 더 낮지만 자기부담금이 훨씬 높아요. 그림이 손상되면 보험이 보장하기 전에 우리가 큰 금액을 먼저 내야 해요.\nM: 이렇게 귀중한 작품이면 보험료가 더 높더라도 우리 쪽 부담은 최대한 작게 하고 싶어요.\nW: 동감이에요. 서명하기 전에 보험 증권을 미술관 소장품 담당자에게 보내 승인받을게요.","part":3},{"id":"p3-101","level":1,"topic":"회의용 점심 도시락 주문","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, this is Karen from Delson Marketing. I'd like to order lunch boxes for a meeting tomorrow."},{"s":"M","t":"Sure. How many do you need?"},{"s":"W","t":"Twelve, please. And can two of them be vegetarian?"},{"s":"M","t":"No problem. What time should we deliver them?"},{"s":"W","t":"At noon, please. Our office is on the fifth floor."},{"s":"M","t":"Great. I'll just need your phone number to confirm the order."}],"graphic":null,"questions":[{"q":"Why is the woman calling?","choices":["To order some food","To book a meeting room","To ask about a job","To cancel a delivery"],"answer":0,"type":"주제·목적","explanation":"여자가 \"I'd like to order lunch boxes\"라고 했으므로 음식을 주문하려고 전화했다. 회의(meeting)는 도시락이 필요한 이유일 뿐 회의실 예약이 아니다."},{"q":"How many vegetarian meals does the woman want?","choices":["One","Two","Five","Twelve"],"answer":1,"type":"세부 사항","explanation":"\"can two of them be vegetarian?\"이라고 했으므로 채식 도시락은 2개다. 12는 전체 도시락 수, 5는 사무실 층수다."},{"q":"What does the man ask for?","choices":["A phone number","An address","A credit card","A meeting time"],"answer":0,"type":"요청·제안","explanation":"남자가 마지막에 \"I'll just need your phone number\"라고 했다. 배달 시간(noon)은 이미 여자가 말했다."}],"translation":"W: 안녕하세요, 델슨 마케팅의 캐런입니다. 내일 회의에 쓸 도시락을 주문하고 싶어요.\nM: 네. 몇 개 필요하세요?\nW: 12개요. 그중 두 개는 채식으로 해 주실 수 있나요?\nM: 그럼요. 몇 시에 배달해 드릴까요?\nW: 정오에 부탁드려요. 저희 사무실은 5층이에요.\nM: 좋습니다. 주문 확인을 위해 전화번호만 알려 주세요.","part":3},{"id":"p3-102","level":1,"topic":"분실한 사원증 재발급","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Excuse me. I lost my employee ID card yesterday. Can I get a new one here?"},{"s":"W","t":"Yes, you can. Please fill out this form first."},{"s":"M","t":"OK. Is there a fee?"},{"s":"W","t":"Yes, it's ten dollars. It will be taken from your next paycheck."},{"s":"M","t":"That's fine. When can I get the new card?"},{"s":"W","t":"Tomorrow morning. Until then, you can use this visitor pass."}],"graphic":null,"questions":[{"q":"What is the man's problem?","choices":["He missed a meeting.","He forgot a password.","He broke his phone.","He lost his ID card."],"answer":3,"type":"주제·목적","explanation":"남자가 \"I lost my employee ID card yesterday\"라고 했으므로 사원증을 잃어버린 것이 문제다."},{"q":"How will the man pay the fee?","choices":["From his paycheck","By bank transfer","In cash","By credit card"],"answer":0,"type":"세부 사항","explanation":"여자가 \"It will be taken from your next paycheck\"라고 했으므로 다음 월급에서 빠진다. 현금·카드 결제는 언급되지 않았다."},{"q":"What does the woman give the man?","choices":["A visitor pass","A receipt","A parking ticket","A new ID card"],"answer":0,"type":"세부 사항","explanation":"\"you can use this visitor pass\"라고 하며 방문증을 준다. 새 사원증은 내일 아침에 받으므로 지금 받는 것이 아니다."}],"translation":"M: 실례합니다. 어제 사원증을 잃어버렸어요. 여기서 새로 받을 수 있나요?\nW: 네, 가능해요. 먼저 이 양식을 작성해 주세요.\nM: 알겠습니다. 수수료가 있나요?\nW: 네, 10달러예요. 다음 월급에서 빠질 거예요.\nM: 괜찮아요. 새 카드는 언제 받을 수 있나요?\nW: 내일 아침이요. 그때까지는 이 방문증을 사용하시면 돼요.","part":3},{"id":"p3-103","level":1,"topic":"새 커피머신 사용법","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Daniel, do you know how to use the new coffee machine?"},{"s":"M","t":"Yes. First, put your cup here. Then press the green button."},{"s":"W","t":"What about milk? I like a latte."},{"s":"M","t":"Press the blue button after the green one. The milk is in the small fridge next to it."},{"s":"W","t":"Oh, I see. Thanks. It's much faster than the old one."},{"s":"M","t":"I know. I'll put a short guide on the wall for everyone."}],"graphic":null,"questions":[{"q":"Where most likely are the speakers?","choices":["In an electronics store","In a hotel lobby","In a café","In an office kitchen"],"answer":3,"type":"화자 정보(직업·장소)","explanation":"동료끼리 \"the new coffee machine\"과 옆의 작은 냉장고 이야기를 하고, 모두를 위해 벽에 안내문을 붙이겠다고 하므로 사무실 탕비실로 볼 수 있다."},{"q":"Where is the milk?","choices":["On the counter","In a cabinet","In a small refrigerator","Next to the sink"],"answer":2,"type":"세부 사항","explanation":"\"The milk is in the small fridge next to it\"이라고 했다. fridge = refrigerator."},{"q":"What will the man do?","choices":["Post some instructions","Fix the machine","Make a latte for the woman","Buy more milk"],"answer":0,"type":"다음 할 일","explanation":"\"I'll put a short guide on the wall\"이라고 했으므로 사용 안내문을 붙일 것이다. guide → instructions로 바꿔 표현했다."}],"translation":"W: 대니얼, 새 커피머신 사용법 알아요?\nM: 네. 먼저 컵을 여기 놓으세요. 그다음 초록 버튼을 누르면 돼요.\nW: 우유는요? 저는 라테를 좋아하거든요.\nM: 초록 버튼 다음에 파란 버튼을 누르세요. 우유는 옆에 있는 작은 냉장고에 있어요.\nW: 아, 알겠어요. 고마워요. 예전 것보다 훨씬 빠르네요.\nM: 그러게요. 모두 볼 수 있게 벽에 짧은 안내문을 붙여 둘게요.","part":3},{"id":"p3-104","level":1,"topic":"우체국에서 해외 소포 발송","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hello. I'd like to send this box to Canada."},{"s":"W","t":"Sure. Let me weigh it. It's a little under two kilograms."},{"s":"M","t":"OK. I don't need it to arrive fast. What's the cheapest way?"},{"s":"W","t":"Standard mail is the cheapest. It takes about two weeks."},{"s":"M","t":"That's fine. I'll use that."},{"s":"W","t":"All right. Please write the address on this label."}],"graphic":{"title":"Mailing Rates to Canada (up to 2 kg)","rows":[["Service","Delivery Time","Price"],["Express","2-3 days","$48"],["Priority","5-7 days","$35"],["Standard","About 2 weeks","$22"],["Economy Plus","About 10 days","$29"]]},"questions":[{"q":"What does the man want to do?","choices":["Pick up a package","Buy some stamps","Change an address","Send a box overseas"],"answer":3,"type":"주제·목적","explanation":"\"I'd like to send this box to Canada\"라고 했으므로 해외로 상자를 보내려 한다."},{"q":"Look at the graphic. How much will the man pay?","choices":["$48","$35","$29","$22"],"answer":3,"type":"시각 자료 연계","explanation":"남자는 가장 싼 방법을 원했고 여자가 Standard를 추천했다. 표에서 Standard는 22달러다."},{"q":"What does the woman ask the man to do?","choices":["Show an ID card","Pay in cash","Come back later","Write an address"],"answer":3,"type":"요청·제안","explanation":"\"Please write the address on this label\"이라고 했으므로 주소를 쓰라고 요청했다."}],"translation":"M: 안녕하세요. 이 상자를 캐나다로 보내고 싶어요.\nW: 네. 무게를 재 볼게요. 2킬로그램이 조금 안 되네요.\nM: 네. 빨리 도착하지 않아도 돼요. 가장 싼 방법이 뭔가요?\nW: 일반 우편이 가장 싸요. 2주 정도 걸려요.\nM: 괜찮아요. 그걸로 할게요.\nW: 알겠습니다. 이 라벨에 주소를 써 주세요.","part":3},{"id":"p3-105","level":1,"topic":"지하철 지연으로 회의 지각","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, Lisa. It's Ken. My subway train stopped between stations, so I'll be late."},{"s":"W","t":"Oh, no. Our meeting with the client starts at ten."},{"s":"M","t":"I know. I think I'll be there around ten thirty."},{"s":"W","t":"OK. I'll start the meeting and explain the new price list first."},{"s":"M","t":"Thanks. The sales slides are in the shared folder."},{"s":"W","t":"Got it. I'll open them on the big screen."}],"graphic":null,"questions":[{"q":"Why will the man be late?","choices":["His train stopped.","His car broke down.","He went to the wrong office.","He missed his bus."],"answer":0,"type":"세부 사항","explanation":"\"My subway train stopped between stations\"라고 했으므로 지하철이 멈춰서 늦는다."},{"q":"What time does the meeting start?","choices":["At 9:30","At 10:00","At 10:30","At 11:00"],"answer":1,"type":"세부 사항","explanation":"여자가 \"starts at ten\"이라고 했다. 10시 30분은 남자가 도착할 것으로 예상하는 시간이다."},{"q":"What will the woman do first at the meeting?","choices":["Introduce the man","Hand out a contract","Show a video","Explain a price list"],"answer":3,"type":"다음 할 일","explanation":"\"I'll start the meeting and explain the new price list first\"라고 했다."}],"translation":"M: 안녕하세요, 리사. 켄이에요. 지하철이 역 사이에서 멈춰서 늦을 것 같아요.\nW: 이런. 고객과의 회의가 10시에 시작하잖아요.\nM: 알아요. 10시 30분쯤 도착할 것 같아요.\nW: 알겠어요. 제가 회의를 시작해서 새 가격표부터 설명할게요.\nM: 고마워요. 영업 슬라이드는 공유 폴더에 있어요.\nW: 알겠어요. 큰 화면에 띄울게요.","part":3},{"id":"p3-106","level":1,"topic":"서점에 책 주문","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hello. I'm looking for a book called Small Business Basics, but I can't find it."},{"s":"M","t":"Let me check. Hmm, we don't have any copies right now."},{"s":"W","t":"Oh. Can you order one for me?"},{"s":"M","t":"Yes. It will arrive in three days. Can I have your name?"},{"s":"W","t":"It's Maria Lopez. Should I pay now?"},{"s":"M","t":"No, you can pay when you pick it up. We'll send you a text message when it comes in."}],"graphic":null,"questions":[{"q":"Where does the conversation most likely take place?","choices":["At a bookstore","At a post office","At a library","At a printing shop"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"책을 찾고, 재고가 없어 주문하고, 찾아갈 때 돈을 낸다고 하므로 서점이다. 도서관은 돈을 내지 않는다."},{"q":"When will the item arrive?","choices":["Next month","In three days","In two days","Tomorrow"],"answer":1,"type":"세부 사항","explanation":"\"It will arrive in three days\"라고 했다."},{"q":"How will the woman be contacted?","choices":["By text message","By letter","By phone call","By e-mail"],"answer":0,"type":"세부 사항","explanation":"\"We'll send you a text message\"라고 했으므로 문자 메시지로 연락받는다."}],"translation":"W: 안녕하세요. '소규모 사업 기초'라는 책을 찾는데 못 찾겠어요.\nM: 확인해 볼게요. 음, 지금은 재고가 하나도 없네요.\nW: 아. 한 권 주문해 주실 수 있나요?\nM: 네. 3일 뒤에 도착할 거예요. 성함을 알려 주시겠어요?\nW: 마리아 로페즈예요. 지금 돈을 내야 하나요?\nM: 아니요, 찾아가실 때 내시면 돼요. 책이 들어오면 문자 메시지를 보내 드릴게요.","part":3},{"id":"p3-107","level":1,"topic":"사무실 냉장고 정리","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Jenny, the office refrigerator is full again. There's no room for my lunch."},{"s":"W","t":"I know. A lot of the food in there is very old."},{"s":"M","t":"Should we clean it out?"},{"s":"W","t":"Yes, but let's tell everyone first. I'll send an e-mail today."},{"s":"M","t":"Good idea. We can clean it on Friday afternoon."},{"s":"W","t":"OK. Anything without a name on it will be thrown away."}],"graphic":null,"questions":[{"q":"What problem does the man mention?","choices":["The refrigerator is broken.","The refrigerator is full.","The kitchen is closed.","His lunch is missing."],"answer":1,"type":"주제·목적","explanation":"\"the office refrigerator is full again. There's no room for my lunch\"라고 했다. 점심이 없어진 것이 아니라 넣을 자리가 없는 것이다."},{"q":"What will the woman do today?","choices":["Clean the kitchen","Order lunch","Buy a new refrigerator","Send an e-mail"],"answer":3,"type":"다음 할 일","explanation":"\"I'll send an e-mail today\"라고 했다. 청소는 금요일 오후에 한다."},{"q":"What will happen to food without a name?","choices":["It will be shared.","It will be returned.","It will be thrown away.","It will be moved to a cabinet."],"answer":2,"type":"세부 사항","explanation":"\"Anything without a name on it will be thrown away\"라고 했다."}],"translation":"M: 제니, 사무실 냉장고가 또 꽉 찼어요. 제 점심 넣을 자리가 없어요.\nW: 알아요. 안에 있는 음식이 오래된 게 많아요.\nM: 우리가 싹 정리할까요?\nW: 네, 그런데 먼저 모두에게 알려요. 제가 오늘 이메일을 보낼게요.\nM: 좋은 생각이에요. 금요일 오후에 정리하면 되겠네요.\nW: 네. 이름이 안 적힌 건 모두 버릴 거예요.","part":3},{"id":"p3-108","level":1,"topic":"호텔 프런트 조식 시간 문의","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Good evening. I'm in room 512. What time is breakfast tomorrow?"},{"s":"W","t":"Tomorrow is Saturday, so please look at this schedule. Breakfast is in the garden restaurant."},{"s":"M","t":"I have a meeting at 8:30, so I need to eat early."},{"s":"W","t":"Then you can come when it opens."},{"s":"M","t":"Great. Could I also get a wake-up call at six?"},{"s":"W","t":"Of course. I'll set that up for you."}],"graphic":{"title":"Garden Restaurant — Breakfast Hours","rows":[["Day","Hours"],["Monday - Friday","6:30 - 9:30"],["Saturday","7:00 - 10:00"],["Sunday","7:30 - 10:30"]]},"questions":[{"q":"Who most likely is the woman?","choices":["A hotel receptionist","A tour guide","A taxi driver","A restaurant chef"],"answer":0,"type":"화자 정보(직업·장소)","explanation":"남자가 객실 번호(room 512)를 말하며 조식 시간과 모닝콜을 요청하므로 여자는 호텔 프런트 직원이다."},{"q":"Look at the graphic. What time will the man most likely go to breakfast?","choices":["At 6:30","At 7:00","At 7:30","At 9:30"],"answer":1,"type":"시각 자료 연계","explanation":"내일은 토요일이고 남자는 문을 여는 시간에 가기로 했다. 표에서 토요일은 7시에 연다. 6시 30분은 평일 시작 시간이다."},{"q":"What does the man ask for?","choices":["A taxi","A wake-up call","A late checkout","A room change"],"answer":1,"type":"요청·제안","explanation":"\"Could I also get a wake-up call at six?\"라고 모닝콜을 요청했다."}],"translation":"M: 안녕하세요. 512호에 묵고 있어요. 내일 아침 식사는 몇 시인가요?\nW: 내일은 토요일이니 이 시간표를 봐 주세요. 아침 식사는 가든 레스토랑에서 해요.\nM: 8시 30분에 회의가 있어서 일찍 먹어야 해요.\nW: 그럼 문 여는 시간에 오시면 돼요.\nM: 좋아요. 6시에 모닝콜도 해 주실 수 있나요?\nW: 물론이죠. 설정해 드릴게요.","part":3},{"id":"p3-109","level":2,"topic":"회사 체육대회 팀 배정","speakers":{"M":"male","W":"female","M2":"male"},"script":[{"s":"W","t":"Hi, Alex. Hi, Ben. Have you both signed up for the company sports day next Saturday?"},{"s":"M","t":"I have. I put my name down for the soccer team."},{"s":"M2","t":"I wanted to join soccer too, but the sign-up sheet said it's already full."},{"s":"W","t":"That's right, Ben. We only have room for eleven players. But the volleyball team still needs two more people."},{"s":"M2","t":"Volleyball sounds fun. I'll join that one."},{"s":"W","t":"Great. I'll add your name. Oh, and everyone gets a free T-shirt, so please tell me your size by Wednesday."}],"graphic":null,"questions":[{"q":"What event are the speakers discussing?","choices":["A charity run","A training workshop","A soccer match on TV","A company sports day"],"answer":3,"type":"주제·목적","explanation":"여자가 \"the company sports day next Saturday\"를 언급하며 팀 신청 이야기를 하므로 회사 체육대회에 관한 대화다."},{"q":"Why can't Ben join the soccer team?","choices":["He is injured.","He will be away.","He signed up too late for the event.","The team is full."],"answer":3,"type":"세부 사항","explanation":"벤(M2)이 \"the sign-up sheet said it's already full\"이라고 했다. 행사 자체 신청이 늦은 것이 아니라 축구 팀 정원이 찬 것이다."},{"q":"What does the woman ask the men to do by Wednesday?","choices":["Pay a fee","Bring some equipment","Give their T-shirt size","Choose a team captain"],"answer":2,"type":"요청·제안","explanation":"\"please tell me your size by Wednesday\"라고 했으므로 티셔츠 사이즈를 알려 달라는 것이다."}],"translation":"W: 안녕하세요, 알렉스, 벤. 두 분 다음 주 토요일 회사 체육대회 신청했어요?\nM: 저는 했어요. 축구 팀에 이름을 올렸어요.\nM2: 저도 축구를 하고 싶었는데 신청표에 이미 꽉 찼다고 되어 있더라고요.\nW: 맞아요, 벤. 선수는 11명까지만 받을 수 있어요. 그런데 배구 팀은 아직 두 명이 더 필요해요.\nM2: 배구도 재밌겠네요. 그쪽으로 할게요.\nW: 좋아요. 이름 넣어 둘게요. 아, 모두에게 무료 티셔츠를 주니까 수요일까지 사이즈를 알려 주세요.","part":3},{"id":"p3-110","level":2,"topic":"노트북 수리 센터","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi. My laptop won't turn on, and I need it for work. Can you take a look?"},{"s":"W","t":"Sure. Hmm, the battery seems to be the problem. Is it still under warranty?"},{"s":"M","t":"No, I bought it about three years ago."},{"s":"W","t":"Then there will be a charge. A new battery usually fixes this."},{"s":"M","t":"OK, please go ahead. How long will it take?"},{"s":"W","t":"We have the part in stock, so you can pick it up later this afternoon. Just leave your charger with it."}],"graphic":{"title":"QuickFix Repair Center — Service Prices","rows":[["Service","Price"],["Screen replacement","$180"],["Keyboard replacement","$95"],["Battery replacement","$120"],["Software check","$40"]]},"questions":[{"q":"What is the problem with the man's laptop?","choices":["It is running slowly.","It does not turn on.","The screen is cracked.","Some keys are missing."],"answer":1,"type":"주제·목적","explanation":"\"My laptop won't turn on\"이라고 했다."},{"q":"Look at the graphic. How much will the man most likely pay?","choices":["$40","$95","$120","$180"],"answer":2,"type":"시각 자료 연계","explanation":"보증 기간이 지나 비용이 들고, 배터리를 교체하기로 했으므로 표의 Battery replacement, 120달러다."},{"q":"What does the woman ask the man to leave?","choices":["His charger","His receipt","His phone number","His warranty card"],"answer":0,"type":"요청·제안","explanation":"\"Just leave your charger with it\"이라고 했다."}],"translation":"M: 안녕하세요. 노트북이 안 켜지는데 업무에 필요해서요. 좀 봐 주실 수 있나요?\nW: 그럼요. 음, 배터리가 문제인 것 같네요. 아직 보증 기간인가요?\nM: 아니요, 3년 전쯤 샀어요.\nW: 그럼 비용이 발생해요. 보통 새 배터리로 바꾸면 해결돼요.\nM: 네, 진행해 주세요. 얼마나 걸릴까요?\nW: 부품 재고가 있어서 오늘 오후 늦게 찾아가실 수 있어요. 충전기만 같이 두고 가세요.","part":3},{"id":"p3-111","level":2,"topic":"공항 셔틀버스 시간 확인","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Excuse me. Does the shuttle bus to the convention center leave from here?"},{"s":"M","t":"Yes, it does. Here's the schedule for this afternoon."},{"s":"W","t":"Thanks. It's almost two thirty now. My presentation starts at four, and the ride takes about forty minutes."},{"s":"M","t":"Then you should take the next bus. The one after that would get you there too late."},{"s":"W","t":"OK. Do I pay the driver?"},{"s":"M","t":"No, you need to buy a ticket from that machine over there. It only takes cards."}],"graphic":{"title":"Airport Shuttle — Convention Center Line","rows":[["Departure","Arrival"],["2:15 P.M.","2:55 P.M."],["2:50 P.M.","3:30 P.M."],["3:25 P.M.","4:05 P.M."],["4:00 P.M.","4:40 P.M."]]},"questions":[{"q":"Why is the woman going to the convention center?","choices":["To meet a client","To give a presentation","To set up a booth","To pick up a badge"],"answer":1,"type":"세부 사항","explanation":"\"My presentation starts at four\"라고 했으므로 발표를 하러 간다."},{"q":"Look at the graphic. Which bus will the woman most likely take?","choices":["The 2:15 bus","The 2:50 bus","The 3:25 bus","The 4:00 bus"],"answer":1,"type":"시각 자료 연계","explanation":"4시 발표 전에 도착해야 하는데, 3시 25분 버스는 4시 5분 도착이라 늦는다. 지금이 거의 2시 30분이라 2시 15분 버스는 이미 떠났고, 남자가 말한 '다음 버스'는 2시 50분 버스(3시 30분 도착)다."},{"q":"What does the man tell the woman?","choices":["A machine accepts only cards.","The bus is free.","Tickets are sold online.","She should pay the driver."],"answer":0,"type":"세부 사항","explanation":"\"you need to buy a ticket from that machine... It only takes cards\"라고 했다. 운전기사에게 내는 것이 아니라고 했다."}],"translation":"W: 실례합니다. 컨벤션 센터 가는 셔틀버스가 여기서 출발하나요?\nM: 네, 그래요. 여기 오늘 오후 시간표예요.\nW: 고마워요. 지금 거의 2시 30분이네요. 제 발표가 4시에 시작하고 가는 데 40분쯤 걸려요.\nM: 그럼 다음 버스를 타셔야 해요. 그다음 버스는 너무 늦어요.\nW: 네. 요금은 기사님께 내나요?\nM: 아니요, 저기 있는 기계에서 표를 사셔야 해요. 카드만 받아요.","part":3},{"id":"p3-112","level":2,"topic":"신입 직원 자리 배치","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Rachel, our new designer starts on Monday. Where should we put her desk?"},{"s":"W","t":"How about the empty desk by the window, next to Tom?"},{"s":"M","t":"Tom's on the phone with customers all day."},{"s":"W","t":"Oh, right. She'll need a quiet place to focus. What about the corner near the design team, then?"},{"s":"M","t":"That works. But there's no computer there yet."},{"s":"W","t":"I'll ask the IT department to set one up before Monday."}],"graphic":null,"questions":[{"q":"What are the speakers discussing?","choices":["Hiring a designer","Moving to a new office","Where a new employee will sit","Buying new furniture"],"answer":2,"type":"주제·목적","explanation":"새 디자이너의 책상을 어디에 둘지 이야기하고 있다. 채용은 이미 끝났다(starts on Monday)."},{"q":"What does the man imply when he says, \"Tom's on the phone with customers all day\"?","choices":["Tom should train the new designer.","Customers often visit the office.","Tom is very busy.","The window desk would be noisy."],"answer":3,"type":"의도 파악","explanation":"톰 옆자리를 제안받고 이 말을 하자 여자가 '조용한 곳이 필요하겠다'고 반응하므로, 그 자리가 시끄러울 것이라는 뜻이다."},{"q":"What will the woman do?","choices":["Move Tom's desk","Contact the IT department","Call the new designer","Order a new chair"],"answer":1,"type":"다음 할 일","explanation":"\"I'll ask the IT department to set one up\"이라고 했다."}],"translation":"M: 레이첼, 새 디자이너가 월요일에 출근해요. 책상을 어디에 둘까요?\nW: 창가 옆 빈 책상, 톰 옆자리는 어때요?\nM: 톰은 하루 종일 고객이랑 통화하잖아요.\nW: 아, 맞다. 집중할 조용한 곳이 필요하겠네요. 그럼 디자인 팀 근처 구석 자리는요?\nM: 좋아요. 그런데 거긴 아직 컴퓨터가 없어요.\nW: 월요일 전에 IT 부서에 설치해 달라고 할게요.","part":3},{"id":"p3-113","level":2,"topic":"고객 주문 수량 변경 전화","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hello, this is Sandra Kim from Bright Bakery. I placed an order for paper cups yesterday."},{"s":"M","t":"Yes, Ms. Kim. Two thousand cups, right?"},{"s":"W","t":"That's right. But we're opening a second shop next week, so I'd like to double it."},{"s":"M","t":"Congratulations! Four thousand cups, then. Do you still want them on Thursday?"},{"s":"W","t":"Yes, if possible. Will the price change?"},{"s":"M","t":"Actually, orders over three thousand get a ten percent discount. I'll e-mail you the new invoice."}],"graphic":null,"questions":[{"q":"Why does the woman want to change her order?","choices":["The price went up.","A customer canceled an event.","Her shop is opening another location.","She ordered the wrong size."],"answer":2,"type":"세부 사항","explanation":"\"we're opening a second shop next week\"라고 했으므로 두 번째 매장을 열기 때문이다."},{"q":"How many cups will the woman receive?","choices":["2,000","3,000","4,000","5,000"],"answer":2,"type":"세부 사항","explanation":"원래 2,000개를 두 배로 늘려 4,000개다. 3,000은 할인 기준 수량이다."},{"q":"What does the man say he will do?","choices":["Deliver the order early","Visit the new shop","Call the woman back","Send an updated invoice"],"answer":3,"type":"다음 할 일","explanation":"\"I'll e-mail you the new invoice\"라고 했다."}],"translation":"W: 안녕하세요, 브라이트 베이커리의 샌드라 김입니다. 어제 종이컵을 주문했는데요.\nM: 네, 김 선생님. 2,000개 맞으시죠?\nW: 맞아요. 그런데 다음 주에 2호점을 열게 돼서 두 배로 늘리고 싶어요.\nM: 축하드려요! 그럼 4,000개네요. 여전히 목요일에 받으시겠어요?\nW: 네, 가능하면요. 가격이 바뀌나요?\nM: 사실 3,000개 넘는 주문은 10퍼센트 할인이 돼요. 새 청구서를 이메일로 보내 드릴게요.","part":3},{"id":"p3-114","level":2,"topic":"사내 헌혈 행사","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, Emma. Are you going to give blood at the blood drive tomorrow?"},{"s":"W","t":"I'd like to, but I have a client visit in the morning."},{"s":"M","t":"The bus will be in the parking lot until four in the afternoon."},{"s":"W","t":"Oh, then I can go after lunch. Do I need to make an appointment?"},{"s":"M","t":"It's better to. You can choose a time on the HR website."},{"s":"W","t":"OK. I'll do that now. Thanks for letting me know."}],"graphic":null,"questions":[{"q":"What event will take place tomorrow?","choices":["A blood drive","A health seminar","A client lunch","A parking lot repair"],"answer":0,"type":"주제·목적","explanation":"\"give blood at the blood drive tomorrow\"라고 했으므로 헌혈 행사다."},{"q":"What is the woman doing tomorrow morning?","choices":["Meeting a client","Visiting a doctor","Working from home","Attending a training"],"answer":0,"type":"세부 사항","explanation":"\"I have a client visit in the morning\"이라고 했다."},{"q":"What will the woman most likely do next?","choices":["Go to the parking lot","Call a client","Book a time online","Have lunch"],"answer":2,"type":"다음 할 일","explanation":"남자가 HR 웹사이트에서 시간을 고르라고 하자 \"I'll do that now\"라고 했다."}],"translation":"M: 안녕하세요, 엠마. 내일 헌혈 행사에서 헌혈할 거예요?\nW: 하고 싶은데 오전에 고객 방문이 있어요.\nM: 헌혈 버스는 오후 4시까지 주차장에 있을 거예요.\nW: 아, 그럼 점심 먹고 갈 수 있겠네요. 예약해야 하나요?\nM: 하는 게 좋아요. 인사팀 웹사이트에서 시간을 고를 수 있어요.\nW: 알겠어요. 지금 할게요. 알려 줘서 고마워요.","part":3},{"id":"p3-115","level":2,"topic":"인쇄소 브로슈어 용지 선택","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi. I need five hundred brochures for a trade show next month. I'd like them to look high quality."},{"s":"M","t":"Sure. Here are our paper options. Glossy paper makes photos look bright."},{"s":"W","t":"We have a lot of product photos, but I don't want the most expensive one."},{"s":"M","t":"Then I recommend the second most expensive option. Customers like it a lot."},{"s":"W","t":"OK, let's go with that. Can you also add our logo on the back?"},{"s":"M","t":"Of course. Please send me the logo file, and I'll prepare a sample."}],"graphic":{"title":"Paper Options (per 500 brochures)","rows":[["Paper Type","Price"],["Standard matte","$150"],["Recycled","$170"],["Glossy","$210"],["Premium glossy","$260"]]},"questions":[{"q":"What will the brochures be used for?","choices":["A grand opening","A training session","A mailing to customers","A trade show"],"answer":3,"type":"세부 사항","explanation":"\"five hundred brochures for a trade show next month\"라고 했다."},{"q":"Look at the graphic. Which paper will the woman most likely choose?","choices":["Standard matte","Recycled","Glossy","Premium glossy"],"answer":2,"type":"시각 자료 연계","explanation":"가장 비싼 것은 원하지 않았고 남자가 두 번째로 비싼 것을 추천해 받아들였다. 표에서 두 번째로 비싼 것은 Glossy(210달러)다."},{"q":"What does the man ask the woman to send?","choices":["A product list","A logo file","A delivery address","A deposit"],"answer":1,"type":"요청·제안","explanation":"\"Please send me the logo file\"이라고 했다."}],"translation":"W: 안녕하세요. 다음 달 무역 박람회용 브로슈어 500부가 필요해요. 고급스러워 보였으면 해요.\nM: 네. 여기 용지 종류예요. 유광지는 사진을 선명하게 보이게 해요.\nW: 제품 사진이 많긴 한데 가장 비싼 건 원하지 않아요.\nM: 그럼 두 번째로 비싼 것을 추천해요. 고객분들이 많이 좋아하세요.\nW: 좋아요, 그걸로 할게요. 뒷면에 저희 로고도 넣어 주실 수 있나요?\nM: 그럼요. 로고 파일을 보내 주시면 샘플을 준비할게요.","part":3},{"id":"p3-116","level":2,"topic":"회의실 프로젝터 고장","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Olivia, the projector in Meeting Room B isn't working. The screen just stays blue."},{"s":"W","t":"Oh, no. Your training session starts in fifteen minutes, doesn't it?"},{"s":"M","t":"Yes, and there are twenty people coming."},{"s":"W","t":"Well, the sales team just finished in Room C."},{"s":"M","t":"Really? Then I'll move everything over there right now."},{"s":"W","t":"I'll put a sign on the door of Room B so people know where to go."}],"graphic":null,"questions":[{"q":"What problem does the man report?","choices":["A projector is not working.","A room is double-booked.","Some chairs are missing.","A trainer is late."],"answer":0,"type":"주제·목적","explanation":"\"the projector in Meeting Room B isn't working\"라고 했다."},{"q":"Why does the woman say, \"the sales team just finished in Room C\"?","choices":["To complain about the sales team","To ask the man to join the sales team","To suggest using another room","To explain why she is late"],"answer":2,"type":"의도 파악","explanation":"C 회의실이 방금 비었다는 말에 남자가 그곳으로 옮기겠다고 하므로, 다른 방을 쓰자는 제안이다."},{"q":"What will the woman do?","choices":["Fix the projector","Call the sales team","Cancel the session","Post a sign"],"answer":3,"type":"다음 할 일","explanation":"\"I'll put a sign on the door of Room B\"라고 했다."}],"translation":"M: 올리비아, B 회의실 프로젝터가 안 돼요. 화면이 계속 파랗게만 나와요.\nW: 이런. 교육이 15분 뒤에 시작하죠?\nM: 네, 20명이 와요.\nW: 음, 영업팀이 C 회의실에서 방금 끝났어요.\nM: 정말요? 그럼 지금 바로 다 그쪽으로 옮길게요.\nW: 사람들이 어디로 가야 하는지 알게 B 회의실 문에 안내문을 붙일게요.","part":3},{"id":"p3-117","level":3,"topic":"협력사 방문 일정 조정","speakers":{"W":"female","M":"male","W2":"female"},"script":[{"s":"W","t":"Thanks for joining me. As you know, the engineers from Halvorsen Tools are visiting next week. We need to decide which day works best."},{"s":"M","t":"They originally asked for Tuesday, but that's when our production line is being inspected. The factory floor will be closed to visitors."},{"s":"W2","t":"What about Thursday? The inspection should be finished by then, and I'm free all day to give them a tour."},{"s":"W","t":"Thursday's fine with me too. Paul, could you let them know?"},{"s":"M","t":"Sure. I'll also ask whether they need us to arrange a hotel near the plant."},{"s":"W2","t":"Good idea. Last time they stayed downtown, and the drive took almost an hour."}],"graphic":null,"questions":[{"q":"Why is Tuesday not a good day for the visit?","choices":["A holiday is scheduled.","The factory will be inspected.","The meeting rooms are booked.","Some engineers will be traveling."],"answer":1,"type":"세부 사항","explanation":"남자가 화요일에는 \"our production line is being inspected\"라서 방문객 출입이 안 된다고 했다."},{"q":"What does the woman ask Paul to do?","choices":["Contact the visitors","Book a meeting room","Reschedule an inspection","Lead a factory tour"],"answer":0,"type":"요청·제안","explanation":"\"Paul, could you let them know?\"라고 했으므로 방문객(할보슨 툴스 엔지니어)에게 연락하라는 요청이다. 투어는 W2가 맡는다."},{"q":"What problem did the visitors have last time?","choices":["Their flight was delayed.","They could not find parking.","Their hotel was far from the plant.","Their tour was canceled."],"answer":2,"type":"세부 사항","explanation":"W2가 \"Last time they stayed downtown, and the drive took almost an hour\"라고 했으므로 숙소가 공장에서 멀었다."}],"translation":"W: 함께해 줘서 고마워요. 아시다시피 다음 주에 할보슨 툴스 엔지니어들이 방문해요. 어느 요일이 가장 좋을지 정해야 해요.\nM: 원래 화요일을 원했는데, 그날 생산 라인 점검이 있어요. 공장 현장에 방문객이 들어갈 수 없어요.\nW2: 목요일은 어때요? 그때면 점검이 끝났을 거고, 저는 종일 시간이 돼서 공장 안내를 할 수 있어요.\nW: 저도 목요일 괜찮아요. 폴, 그쪽에 알려 줄래요?\nM: 네. 공장 근처 호텔을 잡아 드릴지도 물어볼게요.\nW2: 좋은 생각이에요. 지난번엔 시내에 묵어서 차로 거의 한 시간이 걸렸거든요.","part":3},{"id":"p3-118","level":3,"topic":"원격 근무 설문 결과","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Have you seen the results of the employee survey about remote work?"},{"s":"W","t":"Yes. Most people want to work from home two days a week, but they said our video meetings often have sound problems."},{"s":"M","t":"I noticed that too. The headsets we gave out last year are pretty cheap."},{"s":"W","t":"I agree. I'll get prices for better headsets from a few suppliers."},{"s":"M","t":"Good. If we can show the cost to the director by Friday, the change could start next month."},{"s":"W","t":"I'll try. I'll also put together a short summary of the survey for her."}],"graphic":null,"questions":[{"q":"What are the speakers mainly discussing?","choices":["A new office layout","The results of a survey","A hiring plan","A director's retirement"],"answer":1,"type":"주제·목적","explanation":"원격 근무에 대한 직원 설문 결과를 보고 그에 따른 조치를 논의하고 있다."},{"q":"What complaint did employees make?","choices":["Their computers are too slow.","They have too many meetings.","The office is too crowded.","Video meetings have audio issues."],"answer":3,"type":"세부 사항","explanation":"\"our video meetings often have sound problems\"라고 했다. sound problems → audio issues."},{"q":"What will the woman do?","choices":["Collect price quotes","Schedule a video meeting","Return some headsets","Survey employees again"],"answer":0,"type":"다음 할 일","explanation":"\"I'll get prices for better headsets from a few suppliers\"라고 했으므로 견적을 받을 것이다."}],"translation":"M: 원격 근무에 대한 직원 설문 결과 봤어요?\nW: 네. 대부분 일주일에 이틀 재택근무를 원하는데, 화상 회의에 소리 문제가 자주 있다고 했어요.\nM: 저도 그걸 봤어요. 작년에 나눠 준 헤드셋이 꽤 싼 거라서요.\nW: 맞아요. 몇몇 공급업체에서 더 좋은 헤드셋 가격을 알아볼게요.\nM: 좋아요. 금요일까지 이사님께 비용을 보여 드릴 수 있으면 다음 달부터 바꿀 수 있을 거예요.\nW: 해 볼게요. 이사님께 드릴 설문 요약도 짧게 만들게요.","part":3},{"id":"p3-119","level":3,"topic":"매장 진열 위치 변경","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Marcus, I've been looking at last month's sales for the four display areas in the store."},{"s":"M","t":"And? I'm guessing the area by the entrance did the best."},{"s":"W","t":"Actually, no. It came in second. The area near the checkout counter sold the most."},{"s":"M","t":"Interesting. People must pick up small items while they wait in line."},{"s":"W","t":"Exactly. So I'd like to move our new phone cases from the back wall to the area that came in third. People walking by outside can see it, but what's there now just isn't selling."},{"s":"M","t":"Hmm, wouldn't it be better to put them in the area that sold the most?"},{"s":"W","t":"The checkout area is already full. But with good signs, I think the other spot could work. I'll make some new signs this afternoon."}],"graphic":{"title":"Sales by Display Area — Last Month","rows":[["Display Area","Sales"],["Entrance","$8,400"],["Checkout counter","$9,100"],["Window","$5,200"],["Back wall","$3,700"]]},"questions":[{"q":"What does the woman say about the entrance area?","choices":["It had the highest sales.","It had the second highest sales.","It needs new lighting.","It will be closed."],"answer":1,"type":"세부 사항","explanation":"남자가 입구 쪽이 가장 잘 팔렸을 거라고 하자 여자가 \"It came in second\"라고 했다. 표에서도 입구는 8,400달러로 2위다."},{"q":"Look at the graphic. Where will the phone cases most likely be moved?","choices":["Entrance","Checkout counter","Window","Back wall"],"answer":2,"type":"시각 자료 연계","explanation":"휴대폰 케이스를 뒷벽에서 '3위를 한 구역'으로 옮기려 한다. 표에서 매출 3위는 창가(Window, 5,200달러)다. 계산대 쪽은 이미 꽉 찼다고 했고, 뒷벽은 지금 케이스가 있는 곳이다."},{"q":"What will the woman do this afternoon?","choices":["Order more phone cases","Train new staff","Count the inventory","Make new signs"],"answer":3,"type":"다음 할 일","explanation":"\"I'll make some new signs this afternoon\"이라고 했다."}],"translation":"W: 마커스, 매장 진열 구역 네 곳의 지난달 매출을 보고 있었어요.\nM: 그래서요? 입구 쪽이 가장 잘 됐을 것 같은데요.\nW: 사실 아니에요. 2위였어요. 계산대 근처 구역이 가장 많이 팔렸어요.\nM: 흥미롭네요. 사람들이 줄 서서 기다리면서 작은 물건을 집나 봐요.\nW: 바로 그거예요. 그래서 새 휴대폰 케이스를 뒷벽에서 3위 한 구역으로 옮기고 싶어요. 밖을 지나가는 사람들이 볼 수 있는데 지금 있는 물건이 안 팔리거든요.\nM: 음, 가장 많이 팔린 구역에 두는 게 낫지 않을까요?\nW: 계산대 쪽은 이미 꽉 찼어요. 그래도 안내판만 잘 만들면 그 자리도 괜찮을 것 같아요. 오늘 오후에 새 안내판을 만들게요.","part":3},{"id":"p3-120","level":3,"topic":"온라인 쇼핑몰 무료 배송 기준 변경","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Jasmine, did you see that our shipping costs went up again this quarter?"},{"s":"W","t":"I did. We still offer free shipping on every order, no matter how small."},{"s":"M","t":"Some companies only offer it on orders over fifty dollars."},{"s":"W","t":"That might work. Most of our customers spend about forty dollars, so some of them would probably add one more item."},{"s":"M","t":"Right. Before we decide, though, I'd like to see how customers react. Could we test it on our website for two weeks?"},{"s":"W","t":"Sure. I'll ask the web team to set it up for half of our visitors."}],"graphic":null,"questions":[{"q":"What problem are the speakers discussing?","choices":["A website is not working.","Customers are returning items.","Shipping costs have increased.","Packages are arriving late."],"answer":2,"type":"주제·목적","explanation":"\"our shipping costs went up again this quarter\"라고 했으므로 배송비 증가가 문제다."},{"q":"What does the man imply when he says, \"Some companies only offer it on orders over fifty dollars\"?","choices":["Competitors have better products.","The company could set a minimum for free shipping.","Customers prefer other stores.","The company should raise its prices."],"answer":1,"type":"의도 파악","explanation":"모든 주문에 무료 배송을 한다는 말에 대한 응답이므로, 일정 금액 이상에만 무료 배송을 하자는 제안이다. 여자도 \"That might work\"라고 받는다."},{"q":"What will the woman do?","choices":["Contact a shipping company","Lower the prices of some items","Ask a team to run a test","Survey customers by e-mail"],"answer":2,"type":"다음 할 일","explanation":"\"I'll ask the web team to set it up for half of our visitors\"라고 했으므로 웹 팀에 시험 운영을 요청한다."}],"translation":"M: 재스민, 이번 분기에 배송비가 또 오른 거 봤어요?\nW: 봤어요. 우리는 아직 금액에 상관없이 모든 주문에 무료 배송을 하잖아요.\nM: 어떤 회사들은 50달러 넘는 주문에만 해 줘요.\nW: 그게 괜찮을 수도 있겠네요. 고객 대부분이 40달러 정도 쓰니까 일부는 물건을 하나 더 담겠죠.\nM: 맞아요. 그래도 결정 전에 고객 반응을 보고 싶어요. 웹사이트에서 2주 동안 시험해 볼 수 있을까요?\nW: 그럼요. 방문자 절반에게 적용하도록 웹 팀에 요청할게요.","part":3},{"id":"p3-121","level":3,"topic":"연례 보고서 디자인 외주","speakers":{"M":"male","W":"female","M2":"male"},"script":[{"s":"M","t":"Linda, Chris, thanks for coming. This year's annual report needs a new look, and our in-house designers are fully booked."},{"s":"W","t":"I've worked with an agency called Brightline before. Their work is excellent, but they usually need six weeks."},{"s":"M2","t":"Six weeks is cutting it close. The report has to go to shareholders by the end of May."},{"s":"M","t":"If we send them the text by next Friday, we'd still have about a week to spare."},{"s":"W","t":"Then I'll call Brightline this afternoon and ask for a quote."},{"s":"M2","t":"And I'll make sure the finance team finishes the numbers by Wednesday so the text is ready in time."}],"graphic":null,"questions":[{"q":"Why does the company need outside help?","choices":["Its budget was increased.","Its printer has closed.","Its report has errors.","Its designers are too busy."],"answer":3,"type":"세부 사항","explanation":"\"our in-house designers are fully booked\"라고 했으므로 사내 디자이너가 바쁘기 때문이다."},{"q":"What does Chris mean when he says, \"Six weeks is cutting it close\"?","choices":["The schedule leaves little extra time.","The deadline is far away.","The agency charges too much.","The report is too long."],"answer":0,"type":"의도 파악","explanation":"cut it close는 '시간이 빠듯하다'는 뜻이다. 5월 말 마감과 비교해 6주가 걸리면 여유가 거의 없다는 의미다."},{"q":"What will the woman do this afternoon?","choices":["Meet the shareholders","Check the financial data","Request a price from an agency","Write the report"],"answer":2,"type":"다음 할 일","explanation":"\"I'll call Brightline this afternoon and ask for a quote\"라고 했다. 숫자 확인은 M2(크리스)가 재무팀을 통해 챙긴다."}],"translation":"M: 린다, 크리스, 와 줘서 고마워요. 올해 연례 보고서는 디자인을 새로 해야 하는데, 사내 디자이너들 일정이 꽉 찼어요.\nW: 제가 전에 브라이트라인이라는 에이전시와 일해 봤어요. 실력은 훌륭한데 보통 6주가 필요해요.\nM2: 6주면 빠듯하네요. 보고서가 5월 말까지 주주들에게 가야 하거든요.\nM: 다음 주 금요일까지 원고를 보내면 그래도 일주일 정도 여유가 있어요.\nW: 그럼 오늘 오후에 브라이트라인에 전화해서 견적을 요청할게요.\nM2: 저는 원고가 제때 준비되도록 재무팀이 수요일까지 수치를 마무리하게 챙길게요.","part":3},{"id":"p3-122","level":3,"topic":"신규 고객 환영 선물 패키지","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Owen, I'd like to start sending a welcome package to every new business client."},{"s":"M","t":"That's a nice idea. What would you put in it?"},{"s":"W","t":"A thank-you card from our CEO, a quick-start guide to our software, and maybe a coffee mug with our logo."},{"s":"M","t":"I like the guide, but mugs are expensive to ship. What about a gift card for coffee instead? It could be sent by e-mail."},{"s":"W","t":"Good point. That would save a lot. I'll talk to the marketing team about designing the guide."},{"s":"M","t":"Let me know if you need help with the budget."}],"graphic":null,"questions":[{"q":"What does the woman want to do?","choices":["Hire more sales staff","Update some software","Open a coffee shop","Send gifts to new clients"],"answer":3,"type":"주제·목적","explanation":"\"start sending a welcome package to every new business client\"라고 했다."},{"q":"Why does the man suggest a gift card?","choices":["It is cheaper to send.","Clients asked for it.","Mugs are out of stock.","The CEO prefers it."],"answer":0,"type":"세부 사항","explanation":"\"mugs are expensive to ship... It could be sent by e-mail\"이라고 했으므로 보내는 비용이 덜 든다는 이유다."},{"q":"Who will the woman speak with?","choices":["A shipping company","The marketing team","The CEO","A coffee supplier"],"answer":1,"type":"다음 할 일","explanation":"\"I'll talk to the marketing team about designing the guide\"라고 했다."}],"translation":"W: 오언, 모든 신규 기업 고객에게 환영 패키지를 보내기 시작하고 싶어요.\nM: 좋은 생각이네요. 뭘 넣을 거예요?\nW: CEO의 감사 카드, 우리 소프트웨어 빠른 시작 가이드, 그리고 로고가 들어간 머그잔 정도요.\nM: 가이드는 좋은데 머그잔은 배송비가 비싸요. 대신 커피 기프트 카드는 어때요? 이메일로 보낼 수 있잖아요.\nW: 좋은 지적이에요. 비용이 많이 줄겠네요. 가이드 디자인은 마케팅 팀과 이야기할게요.\nM: 예산 관련해서 도움이 필요하면 알려 줘요.","part":3},{"id":"p3-123","level":3,"topic":"전시회 부스 크기 선택","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, I'm calling about booking a booth at the Regional Food Expo in September."},{"s":"W","t":"Certainly. Here are the booth sizes we have left."},{"s":"M","t":"We'll be bringing two refrigerators and a small cooking area for samples, so we need at least twelve square meters."},{"s":"W","t":"I should mention that any booth with cooking equipment must have a corner location for safety reasons."},{"s":"M","t":"I see. Then we'll take the smallest booth that meets both of those needs."},{"s":"W","t":"All right. I'll send you a contract, and the booth will be reserved once we receive a thirty percent deposit."}],"graphic":{"title":"Regional Food Expo — Available Booths","rows":[["Booth","Size","Location","Price"],["A","9 m²","Corner","$900"],["B","12 m²","Aisle","$1,100"],["C","15 m²","Corner","$1,450"],["D","18 m²","Corner","$1,700"]]},"questions":[{"q":"What does the man's company plan to do at the expo?","choices":["Recruit chefs","Hold a cooking contest","Sell refrigerators","Give food samples"],"answer":3,"type":"세부 사항","explanation":"\"a small cooking area for samples\"를 가져온다고 했으므로 시식용 음식을 제공할 것이다. 냉장고는 판매용이 아니라 장비다."},{"q":"Look at the graphic. Which booth will the man most likely reserve?","choices":["Booth A","Booth B","Booth C","Booth D"],"answer":2,"type":"시각 자료 연계","explanation":"12㎡ 이상이면서 조리 장비 때문에 모서리 위치여야 한다. A는 9㎡라 작고, B는 모서리가 아니다. 조건을 만족하는 가장 작은 부스는 C다."},{"q":"What must the man do to reserve the booth?","choices":["Submit a safety plan","Pay a deposit","Visit the venue","Send product photos"],"answer":1,"type":"세부 사항","explanation":"\"the booth will be reserved once we receive a thirty percent deposit\"라고 했다."}],"translation":"M: 안녕하세요, 9월 지역 식품 박람회 부스 예약 건으로 전화드렸어요.\nW: 네. 남아 있는 부스 크기는 이렇습니다.\nM: 냉장고 두 대와 시식용 작은 조리 공간을 가져갈 거라 최소 12제곱미터가 필요해요.\nW: 말씀드릴 것이 있는데, 조리 장비가 있는 부스는 안전상 모서리 자리여야 해요.\nM: 그렇군요. 그럼 두 조건을 모두 맞추는 가장 작은 부스로 할게요.\nW: 알겠습니다. 계약서를 보내 드릴게요. 보증금 30퍼센트를 받으면 부스가 예약됩니다.","part":3},{"id":"p3-124","level":3,"topic":"노후 노트북 교체 프로그램","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Hi, Victor. IT sent an e-mail saying laptops older than four years will be replaced this month."},{"s":"M","t":"I saw that. Mine is five years old, so I'm on the list. But I have a big client presentation on the twelfth."},{"s":"W","t":"When are they swapping yours?"},{"s":"M","t":"The eleventh. And all my files have to be moved over."},{"s":"W","t":"You could ask them to do it after your presentation. I moved mine to next week without any trouble."},{"s":"M","t":"Really? I'll fill out the request form on their page right away."}],"graphic":null,"questions":[{"q":"What is the IT department doing this month?","choices":["Replacing old laptops","Training new employees","Upgrading the network","Installing new software"],"answer":0,"type":"주제·목적","explanation":"\"laptops older than four years will be replaced this month\"라고 했다."},{"q":"What does the man imply when he says, \"The eleventh\"?","choices":["He forgot the date.","He is free on that day.","The timing could cause a problem.","He has already received a laptop."],"answer":2,"type":"의도 파악","explanation":"12일에 중요한 발표가 있는데 교체일이 바로 전날인 11일이고 파일도 옮겨야 한다고 덧붙이므로, 일정이 문제가 될 수 있다는 뜻이다."},{"q":"What will the man most likely do next?","choices":["Submit a request form","Cancel his presentation","Back up his files","Buy his own laptop"],"answer":0,"type":"다음 할 일","explanation":"\"I'll fill out the request form on their page right away\"라고 했다."}],"translation":"W: 안녕하세요, 빅터. IT팀에서 4년 넘은 노트북을 이번 달에 교체한다는 이메일을 보냈어요.\nM: 봤어요. 제 건 5년 돼서 대상이에요. 그런데 12일에 큰 고객 발표가 있어요.\nW: 언제 바꿔 준대요?\nM: 11일이요. 게다가 파일을 전부 옮겨야 하고요.\nW: 발표 뒤로 해 달라고 요청하면 돼요. 저는 다음 주로 아무 문제 없이 미뤘어요.\nM: 정말요? 지금 바로 IT 페이지에서 요청서를 작성할게요.","part":3},{"id":"p3-125","level":4,"topic":"창고 재고 실사 일정","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"We need to finalize the date for the annual inventory count. Accounting wants the figures before the fiscal year closes on the thirtieth."},{"s":"M","t":"The problem is that shipping volume peaks in the last week of the month. If we shut the warehouse for a full day then, we'll fall behind on orders."},{"s":"M2","t":"What if we split the count over two evenings instead? The second shift could handle the east section on Monday and the west section on Tuesday."},{"s":"W","t":"That would keep shipping running, but the second shift is already short-staffed."},{"s":"M2","t":"I could ask a few people from the day shift to stay late. We'd pay them overtime, of course."},{"s":"W","t":"Overtime is cheaper than missing deliveries. Go ahead and check who's available, and I'll let accounting know about the plan."}],"graphic":null,"questions":[{"q":"Why does the man object to closing the warehouse for a day?","choices":["The building will be inspected.","The software is being updated.","Orders will be delayed.","Employees are on vacation."],"answer":2,"type":"세부 사항","explanation":"월말 마지막 주에 출고량이 가장 많아서 하루 문을 닫으면 \"we'll fall behind on orders\"라고 했다."},{"q":"What concern does the woman raise about the proposal?","choices":["Accounting will not accept it.","It is too expensive.","It requires new equipment.","Not enough workers are available."],"answer":3,"type":"세부 사항","explanation":"\"the second shift is already short-staffed\"라고 해 인력이 부족하다는 우려를 말했다. 초과 근무 수당은 오히려 감수할 만하다고 했다."},{"q":"What will the woman do?","choices":["Change the fiscal year","Inform the accounting department","Count the east section","Hire temporary workers"],"answer":1,"type":"다음 할 일","explanation":"\"I'll let accounting know about the plan\"이라고 했다. 근무 가능 인원 확인은 M2가 한다."}],"translation":"W: 연례 재고 실사 날짜를 확정해야 해요. 회계팀은 30일 회계 연도 마감 전에 수치를 받고 싶어 해요.\nM: 문제는 월말 마지막 주에 출고량이 가장 많다는 거예요. 그때 창고를 하루 종일 닫으면 주문이 밀릴 거예요.\nM2: 대신 이틀 저녁에 나눠서 세면 어때요? 2교대 조가 월요일에 동쪽 구역, 화요일에 서쪽 구역을 맡으면 돼요.\nW: 그러면 출고는 계속 되겠지만, 2교대 조는 이미 인원이 부족해요.\nM2: 주간 근무자 몇 명에게 늦게까지 남아 달라고 해 볼게요. 물론 초과 근무 수당을 주고요.\nW: 초과 근무 수당이 배송 차질보다는 싸죠. 누가 가능한지 확인해 주세요. 저는 회계팀에 계획을 알릴게요.","part":3},{"id":"p3-126","level":4,"topic":"고객 불만 처리 권한 변경","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Natalie, I've been reviewing the complaint logs. Customers are waiting an average of three days for a refund decision."},{"s":"W","t":"That's because every refund, even a small one, has to be approved by a manager."},{"s":"M","t":"Our agents handle hundreds of these a week."},{"s":"W","t":"I know. I've been thinking we could let agents approve refunds under a hundred dollars on their own. That covers most cases."},{"s":"M","t":"I'd support that, as long as we track the numbers. We don't want refunds to go up too much."},{"s":"W","t":"Agreed. I'll draft a proposal with a monthly report, and we can present it at the operations meeting on Thursday."}],"graphic":null,"questions":[{"q":"What problem does the man mention?","choices":["Refund decisions take too long.","Complaint logs are missing.","Agents are leaving the company.","Products are often damaged."],"answer":0,"type":"주제·목적","explanation":"고객이 환불 결정을 평균 3일 기다린다고 했으므로 처리가 오래 걸리는 것이 문제다."},{"q":"Why does the man say, \"Our agents handle hundreds of these a week\"?","choices":["To explain why the logs are incomplete","To emphasize that the current process is inefficient","To praise the agents' performance","To suggest hiring more managers"],"answer":1,"type":"의도 파악","explanation":"작은 환불도 모두 관리자 승인이 필요하다는 말에 이어, 상담원이 매주 수백 건을 처리한다고 강조한 것이므로 현재 절차가 비효율적이라는 뜻이다. 여자도 바로 권한 위임안을 꺼낸다."},{"q":"What does the woman plan to include in her proposal?","choices":["A training schedule","A customer survey","A monthly report","A new refund form"],"answer":2,"type":"세부 사항","explanation":"\"I'll draft a proposal with a monthly report\"라고 했다. 환불 증가를 추적하자는 남자의 조건을 반영한 것이다."}],"translation":"M: 나탈리, 불만 처리 기록을 검토하고 있었어요. 고객들이 환불 결정까지 평균 3일을 기다리고 있어요.\nW: 아무리 소액 환불이라도 모두 관리자 승인을 받아야 해서 그래요.\nM: 상담원들이 이런 걸 일주일에 수백 건 처리하잖아요.\nW: 알아요. 100달러 미만 환불은 상담원이 직접 승인하게 하면 어떨까 생각했어요. 대부분의 경우가 거기에 해당해요.\nM: 찬성이에요. 수치를 추적한다면요. 환불이 너무 늘어나면 안 되니까요.\nW: 동의해요. 월간 보고를 포함한 제안서 초안을 만들어서 목요일 운영 회의에서 발표해요.","part":3},{"id":"p3-127","level":4,"topic":"포장재 공급업체 단가 인상 협상","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Mr. Carter, I received your new price list for the shipping boxes. The increase is larger than we expected."},{"s":"M","t":"I understand. Our paper costs have gone up nearly twenty percent this year, so we had to adjust."},{"s":"W","t":"We order almost entirely the medium-sized box, about twenty thousand a month. Is there any flexibility on that one?"},{"s":"M","t":"If you're willing to sign a one-year contract, I could keep that size at last year's price."},{"s":"W","t":"That's appealing. But I'd need to run it by our purchasing director first."},{"s":"M","t":"Of course. I'll hold the offer until the end of next week."}],"graphic":{"title":"Carter Packaging — Price per Box","rows":[["Box Size","Last Year","New Price"],["Small","$0.42","$0.48"],["Medium","$0.65","$0.74"],["Large","$0.88","$0.99"],["Extra Large","$1.20","$1.35"]]},"questions":[{"q":"According to the man, why did prices increase?","choices":["A factory was closed.","Demand has fallen.","Shipping fees rose.","Material costs went up."],"answer":3,"type":"세부 사항","explanation":"\"Our paper costs have gone up nearly twenty percent\"라고 했으므로 원자재(종이) 비용 상승 때문이다."},{"q":"Look at the graphic. What price per box will the woman's company pay if it signs the contract?","choices":["$0.48","$0.65","$0.74","$0.88"],"answer":1,"type":"시각 자료 연계","explanation":"여자 회사는 주로 중간 크기 상자를 주문하고, 1년 계약 시 그 크기를 작년 가격으로 유지해 준다고 했다. 표에서 Medium의 작년 가격은 0.65달러다. 0.74달러는 새 가격이다."},{"q":"What does the woman say she needs to do?","choices":["Consult a director","Reduce her order","Compare other suppliers","Visit the factory"],"answer":0,"type":"다음 할 일","explanation":"\"I'd need to run it by our purchasing director first\"라고 했다. run it by = 의견을 묻다."}],"translation":"W: 카터 씨, 배송 상자 새 가격표를 받았어요. 인상 폭이 예상보다 크네요.\nM: 이해합니다. 올해 종이 원가가 20퍼센트 가까이 올라서 조정할 수밖에 없었어요.\nW: 저희는 거의 중간 크기 상자만 한 달에 2만 개 정도 주문해요. 그 제품은 조정 여지가 있을까요?\nM: 1년 계약을 맺으시면 그 크기는 작년 가격으로 유지해 드릴 수 있어요.\nW: 솔깃하네요. 하지만 먼저 구매 담당 이사님께 여쭤봐야 해요.\nM: 물론이죠. 다음 주 말까지 이 조건을 유지해 둘게요.","part":3},{"id":"p3-128","level":4,"topic":"사내 멘토링 프로그램 매칭","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Hi, Grace. How's the matching going for the new mentoring program?"},{"s":"W","t":"Pretty well. Thirty-two junior employees signed up, but we only have twenty-five senior volunteers."},{"s":"M","t":"Could some mentors take on two people?"},{"s":"W","t":"A few offered to, but I'm worried they won't have enough time. The program asks for a one-hour meeting every two weeks."},{"s":"M","t":"What if the extra pairs met once a month instead? That would make it more manageable."},{"s":"W","t":"That might work. I'll check with the volunteers who offered and update the schedule before the kickoff event."}],"graphic":null,"questions":[{"q":"What problem does the woman mention?","choices":["The program has no budget.","There are not enough mentors.","The kickoff event was canceled.","Junior employees lost interest."],"answer":1,"type":"주제·목적","explanation":"신청자 32명에 비해 선배 자원봉사자가 25명뿐이라 멘토가 부족하다."},{"q":"What does the man suggest?","choices":["Recruiting outside mentors","Delaying the kickoff event","Shortening the program","Having some pairs meet less often"],"answer":3,"type":"요청·제안","explanation":"\"What if the extra pairs met once a month instead?\"라고 추가 짝은 한 달에 한 번 만나자고 제안했다."},{"q":"What will the woman do before the kickoff event?","choices":["Book a venue","Interview applicants","Contact certain volunteers","Send a survey"],"answer":2,"type":"다음 할 일","explanation":"\"I'll check with the volunteers who offered\"라고 했으므로 두 명을 맡겠다고 한 자원봉사자들에게 확인한다."}],"translation":"M: 안녕하세요, 그레이스. 새 멘토링 프로그램 매칭은 잘 되고 있어요?\nW: 꽤 잘 되고 있어요. 저연차 직원이 32명 신청했는데 선배 자원봉사자는 25명뿐이에요.\nM: 몇몇 멘토가 두 명씩 맡을 수는 없을까요?\nW: 몇 명이 그러겠다고 했는데 시간이 충분할지 걱정돼요. 프로그램은 2주마다 한 시간 만남을 요구하거든요.\nM: 추가로 맡는 짝은 대신 한 달에 한 번 만나면 어때요? 그러면 부담이 덜할 거예요.\nW: 괜찮겠네요. 제안했던 자원봉사자들에게 확인해서 발대식 전에 일정을 수정할게요.","part":3},{"id":"p3-129","level":4,"topic":"지역 라디오 광고 시간대 선택","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Thanks for meeting with me. We'd like to advertise our new evening cooking classes on your station."},{"s":"M","t":"Great. Here are the time slots we have available next month, along with our weekly rates."},{"s":"W","t":"Our classes are aimed at people who work full-time, so we want to reach them while they're driving home."},{"s":"M","t":"That makes sense. The afternoon commute slot is popular for exactly that reason."},{"s":"W","t":"It's a bit more than we planned to spend, but it seems worth it. Could you also have one of your hosts read the ad?"},{"s":"M","t":"Certainly. Hosts' voices tend to get better results. I'll e-mail you a draft script by Monday."}],"graphic":{"title":"WKLR 98.3 FM — Weekly Advertising Rates","rows":[["Time Slot","Program","Rate"],["6-9 A.M.","Morning Drive","$1,200"],["9 A.M.-3 P.M.","Midday Mix","$650"],["3-7 P.M.","Afternoon Drive","$1,050"],["7 P.M.-12 A.M.","Night Grooves","$480"]]},"questions":[{"q":"What is the woman's business promoting?","choices":["A radio contest","Kitchen equipment","Cooking classes","A restaurant opening"],"answer":2,"type":"세부 사항","explanation":"\"our new evening cooking classes\"를 광고하고 싶다고 했다."},{"q":"Look at the graphic. How much will the woman most likely pay per week?","choices":["$480","$650","$1,050","$1,200"],"answer":2,"type":"시각 자료 연계","explanation":"직장인들이 퇴근길에 운전할 때 들려주고 싶어 하고, 남자가 오후 출퇴근 시간대를 언급했다. 표에서 Afternoon Drive(3-7 P.M.)는 1,050달러다. 1,200달러는 아침 출근 시간대다."},{"q":"What does the man say he will send?","choices":["A sample script","A contract","An invoice","A recording"],"answer":0,"type":"다음 할 일","explanation":"\"I'll e-mail you a draft script by Monday\"라고 했다."}],"translation":"W: 만나 주셔서 감사해요. 새로 여는 저녁 요리 강좌를 이 방송국에서 광고하고 싶어요.\nM: 좋습니다. 다음 달에 가능한 시간대와 주간 요금은 이렇습니다.\nW: 저희 강좌는 전일제 직장인 대상이라 퇴근길 운전 중에 듣게 하고 싶어요.\nM: 일리가 있네요. 오후 출퇴근 시간대가 바로 그 이유로 인기가 많아요.\nW: 예상보다 조금 비싸지만 그만한 가치가 있겠네요. 진행자 중 한 분이 광고를 읽어 주실 수 있나요?\nM: 물론이죠. 진행자 목소리가 효과가 더 좋아요. 월요일까지 대본 초안을 이메일로 보내 드릴게요.","part":3},{"id":"p3-130","level":4,"topic":"앱 베타 테스트 피드백","speakers":{"M":"male","W":"female","W2":"female"},"script":[{"s":"M","t":"Let's go over the feedback from the beta testers of our budgeting app. Sophie, what stood out?"},{"s":"W","t":"Overall, people liked the design. But nearly half said that connecting their bank account took too many steps."},{"s":"W2","t":"We could combine the verification screens. That would cut the process from six steps to three."},{"s":"M","t":"How long would that take to build?"},{"s":"W2","t":"About two weeks. But launch is scheduled for the first of next month."},{"s":"M","t":"Well, a smooth first experience matters more than a date on a calendar. Let's move the launch back. I'll tell the marketing team today."}],"graphic":null,"questions":[{"q":"What did beta testers complain about?","choices":["The app's design","A complicated setup process","The app's price","Slow customer service"],"answer":1,"type":"세부 사항","explanation":"은행 계좌 연결이 \"took too many steps\"라고 했으므로 설정 과정이 복잡하다는 불만이다. 디자인은 오히려 좋아했다."},{"q":"Why does the woman say, \"launch is scheduled for the first of next month\"?","choices":["To praise the team's progress","To confirm a marketing plan","To suggest an earlier launch","To point out a possible scheduling conflict"],"answer":3,"type":"의도 파악","explanation":"개선에 2주가 걸린다고 한 직후 출시일을 언급한 것이므로 일정이 겹칠 수 있다는 문제 제기다. 남자도 출시를 미루자고 반응한다."},{"q":"What does the man decide to do?","choices":["Postpone the launch","Cancel the beta test","Remove a feature","Hire more developers"],"answer":0,"type":"다음 할 일","explanation":"\"Let's move the launch back\"이라고 했으므로 출시를 연기한다."}],"translation":"M: 가계부 앱 베타 테스터 피드백을 검토해 봅시다. 소피, 눈에 띄는 게 뭐였어요?\nW: 전반적으로 디자인은 좋아했어요. 그런데 거의 절반이 은행 계좌 연결 단계가 너무 많다고 했어요.\nW2: 인증 화면을 합칠 수 있어요. 그러면 여섯 단계가 세 단계로 줄어요.\nM: 만드는 데 얼마나 걸려요?\nW2: 2주 정도요. 그런데 출시가 다음 달 1일로 잡혀 있어요.\nM: 음, 달력의 날짜보다 매끄러운 첫 경험이 더 중요해요. 출시를 미룹시다. 오늘 마케팅 팀에 알릴게요.","part":3},{"id":"p3-131","level":4,"topic":"매장 영업시간 연장 효과 검토","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Andrew, it's been three months since we started staying open until ten on weekdays. What do the numbers look like?"},{"s":"M","t":"Sales between eight and ten are up, but mostly on Thursdays and Fridays. Monday through Wednesday, we barely cover the extra staffing costs."},{"s":"W","t":"So maybe we should keep the late hours only at the end of the week."},{"s":"M","t":"That's what I'd recommend. But some regular customers have told us they like the late hours on Mondays."},{"s":"W","t":"Then before we change anything, let's put a notice at the register and ask for comments for two weeks."},{"s":"M","t":"OK. I'll print the notice and a short comment card this afternoon."}],"graphic":null,"questions":[{"q":"What change did the store make three months ago?","choices":["It hired more staff.","It started a loyalty program.","It opened a new location.","It extended its weekday hours."],"answer":3,"type":"세부 사항","explanation":"\"we started staying open until ten on weekdays\"라고 했으므로 평일 영업시간을 연장했다."},{"q":"According to the man, what is true about Monday through Wednesday?","choices":["Sales are highest then.","Extra costs are barely covered.","The store closes early.","Most regular customers visit then."],"answer":1,"type":"세부 사항","explanation":"\"we barely cover the extra staffing costs\"라고 했다. 단골 일부가 월요일 연장을 좋아한다고 했을 뿐 대부분이 그때 온다는 말은 없다."},{"q":"What does the woman suggest doing?","choices":["Closing the store on Wednesdays","Lowering prices on Mondays","Collecting customer feedback","Hiring a consultant"],"answer":2,"type":"요청·제안","explanation":"계산대에 공지를 두고 2주 동안 의견을 받자고 했으므로 고객 의견 수렴을 제안했다."}],"translation":"W: 앤드루, 평일에 10시까지 영업하기 시작한 지 석 달이 됐어요. 수치는 어때요?\nM: 8시에서 10시 사이 매출은 늘었는데 대부분 목요일과 금요일이에요. 월요일부터 수요일까지는 추가 인건비를 겨우 메우는 수준이에요.\nW: 그럼 늦은 영업은 주 후반에만 하는 게 좋겠네요.\nM: 저도 그렇게 권하고 싶어요. 그런데 몇몇 단골 고객이 월요일 늦은 영업이 좋다고 했어요.\nW: 그럼 뭔가를 바꾸기 전에 계산대에 안내문을 두고 2주 동안 의견을 받아 봐요.\nM: 알겠어요. 오늘 오후에 안내문과 짧은 의견 카드를 출력할게요.","part":3},{"id":"p3-132","level":4,"topic":"법인 차량 리스 교체","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Our lease on the sales team's cars ends in June. I'd like to replace them with electric vehicles this time."},{"s":"W","t":"The monthly payments for electric models are higher, though, aren't they?"},{"s":"M","t":"Slightly, but we'd save a lot on fuel. Our reps drive over two thousand kilometers a month."},{"s":"W","t":"What about charging? Most of them live in apartments."},{"s":"M","t":"That's a fair concern. The leasing company offers a charging card that works at public stations, and we could install a few chargers in our parking garage."},{"s":"W","t":"If you can put the total costs in a comparison sheet, I'll take it to the finance committee."}],"graphic":null,"questions":[{"q":"What is the man proposing?","choices":["Moving to a new office","Leasing electric vehicles","Selling the company's cars","Reducing travel for the sales team"],"answer":1,"type":"주제·목적","explanation":"\"I'd like to replace them with electric vehicles\"라고 했으므로 전기차 리스를 제안했다."},{"q":"What concern does the woman raise?","choices":["The lease ends too soon.","The sales reps do not drive enough.","The cars are too small.","Employees may have trouble charging the cars."],"answer":3,"type":"세부 사항","explanation":"\"What about charging? Most of them live in apartments\"라고 했으므로 충전이 어려울 수 있다는 우려다. 월 납입금이 높다는 점도 물었지만 선택지에는 충전 문제만 있다."},{"q":"What does the woman ask the man to prepare?","choices":["A cost comparison","A list of charging stations","A driving schedule","A new lease contract"],"answer":0,"type":"요청·제안","explanation":"\"put the total costs in a comparison sheet\"라고 했다."}],"translation":"M: 영업팀 차량 리스가 6월에 끝나요. 이번에는 전기차로 바꾸고 싶어요.\nW: 그런데 전기차는 월 납입금이 더 높지 않나요?\nM: 약간요. 하지만 연료비를 많이 아낄 수 있어요. 영업 사원들이 한 달에 2,000킬로미터 넘게 운전하거든요.\nW: 충전은요? 대부분 아파트에 살잖아요.\nM: 타당한 걱정이에요. 리스 회사가 공용 충전소에서 쓰는 충전 카드를 주고, 우리 주차장에 충전기 몇 대를 설치할 수도 있어요.\nW: 총비용을 비교표로 정리해 주면 재무 위원회에 가져갈게요.","part":3},{"id":"p3-133","level":5,"topic":"분기 실적의 환율 영향 분석","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"Before we finalize the earnings summary, I want to address the European figures. Revenue there is down six percent compared with last quarter."},{"s":"M","t":"In local currency, though, European sales actually grew by about four percent. The decline comes entirely from the weaker euro."},{"s":"M2","t":"That's an important distinction. If we report only the converted number, investors may assume demand is slipping."},{"s":"W","t":"Agreed. Let's present both figures side by side, with a short note explaining the currency effect."},{"s":"M","t":"Our hedging contracts expire in March, too."},{"s":"W","t":"Then that needs to be on the agenda for the treasury committee. Kevin, could you prepare a few options with estimated costs before the next meeting?"}],"graphic":null,"questions":[{"q":"What does the man say about European sales?","choices":["They fell because of weaker demand.","They exceeded the company's forecast.","They rose when measured in local currency.","They were reported incorrectly."],"answer":2,"type":"세부 사항","explanation":"\"In local currency, though, European sales actually grew by about four percent\"라고 했다. 6% 감소는 유로 약세로 환산한 결과일 뿐 수요 감소가 아니다."},{"q":"What does the man imply when he says, \"Our hedging contracts expire in March, too\"?","choices":["The summary must be finished by March.","The contracts were too expensive.","The company's currency risk may soon increase.","Investors have asked about the contracts."],"answer":2,"type":"의도 파악","explanation":"환율 영향을 이야기하는 중에 환헤지 계약이 3월에 끝난다고 덧붙인 것은, 그 뒤에는 환율 위험이 더 커질 수 있다는 경고다. 여자가 바로 재무 위원회 안건으로 올리자고 반응한다."},{"q":"What is Kevin asked to do?","choices":["Contact some investors","Prepare options with cost estimates","Rewrite the earnings summary","Convert the figures into euros"],"answer":1,"type":"요청·제안","explanation":"\"Kevin, could you prepare a few options with estimated costs\"라고 했다."}],"translation":"W: 실적 요약을 확정하기 전에 유럽 수치를 짚고 넘어가고 싶어요. 그쪽 매출이 지난 분기 대비 6퍼센트 줄었어요.\nM: 그런데 현지 통화 기준으로는 유럽 매출이 오히려 4퍼센트 정도 늘었어요. 감소분은 전적으로 유로화 약세 때문이에요.\nM2: 그건 중요한 구분이에요. 환산 수치만 발표하면 투자자들이 수요가 줄고 있다고 생각할 수 있어요.\nW: 동의해요. 두 수치를 나란히 보여 주고 환율 영향을 설명하는 짧은 주석을 달죠.\nM: 우리 환헤지 계약도 3월에 만료돼요.\nW: 그럼 그건 재무 위원회 안건에 올려야겠네요. 케빈, 다음 회의 전까지 예상 비용을 포함한 선택안 몇 가지를 준비해 줄래요?","part":3},{"id":"p3-134","level":5,"topic":"공장 설비 예방정비 계약 선택","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"I've narrowed the maintenance contracts for our packaging line down to four tiers. The question is how much downtime risk we're willing to accept."},{"s":"W","t":"Last year, two breakdowns cost us nearly a week of production. I'd rather not go through that again."},{"s":"M","t":"Then guaranteed response time is the key factor. Our plant runs around the clock, so we'd need technicians available at night as well."},{"s":"W","t":"Agreed. But the top tier includes on-site staff we don't really need, since our own engineers cover the day shift."},{"s":"M","t":"So the tier just below that seems like the best balance."},{"s":"W","t":"I think so. Draft a recommendation, and include last year's breakdown costs so the board can see the trade-off."}],"graphic":{"title":"Preventive Maintenance Plans — Annual Cost","rows":[["Plan","Coverage","Response Time","Annual Cost"],["Basic","Weekdays 9-6","48 hours","$18,000"],["Standard","Weekdays 7-10","24 hours","$27,000"],["Advanced","24/7","4 hours","$41,000"],["Premier","24/7 + on-site staff","1 hour","$63,000"]]},"questions":[{"q":"What happened last year?","choices":["Equipment failures halted production.","The plant began operating 24 hours a day.","A maintenance contract was canceled.","A new packaging line was installed."],"answer":0,"type":"세부 사항","explanation":"\"two breakdowns cost us nearly a week of production\"라고 했으므로 설비 고장으로 생산이 멈췄다. 24시간 가동은 원래 그렇다고 했을 뿐 작년에 시작했다는 말은 없다."},{"q":"Look at the graphic. Which plan will the man most likely recommend?","choices":["Basic","Standard","Advanced","Premier"],"answer":2,"type":"시각 자료 연계","explanation":"야간에도 대응이 필요하므로 24/7 플랜이어야 하고, 최상위(Premier)는 필요 없는 상주 인력이 포함돼 있어 '그 바로 아래 등급'을 고른다. 표에서 Advanced(4만 1천 달러)다."},{"q":"What does the woman ask the man to include?","choices":["Quotes from other vendors","Technicians' qualifications","A staffing schedule","Last year's repair costs"],"answer":3,"type":"요청·제안","explanation":"\"include last year's breakdown costs so the board can see the trade-off\"라고 했다."}],"translation":"M: 포장 라인 정비 계약을 네 단계로 좁혔어요. 문제는 가동 중단 위험을 어디까지 감수할지예요.\nW: 작년에 두 번 고장 나서 거의 일주일 치 생산을 잃었어요. 다시 겪고 싶지 않아요.\nM: 그럼 보장 대응 시간이 핵심이에요. 우리 공장은 24시간 돌아가니까 야간에도 기술자가 대응할 수 있어야 해요.\nW: 동의해요. 그런데 최상위 등급에는 우리에게 꼭 필요하지 않은 상주 인력이 포함돼 있어요. 주간은 우리 엔지니어들이 맡으니까요.\nM: 그럼 그 바로 아래 등급이 가장 균형이 맞아 보이네요.\nW: 그런 것 같아요. 권고안을 작성하고, 이사회가 득실을 볼 수 있게 작년 고장 비용도 넣어 주세요.","part":3},{"id":"p3-135","level":5,"topic":"데이터센터 이전 중단 시간 조율","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Rajesh, the vendor has confirmed that migrating our servers to the new data center will require about eight hours of downtime."},{"s":"M","t":"Eight hours is a lot. Our customer portal handles orders from Asia overnight, so there's really no quiet window."},{"s":"W","t":"I looked at the traffic logs. Sunday from midnight to eight a.m. is the lowest point—roughly a fifth of the weekday volume."},{"s":"M","t":"Even so, we'd need to warn customers well in advance. Could we keep the portal running in read-only mode, so they can at least check order status?"},{"s":"W","t":"The vendor said that's possible if we copy the database the day before. It adds some cost, but I think it's justified."},{"s":"M","t":"I agree. I'll draft the customer notice so it can go out two weeks ahead."}],"graphic":null,"questions":[{"q":"What is the company preparing to do?","choices":["Open an office in Asia","Move servers to a new facility","Launch a customer portal","Replace a vendor"],"answer":1,"type":"주제·목적","explanation":"\"migrating our servers to the new data center\"라고 했으므로 서버를 새 데이터센터로 옮기려 한다."},{"q":"Why does the man suggest a read-only mode?","choices":["To reduce the vendor's fees","To test the new data center","To protect the database from errors","To let customers check their orders"],"answer":3,"type":"세부 사항","explanation":"\"so they can at least check order status\"라고 했으므로 고객이 주문 상태라도 확인할 수 있게 하려는 것이다. 오히려 비용은 늘어난다."},{"q":"What will the man do?","choices":["Analyze traffic logs","Copy the database","Write a notice to customers","Contact the vendor"],"answer":2,"type":"다음 할 일","explanation":"\"I'll draft the customer notice\"라고 했다. 트래픽 로그 분석은 여자가 이미 했다."}],"translation":"W: 라제시, 업체에서 서버를 새 데이터센터로 옮기려면 약 8시간 중단이 필요하다고 확인해 줬어요.\nM: 8시간은 길어요. 우리 고객 포털은 밤사이 아시아 주문을 처리해서 사실상 한가한 시간대가 없어요.\nW: 트래픽 기록을 봤어요. 일요일 자정부터 오전 8시가 가장 낮아요. 평일 물량의 5분의 1 정도예요.\nM: 그래도 고객에게 훨씬 미리 알려야 해요. 포털을 읽기 전용 모드로 유지해서 최소한 주문 상태는 확인할 수 있게 할 수 있을까요?\nW: 업체 말로는 전날 데이터베이스를 복사해 두면 가능하대요. 비용이 좀 늘지만 그럴 가치가 있다고 봐요.\nM: 동의해요. 2주 전에 나갈 수 있게 고객 안내문 초안을 쓸게요.","part":3},{"id":"p3-136","level":5,"topic":"브랜드 리뉴얼 로고 시장 조사","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"The consumer panel results for the four logo concepts are in. Concept A was the clear favorite overall."},{"s":"W","t":"True, but look at the eighteen-to-thirty-four age group. That's the segment we're trying to win over with the rebrand."},{"s":"M","t":"Right. Among younger buyers, Concept A finished well behind the leader there."},{"s":"W","t":"Exactly. If the whole point is to attract a new generation, the overall average shouldn't decide it."},{"s":"M","t":"Still, the board is attached to the current color scheme, and the concept younger buyers liked most drops it entirely."},{"s":"W","t":"Then let's ask the agency to produce a version of that concept in our existing colors and test it again before the board meeting."}],"graphic":{"title":"Logo Concept Survey — Preference Score (out of 10)","rows":[["Concept","All Respondents","Ages 18-34"],["A","7.8","6.1"],["B","6.9","8.3"],["C","7.1","7.4"],["D","5.6","6.7"]]},"questions":[{"q":"What is the purpose of the rebrand?","choices":["To appeal to younger consumers","To reduce printing costs","To celebrate an anniversary","To enter a foreign market"],"answer":0,"type":"주제·목적","explanation":"18~34세가 \"the segment we're trying to win over with the rebrand\"이고 \"attract a new generation\"이 목적이라고 했다."},{"q":"Look at the graphic. Which concept will the agency be asked to revise?","choices":["Concept A","Concept B","Concept C","Concept D"],"answer":1,"type":"시각 자료 연계","explanation":"젊은 층이 가장 좋아한 시안을 기존 색상으로 다시 만들어 달라고 한다. 표의 18~34세 점수에서 가장 높은 것은 B(8.3)다. A는 전체 평균 1위일 뿐이다."},{"q":"Why might the board object to the younger buyers' favorite concept?","choices":["It is too expensive to produce.","It does not use the current colors.","It resembles a competitor's logo.","It scored poorly overall."],"answer":1,"type":"세부 사항","explanation":"이사회가 현재 색 구성을 아끼는데 그 시안은 \"drops it entirely\"라고 했으므로 현재 색을 쓰지 않는다는 점이 문제다."}],"translation":"M: 로고 시안 네 개에 대한 소비자 패널 결과가 나왔어요. 전체로는 A안이 확실한 1위였어요.\nW: 맞아요, 그런데 18~34세 그룹을 보세요. 이번 리브랜딩으로 끌어오려는 층이 거기잖아요.\nM: 그렇네요. 젊은 구매자 사이에서는 A안이 1위 시안에 한참 뒤졌어요.\nW: 바로 그거예요. 새로운 세대를 끌어들이는 게 핵심이라면 전체 평균으로 결정하면 안 돼요.\nM: 그래도 이사회는 지금 색 구성을 아끼는데, 젊은 층이 가장 좋아한 시안은 그걸 완전히 빼 버렸어요.\nW: 그럼 에이전시에 그 시안을 기존 색으로 만든 버전을 요청해서 이사회 전에 다시 테스트해요.","part":3},{"id":"p3-137","level":5,"topic":"인수 대상 기업 실사","speakers":{"M":"male","W":"female","W2":"female"},"script":[{"s":"M","t":"Let's review where we stand on the due diligence for Norvik Logistics. Any red flags so far?"},{"s":"W","t":"Their financial statements look solid, but about forty percent of their revenue comes from a single retail client, and that contract is up for renewal next spring."},{"s":"W2","t":"I've seen that in the legal review as well. The contract also allows the client to terminate if Norvik changes ownership."},{"s":"M","t":"That's significant. If the client walks away after the acquisition, we'd be overpaying by a wide margin."},{"s":"W2","t":"One option is to make part of the purchase price conditional on the contract being renewed."},{"s":"M","t":"Let's propose that. Helen, please draft the terms, and I'll raise it with Norvik's owners when we meet on Friday."}],"graphic":null,"questions":[{"q":"What concern does the woman raise about Norvik Logistics?","choices":["Its financial statements contain errors.","Its warehouses are outdated.","It depends heavily on one customer.","It has too many employees."],"answer":2,"type":"세부 사항","explanation":"수익의 약 40퍼센트가 한 소매 고객에게서 나온다고 했으므로 한 고객에 대한 의존도가 높다는 우려다. 재무제표는 견실하다고 했다."},{"q":"According to the legal review, what can the client do?","choices":["Raise its prices","Extend the contract automatically","Purchase Norvik itself","End the contract if ownership changes"],"answer":3,"type":"세부 사항","explanation":"\"allows the client to terminate if Norvik changes ownership\"라고 했다. terminate = end."},{"q":"What does the man ask Helen to do?","choices":["Draft some contract terms","Meet with Norvik's owners","Contact the retail client","Review the financial statements again"],"answer":0,"type":"요청·제안","explanation":"\"Helen, please draft the terms\"라고 했다. 헬렌은 조건부 대금 지급을 제안한 W2다. 노르빅 소유주와의 면담은 남자가 한다."}],"translation":"M: 노르빅 로지스틱스 실사가 어디까지 왔는지 점검합시다. 지금까지 위험 신호가 있나요?\nW: 재무제표는 견실해 보이는데, 매출의 40퍼센트 정도가 소매 고객 한 곳에서 나오고 그 계약이 내년 봄에 갱신 시점이에요.\nW2: 법률 검토에서도 봤어요. 그 계약에는 노르빅의 소유주가 바뀌면 고객이 해지할 수 있다는 조항도 있어요.\nM: 중대한 문제네요. 인수 후 그 고객이 떠나면 우리가 한참 비싸게 사는 셈이에요.\nW2: 한 가지 방법은 인수 대금 일부를 계약 갱신을 조건으로 지급하는 거예요.\nM: 그렇게 제안합시다. 헬렌, 조건 초안을 써 주세요. 금요일에 노르빅 소유주들을 만날 때 제가 이야기할게요.","part":3},{"id":"p3-138","level":5,"topic":"탄소 배출 공시 규정 대응","speakers":{"M":"male","W":"female"},"script":[{"s":"W","t":"Simon, have you read the new regulation on emissions reporting? Starting in two years, we'll have to disclose emissions from our suppliers, not just our own facilities."},{"s":"M","t":"I have. Honestly, most of our suppliers don't track that data at all."},{"s":"W","t":"Two years sounds like plenty of time."},{"s":"M","t":"It isn't, given that we have more than three hundred suppliers. We'd need to collect at least one full year of data before the first report."},{"s":"W","t":"Then we should start with the largest ones. The top twenty probably account for most of our purchasing."},{"s":"M","t":"About seventy percent, actually. I'll send them a questionnaire this month and set up a meeting with each of them."}],"graphic":null,"questions":[{"q":"What will the new regulation require?","choices":["Reducing factory emissions by half","Hiring an environmental officer","Reporting suppliers' emissions","Replacing older suppliers"],"answer":2,"type":"주제·목적","explanation":"\"we'll have to disclose emissions from our suppliers\"라고 했다. 감축 목표가 아니라 공시 의무다."},{"q":"What does the man mean when he says, \"It isn't\"?","choices":["The regulation does not apply to the company.","The deadline is not as far away as it seems.","The suppliers are not cooperative.","The report is not difficult to write."],"answer":1,"type":"의도 파악","explanation":"2년이면 충분하다는 여자 말을 부정한 것이다. 공급업체가 300곳이 넘고 첫 보고 전에 1년 치 데이터를 모아야 하므로 시간이 넉넉하지 않다는 뜻이다."},{"q":"What will the man do this month?","choices":["Send questionnaires to major suppliers","Publish an emissions report","Hire an outside consultant","Reduce the number of suppliers"],"answer":0,"type":"다음 할 일","explanation":"상위 20곳(구매의 70%)부터 시작하자는 말에 \"I'll send them a questionnaire this month\"라고 했다."}],"translation":"W: 사이먼, 배출량 보고에 관한 새 규정 읽어 봤어요? 2년 뒤부터는 우리 시설뿐 아니라 공급업체 배출량까지 공시해야 해요.\nM: 읽었어요. 솔직히 우리 공급업체 대부분은 그런 데이터를 전혀 관리하지 않아요.\nW: 2년이면 시간은 충분해 보이는데요.\nM: 그렇지 않아요. 공급업체가 300곳이 넘으니까요. 첫 보고서 전에 최소 1년 치 데이터를 모아야 해요.\nW: 그럼 가장 큰 곳부터 시작해야겠네요. 상위 20곳이 구매의 대부분을 차지할 거예요.\nM: 실제로 약 70퍼센트예요. 이번 달에 그곳들에 설문지를 보내고 한 곳씩 회의를 잡을게요.","part":3},{"id":"p3-139","level":5,"topic":"해외 출장 숙박비 규정 개정","speakers":{"M":"male","W":"female"},"script":[{"s":"M","t":"Diane, I've been reviewing our travel policy. The nightly hotel limits haven't been updated in four years, and rates have climbed sharply in several cities."},{"s":"W","t":"I've noticed that, too. Employees keep submitting exception requests, and approving each one takes my team hours every week."},{"s":"M","t":"The worst case is the city where our new regional office opened. Our limit there is less than two-thirds of what a standard business hotel costs now."},{"s":"W","t":"That explains why most of the requests come from that team. Let's raise the limit for that city first and review the others next quarter."},{"s":"M","t":"Sounds reasonable. I'd suggest setting it at the average rate plus ten percent."},{"s":"W","t":"Fine. Put it in writing, and I'll get the CFO's sign-off."}],"graphic":{"title":"Hotel Allowance per Night (Current Policy vs. Average Rate)","rows":[["City","Current Limit","Average Business Hotel Rate"],["Singapore","$220","$265"],["Frankfurt","$190","$210"],["Toronto","$180","$205"],["Seoul","$140","$230"]]},"questions":[{"q":"What problem does the woman mention?","choices":["Hotels are refusing corporate discounts.","Travel reports are submitted late.","Employees are traveling too often.","Handling exceptions takes a lot of time."],"answer":3,"type":"세부 사항","explanation":"예외 요청 승인에 \"takes my team hours every week\"라고 했으므로 예외 처리에 시간이 많이 든다는 문제다."},{"q":"Look at the graphic. In which city is the new regional office located?","choices":["Singapore","Frankfurt","Toronto","Seoul"],"answer":3,"type":"시각 자료 연계","explanation":"현재 한도가 평균 요금의 3분의 2에도 못 미치는 도시다. 서울은 140/230 ≈ 61%로 유일하게 3분의 2(약 67%) 미만이다. 싱가포르는 금액 차이가 크지만 비율로는 약 83%다."},{"q":"What will the woman do?","choices":["Book a hotel","Visit the regional office","Review all city limits immediately","Obtain approval from an executive"],"answer":3,"type":"다음 할 일","explanation":"\"I'll get the CFO's sign-off\"라고 했다. CFO = executive, sign-off = approval. 다른 도시는 다음 분기에 검토한다."}],"translation":"M: 다이앤, 출장 규정을 검토하고 있었어요. 1박 호텔 한도가 4년째 그대로인데 여러 도시에서 요금이 크게 올랐어요.\nW: 저도 알고 있었어요. 직원들이 예외 요청을 계속 올리고, 그걸 하나하나 승인하느라 우리 팀이 매주 몇 시간씩 써요.\nM: 가장 심한 곳은 새 지역 사무소가 문을 연 도시예요. 거기 한도는 지금 일반 비즈니스호텔 요금의 3분의 2도 안 돼요.\nW: 요청 대부분이 그 팀에서 오는 이유가 그거였군요. 그 도시 한도부터 올리고 나머지는 다음 분기에 검토해요.\nM: 합리적이네요. 평균 요금에 10퍼센트를 더한 수준으로 정하는 걸 제안해요.\nW: 좋아요. 문서로 정리해 주면 제가 CFO 승인을 받을게요.","part":3},{"id":"p3-140","level":5,"topic":"공동 연구 지적재산권 협상","speakers":{"W":"female","M":"male","M2":"male"},"script":[{"s":"W","t":"Thanks for joining us, Dr. Hale. We're close to finalizing the joint research agreement with your university, but the intellectual property clause is still open."},{"s":"M","t":"Yes. Our position is that any patents arising from the project should be jointly owned."},{"s":"M2","t":"We understand that. Our concern is that joint ownership can slow down commercialization, since every license would need both parties' consent."},{"s":"M","t":"Well, our researchers would also need to publish their findings."},{"s":"W","t":"We wouldn't want to stop that. What if the company held exclusive commercial rights, the university kept the right to publish after a ninety-day review period, and we shared royalties?"},{"s":"M","t":"That could work in principle. I'll need to discuss the royalty percentage with our technology transfer office, though."}],"graphic":null,"questions":[{"q":"What issue remains unresolved in the agreement?","choices":["The research schedule","Ownership of inventions","Laboratory access","The project budget"],"answer":1,"type":"주제·목적","explanation":"\"the intellectual property clause is still open\"이라고 했고 특허 소유를 두고 이야기하므로 발명(특허)의 소유권 문제다."},{"q":"Why does Dr. Hale say, \"our researchers would also need to publish their findings\"?","choices":["To explain a delay in the research","To agree to the company's proposal","To raise an additional requirement","To request more funding"],"answer":2,"type":"의도 파악","explanation":"상업화 속도를 걱정하는 회사 측 말에 대해 연구 결과 발표 권리라는 대학 측 요구 사항을 하나 더 제시한 것이다. 여자가 이를 반영해 90일 검토 후 발표안을 낸다."},{"q":"What does Dr. Hale say he needs to do?","choices":["Consult another office","Publish a paper","Sign the agreement","Review the patents"],"answer":0,"type":"다음 할 일","explanation":"\"I'll need to discuss the royalty percentage with our technology transfer office\"라고 했으므로 대학의 기술이전 부서와 상의해야 한다."}],"translation":"W: 함께해 주셔서 감사합니다, 헤일 박사님. 귀 대학과의 공동 연구 계약이 거의 마무리됐는데 지적재산권 조항이 아직 남아 있어요.\nM: 네. 저희 입장은 프로젝트에서 나오는 특허는 공동 소유여야 한다는 거예요.\nM2: 이해합니다. 저희가 걱정하는 건 공동 소유면 모든 라이선스에 양측 동의가 필요해서 상업화가 늦어질 수 있다는 점이에요.\nM: 음, 저희 연구원들은 연구 결과를 발표도 해야 하고요.\nW: 그걸 막을 생각은 없어요. 회사가 독점 상업화 권리를 갖고, 대학은 90일 검토 기간 후 발표할 권리를 유지하고, 로열티는 나누는 건 어떨까요?\nM: 원칙적으로는 가능할 것 같아요. 다만 로열티 비율은 저희 기술이전 사무소와 상의해야 해요.","part":3}];
